                            ["description"] = "这座雕像中的骨头、树枝和兽皮都得到了氏族中巫师的鲜血祝福。他们声称，这座雕像能将满怀恶意的灵魂送回人间，折磨他们曾经的主人。",
                            ["quality"] = "史诗",
                            ["id"] = 171391,
                        },
                        [171392] = 
                        {
                            ["category"] = "地下室",
                            ["name"] = "雪精灵统御图腾",
                            ["icon"] = "/esoui/art/icons/housing_skr_str_fmrtotemlarge001.dds",
                            ["subcategory"] = "象征性装饰",
                            ["description"] = "“对于那位写下‘我发现雪精灵用这种图腾来标记他们的领地’的学者，我还想问问更多这个臭气熏天的柱子和她口中雪精灵的情况。但她在日记中写下这篇文章后就死了，太不巧了。”——学者图恩塔泰尔",
                            ["quality"] = "上乘",
                            ["id"] = 171392,
                        },
                        [171393] = 
                        {
                            ["category"] = "地下室",
                            ["name"] = "树（瑞驰图腾树木）",
                            ["icon"] = "/esoui/art/icons/housing_skr_ext_rchforteffigy002.dds",
                            ["subcategory"] = "象征性装饰",
                            ["description"] = "“头顶之上，四肢伸向天空；脚踩之下，根须遍布大地。在这棵树上的二者交汇处，放置你的骨头祭品。每次雨后都用油将其浇灌，否则树之魂将为你带来灭亡。”——瑞驰女巫伊欧内尔根",
                            ["quality"] = "上乘",
                            ["id"] = 171393,
                        },
                        [171394] = 
                        {
                            ["tags"] = "照明用具, 可交互, 视觉特效",
                            ["category"] = "照明",
                            ["name"] = "矮人展台（虚无水晶）",
                            ["icon"] = "/esoui/art/icons/housing_skr_inc_voidpocketshard001.dds",
                            ["subcategory"] = "魔灯",
                            ["description"] = "“的确，我喜欢亮闪闪的东西。鉴于我在守卫中度过的时间，咳咳，可能有点喜欢过头了。但这块石头中的某些东西让我感到不安。那些古怪的矮人用它来做什么的？”——矮人遗迹探索者戈瑟斯",
                            ["quality"] = "传说",
                            ["id"] = 171394,
                        },
                        [171395] = 
                        {
                            ["category"] = "工坊",
                            ["name"] = "矮人信标（以太）",
                            ["icon"] = "/esoui/art/icons/housing_skr_lsb_markaethericbeacon001.dds",
                            ["subcategory"] = "机械",
                            ["description"] = "“以大衮火热的屁股为证，这个矮人装置中的以太石根本不会动。它们有什么用？我不在乎。但碍于禅宗的名义，我还不能把这整块金属拖走。呃。”——矮人遗迹探索者戈瑟斯",
                            ["quality"] = "传说",
                            ["id"] = 171395,
                        },
                        [171396] = 
                        {
                            ["category"] = "工坊",
                            ["name"] = "矮人音场镣铐",
                            ["icon"] = "/esoui/art/icons/housing_skr_inc_markmanacle001.dds",
                            ["subcategory"] = "机械",
                            ["description"] = "“这条花哨的矮人束链……之类的。相信我，我对束链很了解。可以在五十步开外的守卫身上闻出它们的气味。但这东西弥漫着诸如束链……镣铐之类的东西，还是离远点吧。”——矮人遗迹探索者戈瑟斯",
