                            ["description"] = "从孵化出来那一刻起，小查鲁斯学习指令的能力就很强。有人认为，在心口放一个蛋能让它对你产生依恋，不那么容易走丢，以致去祸害其他人。",
                            ["name"] = "微型茶杯查鲁斯",
                            ["id"] = 8199,
                        },
                        [8200] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7236,
                            ["icon"] = "/esoui/art/icons/pet_boarvariant.dds",
                            ["hint"] = "",
                            ["description"] = "这些家养野猪有着银色的皮和深灰色的条纹，它们曾在卡斯威斯腾自由狂奔。它们挨不了饿，所以很适合那些容易睡过头的人。没有什么比野猪在耳边嚎更能把人叫醒了！",
                            ["name"] = "卡斯威斯腾银野猪",
                            ["id"] = 8200,
