                            ["description"] = "“人们有时会厌倦人性的重担，因此我买了这头死亡猎犬。这导致我不能进入大多数酒馆，不过也没人侵扰我的私人空间了。”——探险家赛尔迪恩·费登",
                            ["name"] = "死亡猎犬",
                            ["id"] = 6443,
                        },
                        [6444] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5992,
                            ["icon"] = "/esoui/art/icons/pet_vampiricdragonimp.dds",
                            ["hint"] = "",
                            ["description"] = "这只小恶魔，从吸血鬼关的笼子中释放了自己，现在可以加入你的旅程。它很容易受到惊吓，经常会变成吸血鬼的龙形，希望看起来比它本身更凶猛。",
                            ["name"] = "吸血鬼龙小恶魔",
                            ["id"] = 6444,
                        },
                        [6445] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5993,
                            ["icon"] = "/esoui/art/icons/pet_newmoonwolf.dds",
                            ["hint"] = "",
                            ["description"] = "新月教的幼崽还没有完全从他们的朝气中长大，这使它们成为有趣的旅行伙伴。它们经常跟踪影子，并试图摧毁它们。",
                            ["name"] = "新月狼幼崽",
