                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5994,
                            ["icon"] = "/esoui/art/icons/pet_newmoonsenche.dds",
                            ["hint"] = "",
                            ["description"] = "虽然这只幼崽穿着新月教的标志性护套，但它的行为就像一只小猫。也就是说，你可能需要训练它，以避免它用头和搔痒的护甲摩擦你的脸颊。",
                            ["name"] = "新月森切幼崽",
                            ["id"] = 6446,
                        },
                        [6447] = 
                        {
                            ["category"] = "异域",
