                            ["icon"] = "/esoui/art/icons/pet_newmoonhorse.dds",
                            ["hint"] = "",
                            ["description"] = "一小撮大胆的商人从新月教派那里偷了一些驮兽，他们声称这些小马和山羊一样灵活，甚至可以爬树。苹果园的果农们要小心了!",
                            ["name"] = "新月小马",
                            ["id"] = 6447,
                        },
