                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5996,
                            ["icon"] = "/esoui/art/icons/pet_newmoonguar.dds",
                            ["hint"] = "",
                            ["description"] = "新月教派周围有许多不同的生物，包括瓜尔。由于其繁殖的特殊性，这只瓜尔每当听到有人唱歌时就会试图跟着唱。然而，只有狗能听到它这样做。",
                            ["name"] = "新月瓜尔幼崽",
                            ["id"] = 6448,
                        },
                        [6449] = 
                        {
