                            ["icon"] = "/esoui/art/icons/pet_newmoonbear.dds",
                            ["hint"] = "",
                            ["description"] = "只要你喂得饱饱的，这只新月教的幼崽就会高高兴兴地跟在你身后。",
                            ["name"] = "新月熊幼崽",
                            ["id"] = 6449,
                        },
                        [6450] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5998,
                            ["icon"] = "/esoui/art/icons/pet_coldsnapdurzogpup.dds",
                            ["hint"] = "",
                            ["description"] = "从冰袭哥布林部落获得的年轻地精犬性情暴躁，需要强硬的手段来驯服。当你和这个生物建立了牢固的联系后，它将展现出无比的忠诚。",
                            ["name"] = "冰袭地精犬幼崽",
                            ["id"] = 6450,
                        },
                        [6451] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5999,
                            ["icon"] = "/esoui/art/icons/pocketwatcher.dds",
                            ["hint"] = "",
                            ["description"] = "有些人把所谓的袖珍眼魔当宠物饲养，用它们在沃斯加看到的袖珍猛犸象给他们命名。如果稍微小一点的呢？还是不太明智，毕竟再小的魔族也还是魔族，这超出了我们的认知范围。“——法士艾尔达",
                            ["name"] = "袖珍恶眼魔",
                            ["id"] = 6451,
                        },
                        [6452] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 6000,
                            ["icon"] = "/esoui/art/icons/pet_grislybanekinmummy.dds",
                            ["hint"] = "",
                            ["description"] = "包着布条，戴着吓人的面具的恐怖灾星木乃伊会在旅途中全程陪伴着你，它会让所有看到它的人感到无尽的恐惧！",
                            ["name"] = "恐惧灾星木乃伊",
                            ["id"] = 6452,
                        },
                        [6453] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6001,
                            ["icon"] = "/esoui/art/icons/pet_radiantdraghuntt2.dds",
                            ["hint"] = "",
                            ["description"] = "\"这只幼崽在龙的攻击之下活了下来，在所有弑龙者面前证明了自己。它坚韧的性格应该能拯救你的生命。\"——贾维达，弑龙者",
                            ["name"] = "恐惧刺壳弑龙之狼",
                            ["id"] = 6453,
                        },
                        [6454] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 6002,
                            ["icon"] = "/esoui/art/icons/pet_mindshrivenscamp.dds",
                            ["hint"] = "",
                            ["description"] = "“失心傀儡小鬼是一种不寻常的生物。通常情况下，你会发现它们与其他失心傀儡的生物混在一起，但一些糊涂的人已经把它们视为自己的随从了。往好听了说，这种情况还真是奇怪。“——法士艾尔达",
                            ["name"] = "失心傀儡小鬼",
                            ["id"] = 6454,
                        },
                        [6455] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6003,
                            ["icon"] = "/esoui/art/icons/pet_witchesinfernal.dds",
                            ["hint"] = "",
                            ["description"] = "这只黑猫戴着一顶帽子，在你身边的世界旁徘徊着，留下了小小的火爪印。",
                            ["name"] = "巫师地狱魔宠",
                            ["id"] = 6455,
                        },
                        [6456] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6004,
                            ["icon"] = "/esoui/art/icons/pet_ancientdraghuntt2.dds",
                            ["hint"] = "",
                            ["description"] = "这只狼能预知到龙的到来，这使它成为了一种优秀的宠物，同时也是个经验丰富的龙之猎手。",
                            ["name"] = "古龙猎人狼",
                            ["id"] = 6456,
                        },
                        [313] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 4264,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_e.dds",
                            ["hint"] = "",
                            ["description"] = "在艾斯维尔，白狮被认为是非常有威望的坐骑。基尔戈王迎娶艾诗塔王后时，他那二十名强壮的兽人栖所荣耀守卫就都骑着成年的白狮。",
                            ["name"] = "白狮",
                            ["id"] = 313,
                        },
                        [6458] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 6005,
                            ["icon"] = "/esoui/art/icons/pet_undauntedporterscamp.dds",
                            ["hint"] = "通过达成“月墓古庙征服者”成就获得。",
                            ["description"] = "“啊，是的，无畏者。他们决定训练小鬼背上背包，可以说是一项了不起的事业。我很想看看有多少装备会丢失。”——法士艾尔达",
                            ["name"] = "无畏者背包小鬼",
                            ["id"] = 6458,
                        },
                        [8507] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 7335,
                            ["icon"] = "/esoui/art/icons/pet_bunnyvariant.dds",
                            ["hint"] = "",
                            ["description"] = "一些瑞驰氏族喜欢养这些毛茸茸的小家伙作为同伴，还会对胆敢伤害它们的人展开报复。这种生物很喜欢被人抚摸，还常常会趴在自己伴侣的脖子上睡觉。当然，这种说法的真实性无从考证。",
                            ["name"] = "卡斯之矛家兔",
                            ["id"] = 8507,
                        },
                        [8508] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7336,
                            ["icon"] = "/esoui/art/icons/mount_radalyeidhorse.dds",
                            ["hint"] = "",
                            ["description"] = "“根据我听到的说法，如果怀孕的母马在一场持久的仪式中受到维尔金石浸染，它就会生下这种马。此外，在奈纳拉塔人撤离期间，他们还带走了能使这些马不知疲倦的发光护甲。”——昭示者贝尔达默",
                            ["name"] = "维尔金降生骏马",
                            ["id"] = 8508,
                        },
                        [8509] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7337,
                            ["icon"] = "/esoui/art/icons/mount_radayleidsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“这匹坐骑身上的光芒不仅仅来自那蕴含库兰达能量的驮具，更是那驮具与坐骑互相影响的结果。根据多份奈纳拉塔野精灵的记载，库兰达融入了这种森切的血液，带给了它令人羡慕的优雅。”——昭示者贝尔达默",
                            ["name"] = "库兰达森切",
                            ["id"] = 8509,
                        },
                        [8510] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 7338,
                            ["icon"] = "/esoui/art/icons/mount_varlabornwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“当骑手给受瓦尔拉浸染过的狼戴上瓦尔拉石制成的驮具时，这些狼所发出的诡异光芒（奈纳拉塔人就是这么说的）就会变得更加耀眼。尽管这种坐骑全身闪烁着蓝光，但其稳健的步伐还是让很多人无法注意到它。”——昭示者贝尔达默",
                            ["name"] = "瓦尔拉狼",
                            ["id"] = 8510,
                        },
                        [6463] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6010,
                            ["icon"] = "/esoui/art/icons/mount_grislyhorsemummy.dds",
                            ["hint"] = "",
                            ["description"] = "带着这匹木乃伊坐骑入场吧！它拥有着古老的外表和神圣的马饰，这匹可怕的马能为一切幽灵游行和集会带来一股恰到好处的怪异感。",
                            ["name"] = "恐惧木乃伊马",
                            ["id"] = 6463,
                        },
                        [8512] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 7340,
                            ["icon"] = "/esoui/art/icons/mount_groupmountu29.dds",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t多人坐骑（1个操控者，1个乘客）|r|",
                            ["description"] = "“需要一头不会吃光你家底的坐骑吗？给两人用？好吧，这个银色的矮人蜘蛛坐骑可以同时满足这两方面的需求！也不要担心它会失去光泽。它会一直闪闪发光，直到世界的尽头。”——马厩主迪巴斯",
                            ["name"] = "双座银白蜘蛛",
                            ["id"] = 8512,
                        },
                        [6465] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6012,
                            ["icon"] = "/esoui/art/icons/mount_siegemasterswarhorse.dds",
                            ["hint"] = "",
                            ["description"] = "就像那些防止敌人征服它们的坚固的要塞堡垒，这匹战马被加固以防止敌人迅速将其击倒。骑着这匹巨大的坐骑去围攻对方的军队并占领他们的阵地吧！",
                            ["name"] = "攻城大师战马",
                            ["id"] = 6465,
                        },
                        [8514] = 
                        {
                            ["category"] = "尼克斯牛虫",
                            ["furnitureId"] = 7342,
                            ["icon"] = "/esoui/art/icons/mount_nixoxvariantwhite.dds",
                            ["hint"] = "",
                            ["description"] = "这种较轻的尼克斯牛虫最初由阿赫穆萨灰原部落驯服，直到最近才受部落以外的人差遣。事实上，一些在天际的冬季旅行的骑手注意到，这种尼克斯牛虫喜欢在雪中蹦蹦跳跳。",
                            ["name"] = "查勒缝合尼克斯牛虫战骑",
                            ["id"] = 8514,
                        },
                        [8515] = 
                        {
                            ["category"] = "公羊",
                            ["furnitureId"] = 7343,
                            ["icon"] = "/esoui/art/icons/mount_ramvarient.dds",
                            ["hint"] = "",
                            ["description"] = "它比其他公羊更温顺，即使在最具挑战性的山地地形中，这种坐骑也能提供稳定的乘坐。事实上，一些风盔城当地居民声称他们在冬天只会骑着这种坐骑穿越山谷。",
                            ["name"] = "风盔城悬崖公羊",
                            ["id"] = 8515,
                        },
                        [8516] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7344,
                            ["icon"] = "/esoui/art/icons/mount_pellitinescorchsenche.dds",
                            ["hint"] = "",
                            ["description"] = "在森查尔和周边地区的大火之后，几群森切狮搬进了该地区。大胆而绝望的虎人训练了这些无畏的生物戴上鞍具，希望能增强他们的力量对抗致命的龙。",
                            ["name"] = "佩利汀烈火森切狮",
                            ["id"] = 8516,
                        },
                        [8517] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7345,
                            ["icon"] = "/esoui/art/icons/mount_silverdawnhorse2.dds",
                            ["hint"] = "",
                            ["description"] = "这匹悲伤的银色黎明战马失去了它的骑手，也失去了它生存的目的。现在，它在寻找一个新的伙伴。只要你想寻找值得击败的敌人，这匹骄傲的战马就会听从你的召唤。",
                            ["name"] = "黎明复仇者军马",
                            ["id"] = 8517,
                        },
                        [8518] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 7346,
                            ["icon"] = "/esoui/art/icons/mount_u29ceelk.dds",
                            ["hint"] = "",
                            ["description"] = "“在法林奈斯提战役中，几群木精灵图腾麋鹿消失了——有人说是虎人恶棍搞的鬼。后来，法林奈斯提忠信团重新获得了它们，并将它们送给了虔诚的骑士。什么样的人才能算作虔诚的骑士？问他们吧。”——弗拉克斯·特伦提斯",
                            ["name"] = "法林奈斯提的忠信图腾麋鹿",
                            ["id"] = 8518,
                        },
                        [8519] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 7347,
                            ["icon"] = "/esoui/art/icons/mount_meridianwolf.dds",
                            ["hint"] = "",
                            ["description"] = "协助奥罗兰人的美瑞蒂亚信徒可以获得足够的青睐，从而获得他们的一匹狼坐骑。这些狼受过战争训练，即使遭遇围攻也能坚持到底，故而成为各种危险情况下的优秀坐骑。",
                            ["name"] = "奥罗兰顶峰战狼",
                            ["id"] = 8519,
                        },
                        [8520] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7348,
                            ["icon"] = "/esoui/art/icons/pet_ayleidwolfpup.dds",
                            ["hint"] = "",
                            ["description"] = "“在撤离奈纳拉塔的过程中，身着铠甲的狼崽们一直在与一只狂怒的熊搏斗，直到有战士将其打倒。这些幼崽在休息时还会帮它们的野精灵主人保暖。它们是凶猛但可爱的小动物。”——指引者贝尔达默",
                            ["name"] = "奈纳拉塔野精灵狼幼崽",
                            ["id"] = 8520,
                        },
                        [8521] = 
                        {
                            ["category"] = "森切战猫",
                            ["furnitureId"] = 7349,
                            ["icon"] = "/esoui/art/icons/mount_dunewalkersencheraht.dds",
                            ["hint"] = "",
                            ["description"] = "沙丘行者曾漫游在艾斯维尔以外的沙漠，在其他土地的沙地中探求知识。米吉拉想要重拾传统，希望能借此带回如何彻底击败龙的信息。你会协助她吗？",
                            ["name"] = "沙丘行者森切战猫",
                            ["id"] = 8521,
                        },
                        [8522] = 
                        {
                            ["category"] = "森切战猫",
                            ["furnitureId"] = 7350,
                            ["icon"] = "/esoui/art/icons/mount_queenssencheraht.dds",
                            ["hint"] = "",
                            ["description"] = "多年的竞速比赛冠军终于让哈扎兹卡兰厌烦了，所以它给女王送了一段时间的信。唉，就连这一点也变得无聊了。现在它想探索世界上所有隐秘的角落——也许和你一起。",
                            ["name"] = "斑点沙丘竞速森切战猫",
                            ["id"] = 8522,
                        },
                        [8523] = 
                        {
                            ["category"] = "四目兽",
                            ["furnitureId"] = 7351,
                            ["icon"] = "/esoui/art/icons/mount_welwavariant.dds",
                            ["hint"] = "",
                            ["description"] = "“德雷曼肯是一种可怕的生物，它们有着能够捣碎一切的脚垫以及只能带来痛苦的锯齿状牙齿。任何有能力给它们披上护甲并骑着它们战斗的人都应该受到加倍的敬畏。这也是合乎逻辑的。”——阿里诺尔魔族学会的诺罗利",
                            ["name"] = "德雷曼肯怒兽",
                            ["id"] = 8523,
                        },
                        [8525] = 
                        {
                            ["category"] = "公羊",
                            ["furnitureId"] = 7353,
                            ["icon"] = "/esoui/art/icons/mount_whitefallram.dds",
                            ["hint"] = "",
                            ["description"] = "巨人宣称白秋地区是他们的地盘之后，这些暗色条纹的公羊就迁移到了天际，在那里，诺德人训练它们佩戴鞍具。虽然它们经常撞到自己的脑袋，但驯服后，你找不到一个比它更忠诚的坐骑了。",
                            ["name"] = "白秋内陆公羊",
                            ["id"] = 8525,
                        },
                        [8526] = 
                        {
                            ["category"] = "尼克斯牛虫",
                            ["furnitureId"] = 7354,
                            ["icon"] = "/esoui/art/icons/mount_nixoxvariant1.dds",
                            ["hint"] = "",
                            ["description"] = "一些学者说，这只尼克斯牛虫身上怪异的蓝色标记是由曾经从缪莱夫特发出的奇怪能量造成的。当地人声称现在已经不存在这样的能量了，并立即把话题转向了坐骑的耐力和适应能力。",
                            ["name"] = "大衮尼克斯牛虫战骑",
                            ["id"] = 8526,
                        },
                        [8527] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 7355,
                            ["icon"] = "/esoui/art/icons/mount_bullkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "在公牛盾角蜥攻击之前，橙色和红色的闪光可以让任何人心惊——除非你是骑着这个吓人的坐骑进入战斗！接受这个生物的凶猛，但也要准备好当你抓它的鼻子时它可爱的咕咕声。",
                            ["name"] = "公牛盾角蜥冲锋战骑",
