                            ["icon"] = "/esoui/art/icons/pet_linchaltitanfox.dds",
                            ["hint"] = "",
                            ["description"] = "这种橙黑相间的生物虽然很怕生，但它顽强地捍卫着自己的巢穴，林查尔堡的建造者在记录中写道。他们驯服了那些在建筑过程中被转移的狐狸，然后把它们带回了帝都，取悦了许多贵族。",
                            ["name"] = "林查尔巨狐",
                            ["id"] = 8532,
                        },
                        [8533] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 7361,
                            ["icon"] = "/esoui/art/icons/pet_bunnyvariantu29.dds",
                            ["hint"] = "",
                            ["description"] = "一些木精灵织歌者声称，耶弗尔承认这些兔子是翠林公约的一部分；学者们却争辩说，第二帝都在建立木炉城时带来了这些兔子，然后，这些兔子就自然而然地繁衍生息开来了。这些跳跳兔是很棒的毛茸茸的朋友！",
                            ["name"] = "木炉城棕兔子",
                            ["id"] = 8533,
                        },
                        [8534] = 
                        {
                            ["category"] = "异域",
