                        {
                            ["category"] = "马",
                            ["furnitureId"] = 4273,
                            ["icon"] = "/esoui/art/icons/mount_icon_alliance_horse_a.dds",
                            ["hint"] = "",
                            ["description"] = "三大联盟竞相为各自的装甲骑兵培育最强壮和最雄伟的战马，这并不让人惊讶。\r\n|cFFFFFF\r\n外观取决于你角色所在的联盟。\r\n\r\n骑术技能不会影响该坐骑的外观。|r",
                            ["name"] = "联盟战马",
                            ["id"] = 365,
                        },
                        [10606] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 8554,
                            ["icon"] = "/esoui/art/icons/pet_nagastanicooncat.dds",
                            ["hint"] = "",
                            ["description"] = "“上一季愤怒的松鼠毁掉了我的商品，但也唤来了这只小救星。它是擅长捕捉啮齿动物、蛾子和其他害虫的猎人，我会接受任何提供给我的帮助。”—克罗普斯福特的阿扎塔",
                            ["name"] = "哈特兰库恩猫",
                            ["id"] = 10606,
                        },
                        [10609] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8555,
                            ["icon"] = "/esoui/art/icons/pet_queenayrenngryphon.dds",
                            ["hint"] = "",
                            ["description"] = "“这件来自王室动物园管理员的神奇礼物让我喜出望外。我希望无论在哪里，这个可爱的小家伙都能找到温暖的家庭和关心它的人。”—艾瑞恩女王",
                            ["name"] = "艾瑞恩狮鹫幼雏",
                            ["id"] = 10609,
                        },
                        [12658] = 
                        {
                            ["category"] = "矮人蜘蛛",
                            ["furnitureId"] = 10118,
                            ["icon"] = "/esoui/art/icons/mount_glassatronachspider.dds",
                            ["hint"] = "",
                            ["description"] = "“为了追寻更为神秘的材料，我使用了最奇异的界域丝线。镜片碎片无穷无尽，延伸至地平线之外。整个地方弥漫着最深沉的失落之感。”——蛛铁匠的日记",
                            ["name"] = "琉璃侍灵矮人蜘蛛",
                            ["id"] = 12658,
                        },
                        [12659] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 10119,
                            ["icon"] = "/esoui/art/icons/pet_goldeneagle.dds",
                            ["hint"] = "",
                            ["description"] = "“这些雄伟的猛禽是出色的猎手，它们能从高空发现猎物，然后悄无声息地俯冲猎杀。这样的能力让它们深受猎人和贵族的青睐。”——《羽翼生灵》（译本）",
                            ["name"] = "金鹰",
                            ["id"] = 12659,
                        },
                        [12660] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 10120,
                            ["icon"] = "/esoui/art/icons/mnt_lionguardcaptainssteed.dds",
                            ["hint"] = "",
                            ["description"] = "“她是陪同我历经每一场战斗的忠实坐骑。从未失过蹄。当然，我们也有过不少险象环生的时刻，但每次我以为我们要完蛋的时候，她总能找到一条狭窄的出路，而我们就这样一路走到了现在。”——莫雷队长",
                            ["name"] = "10周年雄狮卫骏马",
                            ["id"] = 12660,
                        },
                        [12661] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 10121,
                            ["icon"] = "/esoui/art/icons/mount_spiritwalkerpillionelk.dds",
                            ["hint"] = "",
                            ["description"] = "“麋鹿比马匹更温顺，比骆驼更可靠，是穿越泰姆瑞尔森林的首选坐骑。它们威严的姿态为骑手提供了极佳的视野，同时又不会特别显眼。”——稳健之蹄：麋鹿之旅",
                            ["name"] = "灵魂行者双骑麋鹿",
                            ["id"] = 12661,
                        },
                        [12662] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 10122,
                            ["icon"] = "/esoui/art/icons/mount_blackfredaspillionwalker.dds",
                            ["hint"] = "",
                            ["description"] = "当这匹漆黑的骏马驰入城中时，麻烦也就成倍增加。这匹“黑色星期五”的战马会带来超量坏消息，是“祸不单行”这句古老格言的鲜活实例。",
                            ["name"] = "黑色星期五双骑行者",
