                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 8557,
                            ["icon"] = "/esoui/art/icons/mount_lightlesscamel.dds",
                            ["hint"] = "",
                            ["description"] = "在爬上这些色彩斑斓的骆驼之前，那些崇敬鲁普特加的人会跪在坐骑的阴影下，祈求旅途平安。一些人专注于眼前的旅程，而另一些人则希望能在死后被指引到遥远海岸。",
