                        [12730] = 
                        {
                            ["category"] = "特殊",
                            ["furnitureId"] = 10160,
                            ["icon"] = "/esoui/art/icons/mount_sanguinegargoyle.dds",
                            ["hint"] = "",
                            ["description"] = "“血酒浇石，魔力交织。供狂欢魔神飨食，狂欢魔神唤醒你。”——桑吉恩唤石仪式（片段）",
                            ["name"] = "桑吉恩石像鬼",
                            ["id"] = 12730,
                        },
                        [443] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 4289,
                            ["icon"] = "/esoui/art/icons/mounticon_guar_e.dds",
                            ["hint"] = "",
                            ["description"] = "在黑沼泽，这头坐骑被称为鳞片·似乎·涂满了·希思特·汁液，但泰姆瑞尔的其他人只称它为希思特瓜尔。它是目前已知的唯一喜欢音乐的瓜尔亚种。",
                            ["name"] = "希思特瓜尔",
                            ["id"] = 443,
                        },
                        [12734] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 10214,
                            ["icon"] = "/esoui/art/icons/mount_windkeepbear.dds",
                            ["hint"] = "",
                            ["description"] = "狂风要塞的山峦连绵起伏却又安宁祥静，难怪这种奇特的熊会在这里安家。由于鲜有自然天敌，这种野兽性情温顺，很讨骑手们的喜爱。",
                            ["name"] = "狂风要塞熊",
                            ["id"] = 12734,
                        },
                        [12735] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 10215,
                            ["icon"] = "/esoui/art/icons/mount_orsiniumtigerlynx.dds",
                            ["hint"] = "",
                            ["description"] = "“把它喂饱，你就什么都不用担心。这种动物很聪明，知道跟着你有饭吃，就不会挠你或者逃跑。不过进了山里可要当心你的口粮，毕竟它在雪地里基本等同于隐形。”——马夫斯卡古恩",
                            ["name"] = "霜断猞猁虎",
                            ["id"] = 12735,
                        },
                        [12736] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 10216,
                            ["icon"] = "/esoui/art/icons/mount_threebannersveteranwolf.dds",
                            ["hint"] = "",
                            ["description"] = "这种狼久经沙场，战争与血腥只会让它变得更加强大。它骄傲地扛起自己的辉煌战绩，身上披着旗帜——或来自殒命的敌人，或来自高贵的盟友。无论是谁想挑战这头猛兽背上的骑手，都最好三思而后行。",
                            ["name"] = "三旗老兵之狼",
                            ["id"] = 12736,
                        },
                        [12737] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10217,
                            ["icon"] = "/esoui/art/icons/pet_karthriverbristleback.dds",
                            ["hint"] = "",
                            ["description"] = "“这种刚鬣猪的皮毛比寻常品种还厚，脾气也好不到哪儿去，甚至还更暴躁！听说弃誓者会跟它们搏斗来挑战自我、彰显自己的勇猛。我倒觉得他们是疯了！”——饲养员米特",
                            ["name"] = "卡斯河刚鬣猪",
                            ["id"] = 12737,
                        },
                        [12738] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 10218,
                            ["icon"] = "/esoui/art/icons/mount_allianceaccordssteed.dds",
                            ["hint"] = "",
                            ["description"] = "这头熊对自己的主人忠心耿耿，其他人胆敢靠近就要遭受它的咆哮和撕咬。面对和自己出生入死的骑手时，它的性情颇为温和，经常自己跑去用鼻子翻找包里的零食。",
                            ["name"] = "周年益友熊",
                            ["id"] = 12738,
                        },
                        [12739] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10219,
                            ["icon"] = "/esoui/art/icons/pet_orsiniumtigerlynxcub.dds",
                            ["hint"] = "",
                            ["description"] = "“家乡被洗劫一空，我们无路可走，只能在外流浪。可这头猞猁虎宁愿跟着我吃苦，也不愿自己去过更好的生活。所以为了它，我也要继续战斗。”——匕落士兵莫格罗格",
                            ["name"] = "奥辛纽姆猞猁虎幼崽",
                            ["id"] = 12739,
                        },
