                            ["icon"] = "/esoui/art/icons/pet_senchalharbormutt.dds",
                            ["hint"] = "",
                            ["description"] = "这只混种犬身披金色的皮毛，嗅觉灵敏，对任何喂养它并善待它的人都很忠诚。你是那个能让这只狗摆脱在森查尔码头乞讨生活的恩人吗？",
                            ["name"] = "森查尔港土狗",
                            ["id"] = 6620,
                        },
                        [477] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 4292,
                            ["icon"] = "/esoui/art/icons/pet_075.dds",
                            ["hint"] = "",
                            ["description"] = "荒地猞猁，又名野地猞猁，原生于泰姆瑞尔中南部，游荡于艾斯维尔的寇林瑟与北方西罗帝尔的西威尔德之间的草原之中。它是许多虎人游牧部落的图腾动物，并用以协助管理牧群。",
                            ["name"] = "荒地猞猁",
                            ["id"] = 477,
                        },
                        [6622] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6340,
                            ["icon"] = "/esoui/art/icons/pet_fawn.dds",
                            ["hint"] = "",
                            ["description"] = "这只小鹿敏捷地粘在你身边，就像你是它的妈妈一样。可爱吗？噢，当然。看看它的眼睛！鼻子！那些斑点！",
                            ["name"] = "小斑点鹿",
                            ["id"] = 6622,
                        },
                        [6623] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6341,
                            ["icon"] = "/esoui/art/icons/pet_frostwolfpup.dds",
                            ["hint"] = "",
                            ["description"] = "这只小狼不玩简单的取物游戏，但它会忠诚地跟随你一同冒险。不仅如此，只要你让它蜷缩在你的身上，它就能为你带来一丝凉爽。它处世冰冷，但实用又可爱。",
                            ["name"] = "寒霜侍灵狼幼崽",
                            ["id"] = 6623,
                        },
                        [6624] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6342,
                            ["icon"] = "/esoui/art/icons/pet_frostsenchecub.dds",
                            ["hint"] = "",
                            ["description"] = "有些人会选择边缘锋利、没有皮毛的森切幼崽，但你和他们不一样！事实上，在你于沙漠中跋涉时，每当它用凉爽的爪子拱你时，你都能感到一阵惬意。",
                            ["name"] = "寒霜侍灵森切幼崽",
                            ["id"] = 6624,
                        },
                        [6625] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6343,
                            ["icon"] = "/esoui/art/icons/pet_frostpony.dds",
                            ["hint"] = "",
                            ["description"] = "小马对你来说太可爱了吗？别怕！这匹小马很可爱，也很冷酷，仿佛在暗示“别想摸我的鼻子”。对于那些怕热的人来说，它是一个不错的同伴！",
                            ["name"] = "寒霜侍灵小马",
                            ["id"] = 6625,
                        },
                        [6626] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6344,
                            ["icon"] = "/esoui/art/icons/pet_frostkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "这个同伴是幼崽形态的寒霜侍灵盾角蜥，它以冰冷的方式体现了瓦登费尔荒野的本质，它是英雄们在该地区寻求阻止威胁的有趣选择。然而，当地的暗精灵可能会用怀疑的眼光看待你。",
                            ["name"] = "寒霜侍灵盾角蜥幼崽",
                            ["id"] = 6626,
                        },
                        [6627] = 
                        {
                            ["category"] = "非战斗宠物",
                            ["furnitureId"] = 6345,
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["hint"] = "",
                            ["description"] = "模板描述",
                            ["name"] = "龙卫猫",
                            ["id"] = 6627,
                        },
                        [6628] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6346,
                            ["icon"] = "/esoui/art/icons/pet_jadecrowndragonslayerwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“作为最凶猛的弑龙狼，这只狼的眼睛闪烁着坚定的绿光，即使面对最具威严的龙，它也始终陪伴在主人身边。”——弑龙者贾文达",
                            ["name"] = "翡翠王冠屠龙狼",
                            ["id"] = 6628,
                        },
                        [6629] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 6347,
                            ["icon"] = "/esoui/art/icons/pet_avalancedog.dds",
                            ["hint"] = "",
                            ["description"] = "有这只忠诚的狗做你的同伴，即使是在苍白密道和其他山区发生最危险的雪崩时，它也能帮你度过难关，即使这需要它把你从雪堆和碎石下拉出来。",
                            ["name"] = "安瑟布瑞德雪崩犬",
                            ["id"] = 6629,
                        },
                        [6630] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6348,
                            ["icon"] = "/esoui/art/icons/pet_frostbearcub.dds",
                            ["hint"] = "",
                            ["description"] = "你不需要掌握召唤魔法就能有一个侍灵同伴——第仁尼氏族的法师们把来自那个地方的熊幼崽送给了他们认为有价值的人。尽管它们看起来很冷，但奇怪的是，它们却可以温暖人心。",
                            ["name"] = "寒霜侍灵熊幼崽",
                            ["id"] = 6630,
                        },
                        [6631] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6349,
                            ["icon"] = "/esoui/art/icons/pet_legenddragwolf.dds",
                            ["hint"] = "",
                            ["description"] = "这只狼与龙战斗的经验超过了许多猎龙人，而且它还选择站在了你的这边！真是天作之合。",
                            ["name"] = "传说之龙狼",
                            ["id"] = 6631,
                        },
                        [12777] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 10236,
                            ["icon"] = "/esoui/art/icons/mount_carnavalefeatheredguar.dds",
                            ["hint"] = "",
                            ["description"] = "这些瓜尔虽然在泰姆瑞尔的偏远地方土生土长，却是狂欢节游行中的耀眼明星。节日临近之际，饲养员会给这种瓜尔提供丰富的饮食，从而滋养它们的鲜亮羽毛。",
                            ["name"] = "狂欢节飞羽瓜尔",
                            ["id"] = 12777,
                        },
                        [12778] = 
                        {
                            ["category"] = "陆行狮鹫",
                            ["furnitureId"] = 10237,
                            ["icon"] = "/esoui/art/icons/mount_kynarethquasigriff.dds",
                            ["hint"] = "",
                            ["description"] = "“这头陆行狮鹫可能看起来有点吓人，但吉娜莱丝曾经亲手触摸过它。骑在它的背上时，天气美妙晴好，太阳将不再炽热难耐，就连风都只会从你背后吹来。”——女祭司贝尔克丽娜",
                            ["name"] = "吉娜莱丝的陆行狮鹫",
                            ["id"] = 12778,
                        },
                        [12783] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 10238,
                            ["icon"] = "/esoui/art/icons/mount_maormerwaterhorse.dds",
                            ["hint"] = "",
                            ["description"] = "某些海精灵与潮汐产生了深刻的联结，就连海水都会响应他们的呼唤。而这匹魔法骏马，便是出自一位知名的海巫师之手，用来庆祝她在海洋上度过的第六个世纪。",
                            ["name"] = "深海海盗召唤的战马",
                            ["id"] = 12783,
                        },
                        [12785] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10239,
                            ["icon"] = "/esoui/art/icons/pet_mindshrivenmudcrab.dds",
                            ["hint"] = "完成“为逝者报仇雪恨”任务后获得。",
                            ["description"] = "“就在我凝视那只冷酷的甲壳动物的眼睛时，它钳碎了我的网，就像利剑划开皮肤一般。直到这时我才明白：它是捕食者，而我才是猎物。”——垂钓者比库斯-许",
                            ["name"] = "失心傀儡泥沼蟹",
                            ["id"] = 12785,
                        },
                        [12786] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10240,
                            ["icon"] = "/esoui/art/icons/pet_rootwhispercresteddartfrog.dds",
                            ["hint"] = "",
                            ["description"] = "虽然它不会飞，战斗力却毫不逊色！它只需一个猛扑，猎物就会被它的毒素麻痹。剩下的时间里它就可以慢慢享用美食，而后又像普通青蛙一样跳走。",
                            ["name"] = "根语者饰章箭毒蛙",
                            ["id"] = 12786,
                        },
                        [12787] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 10241,
                            ["icon"] = "/esoui/art/icons/pet_warveteranshuntingdog.dds",
                            ["hint"] = "",
                            ["description"] = "“我喜欢跟自己的狗一起打猎，但我搞不明白：每次打完猎后，它们干嘛老想把我的靴子脱下来？可能是这种狗的怪癖？”——乌沙塔佳",
                            ["name"] = "战争老兵的猎犬",
                            ["id"] = 12787,
                        },
                        [12802] = 
                        {
                            ["category"] = "矮人蜘蛛",
                            ["furnitureId"] = 10243,
                            ["icon"] = "/esoui/art/icons/mount_julianosruinedspider.dds",
                            ["hint"] = "",
                            ["description"] = "“矮人的设计，加上尤里安诺斯无可动摇的逻辑，最终就诞生了我的这款顶级作品。初代产品已由我亲自交到途歇城的主顾手中，另外还附赠了一瓶美酒。”——蛛铁匠的私人字条",
                            ["name"] = "尤里安诺斯的法律矮人蜘蛛",
                            ["id"] = 12802,
                        },
                        [10755] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8604,
                            ["icon"] = "/esoui/art/icons/mount_firesongkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "“没人能扑灭这个盾角蜥心中熊熊燃烧的生命之火。我们在岩浆河中夜夜载歌载舞，煽动着创造之火。如果我们有福，魔法就会生效，我们中的一个人就会得到一匹忠诚的坐骑。”——火焰中的生活",
                            ["name"] = "烬石盾角蜥",
                            ["id"] = 10755,
                        },
                        [12804] = 
                        {
                            ["category"] = "萨里克尔",
                            ["furnitureId"] = 10245,
                            ["icon"] = "/esoui/art/icons/mount_jeralltharriker.dds",
                            ["hint"] = "",
                            ["description"] = "在杰拉尔山脉之中，围坐在苦涩篝火旁取暖的战争逃兵与这些野生的萨里克尔找到了共鸣。它们由疯狂的魔法所创造，因而可以迅速适应新家乡的积雪山坡。",
                            ["name"] = "杰拉尔变节者的萨里克尔",
                            ["id"] = 12804,
                        },
                        [10757] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 8605,
                            ["icon"] = "/esoui/art/icons/mount_khenarthiswindwalker.dds",
                            ["hint"] = "",
                            ["description"] = "“不要被劣马所愚弄了。在受到尊重时，这些马仿佛乘上了柯娜西的风。就假装成风之神亲自赐予你这只高贵生物。就像我这样，好吗？”—森查尔马厩主胡兹达哥",
                            ["name"] = "柯娜西风行者",
                            ["id"] = 10757,
                        },
                        [10758] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8606,
                            ["icon"] = "/esoui/art/icons/pet_evermorepaintersmoth.dds",
                            ["hint"] = "",
                            ["description"] = "“当然，在为布莱斯·吉马尔德公爵绘制肖像画时，我使用了由本地飞蛾制成的颜料。我的几个艺术家朋友为这些色彩斑斓的生物提供了庇护所，也许我的小春雨会帮我建立我的庇护所。”—埃莱娜·塔勒梅利埃夫人的日记",
                            ["name"] = "永恒城彩绘飞蛾",
                            ["id"] = 10758,
                        },
                        [10759] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8607,
                            ["icon"] = "/esoui/art/icons/pet_systresfaunfawn.dds",
                            ["hint"] = "",
                            ["description"] = "据传闻所说，因为拥有相同的花纹，西斯忒斯的鹿人会召唤这些灰色的小鹿来陪自己嬉戏。毫无疑问，这些说法肯定跟讲故事时不可缺少的格洛格酒脱不开关系。但无论如何，它们都非常可爱。",
                            ["name"] = "小斑点鹿人",
                            ["id"] = 10759,
                        },
                        [10760] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8608,
                            ["icon"] = "/esoui/art/icons/pet_harpyscursewasp.dds",
                            ["hint"] = "",
                            ["description"] = "“我的家人最讨厌黄蜂，但某只孤独的黄蜂帮我避开了峭壁行者的攻击。它在咬了一小口我杀死的峭壁行者后就开始跟着我，我猜它可能喜欢吃这些东西。”—流浪者盖利乌斯·努恩修斯",
                            ["name"] = "苦涩海岸胡蜂",
                            ["id"] = 10760,
                        },
                        [10761] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8609,
                            ["icon"] = "/esoui/art/icons/pet_heartwoodsdeathdauber.dds",
                            ["hint"] = "",
                            ["description"] = "生活在霍利奇湖周围森林深处的黄蜂会用泥土筑巢。虽然它们平时都躲藏起来，但它们也会围攻任何威胁其巢穴的敌人。那些帮助它们抵抗入侵者的人可能会发现，回家的路上多了一个跟着自己的朋友。",
                            ["name"] = "心材涂鸦者",
                            ["id"] = 10761,
                        },
                        [6672] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6359,
                            ["icon"] = "/esoui/art/icons/pet_deadlandsembercrab.dds",
                            ["hint"] = "",
                            ["description"] = "几乎没人能经受住死地的酷热和无情的荒凉。那为数不多发现自己被困于死地的倒霉蛋们可能会遭遇这样的恐怖生物——这提醒他们正面临着残酷且永恒的命运。",
                            ["name"] = "永恒厄运泥蟹",
                            ["id"] = 6672,
                        },
                        [6673] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6360,
                            ["icon"] = "/esoui/art/icons/mount_jadedragonslayerhorse.dds",
                            ["hint"] = "",
                            ["description"] = "作为屠龙坐骑的典范，这匹骏马不仅能勇敢面对那些迫使软弱之人退缩的危险，而且也配得上你的体型和经验。更值得一提的是，它有一双发着绿色光芒的眼睛。",
                            ["name"] = "翡翠王冠屠龙宝马",
                            ["id"] = 6673,
                        },
                        [6674] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6361,
                            ["icon"] = "/esoui/art/icons/mount_wasseekhorselizard.dds",
                            ["hint"] = "",
                            ["description"] = "只有瓦希克·黑利尔才会培育出这种色彩斑斓、性情温和的蜥蜴马。当你游荡于幽暗沼泽想要扫清麻烦时，它将是你理想的坐骑。",
                            ["name"] = "瓦希克蜥蜴马",
                            ["id"] = 6674,
                        },
                        [6675] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6362,
                            ["icon"] = "/esoui/art/icons/mount_legionzerodestrier.dds",
                            ["hint"] = "",
                            ["description"] = "通过强迫自己的骏马吸食冷港之血，零之军团的叛军创造了一种无与伦比的战马。它身上覆盖着阴沉可怕的红色铠甲，这是一个真正值得畏惧的坐骑。",
                            ["name"] = "零之军团战马",
                            ["id"] = 6675,
                        },
                        [6676] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6363,
                            ["icon"] = "/esoui/art/icons/mount_winterbloom-warmblood.dds",
                            ["hint"] = "",
                            ["description"] = "很久以前，在尊贵的访客和勇敢的英雄们参加风盔城一年一度的庆典时，他们所骑乘的就是身披喜庆装扮的冬花温血骏马。而现在，它们可以自由地用于其他场合了，或许你可以由此重拾这一传统的精神。",
                            ["name"] = "冬花温血骏马",
                            ["id"] = 6676,
                        },
                        [6677] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 6364,
                            ["icon"] = "/esoui/art/icons/mount_empyreanalphawolf.dds",
                            ["hint"] = "",
                            ["description"] = "暗恒的腐化气息可以转变当地的野生动物，如这只狼，被变为晶体状生物。当你骑着它奔跑时，它的绿色卷须将伴你左右，这会让你们看上去有一种异界风采。",
                            ["name"] = "暗恒狼",
                            ["id"] = 6677,
                        },
                        [6678] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 6365,
                            ["icon"] = "/esoui/art/icons/mount_volcanicsenchepanther.dds",
                            ["hint"] = "",
                            ["description"] = "这只熔岩坐骑散发着热气和硫磺的臭味。一些暗精灵发誓说它来自红山的中心，但他们只会小声地谈论此事。如果你想寻找一匹亵渎神灵的坐骑，那就没有比它再好的了！",
                            ["name"] = "火山森切豹",
                            ["id"] = 6678,
                        },
                        [6679] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6366,
                            ["icon"] = "/esoui/art/icons/mount_darkopalinesteed.dds",
                            ["hint"] = "",
                            ["description"] = "这匹黑暗石骏马诞生自一个傲慢的虎人法师的奇异转化仪式。其周身闪烁着蓝色和紫色的光芒，当它跑起来时，五颜六色的光波在它身后飘荡。骑着它穿行于任何环境中都行动极为迅捷，而且看起来颇有格调！",
                            ["name"] = "黑暗石骏马",
                            ["id"] = 6679,
                        },
                        [6680] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 6367,
                            ["icon"] = "/esoui/art/icons/mount_frostatronachkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "这只具有盾角蜥外形的寒霜侍灵也许是某个不幸的法士学徒在成为它的第一个受害者之前制作的最后一件东西。也许你能驯服这个坐骑？如果做不到，那就最好多准备一些治疗药水，因为它肯定会咬你的。",
                            ["name"] = "寒霜侍灵盾角蜥",
                            ["id"] = 6680,
                        },
                        [6681] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 6368,
                            ["icon"] = "/esoui/art/icons/mount_frostatronachwolf.dds",
                            ["hint"] = "",
