                            ["furnitureId"] = 7505,
                            ["icon"] = "/esoui/art/icons/mount_ironatroguar2.dds",
                            ["hint"] = "",
                            ["description"] = "在一次醉酒后，法师塔文·奥瑟伦召唤出了第一只已知的铁侍灵瓜尔，而它却立即杀死了他的同伴们。悲痛之余，法师寻求救赎，在余生中只骑着那只瓜尔作为他所犯之错的提醒。",
                            ["name"] = "铁侍灵瓜尔",
                            ["id"] = 8877,
                        },
                        [8878] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7506,
                            ["icon"] = "/esoui/art/icons/mount_ironatrosenche.dds",
                            ["hint"] = "",
                            ["description"] = "故事讲述了玛兰丽·第仁尼，虽然被强盗束缚着，但不知怎么就潜入了梦境，并召唤出了第一只铁侍灵森切。铁侍灵森切一出现便摧毁了玛兰丽的笼子并释放了她，这样她便能杀了抓她的人，随后骑在它的熔岩之背上逃跑了。",
                            ["name"] = "铁侍灵森切",
                            ["id"] = 8878,
                        },
                        [8879] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 7507,
                            ["icon"] = "/esoui/art/icons/mount_ironatrowolf.dds",
                            ["hint"] = "",
                            ["description"] = "在铁侍灵的各种不同形态中，狼是最难成的。侍灵憎恨狼对于群体的依赖，渴望找到符合它们孤独本质的外形。通常只有泰姆瑞尔的顶尖法师，才能将这些熔岩巨人变化为狼的形态。",
                            ["name"] = "铁侍灵狼",
                            ["id"] = 8879,
                        },
                        [8880] = 
                        {
                            ["category"] = "陆行狮鹫",
                            ["furnitureId"] = 7508,
                            ["icon"] = "/esoui/art/icons/mount_gryphon.dds",
                            ["hint"] = "",
                            ["description"] = "“炽热的灰烬和暗黑的羽毛，尖锐的利爪和加剧的愤怒，这些都接近于剃刀魔神；至少圣人是这么说的。然而，在混沌使这头野兽扭曲之前，第仁尼就已经精心制作了这些。它的身上沾染着死地的堕落热量，无法被祛除。”——名为齐力克的斯卡芬",
                            ["name"] = "大衮陆行狮鹫",
                            ["id"] = 8880,
                        },
                        [10929] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8686,
                            ["icon"] = "/esoui/art/icons/pet_eggbaby.dds",
                            ["hint"] = "",
                            ["description"] = "“一天早晨，我在花园里发现了一个小瓜尔。它到处乱跑，撞到各种东西上。我不完全确定它为什么它要留下一些外壳，但我不在乎。你看它多可爱！我觉得我们现在是朋友了，我愿意为它而死。”——法尔瓦",
                            ["name"] = "未孵化完的小瓜尔",
                            ["id"] = 10929,
                        },
                        [12978] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10310,
                            ["icon"] = "/esoui/art/icons/pet_gloamsenchecub.dds",
                            ["hint"] = "",
                            ["description"] = "“坐在火堆旁时，我察觉到有两只小眼睛正在黑暗中盯着我看。我在营地边放了一些肉，却惊讶地看见一只幽灵般的森切从黑暗中现身，小口小口吃掉了肉。这也许是诺克图娜回应了我的祈祷。”——摘自找回的费利萨·墨本拿的日记",
                            ["name"] = "薄暮森切幼崽",
                            ["id"] = 12978,
                        },
