                        [12992] = 
                        {
                            ["category"] = "特殊",
                            ["furnitureId"] = 10318,
                            ["icon"] = "/esoui/art/icons/mount_akaatoshlivingarmor.dds",
                            ["hint"] = "从阿卡托什和奥杜因王冠宝箱中获取其它的收藏品后，可领取此坐骑。",
                            ["description"] = "“赞美阿卡托什！金色之神！辉煌尊者！让您的烈焰在这造物中熊熊燃烧、绽放光芒吧！让它传播您的光辉，引领世人走向智慧。让阿卡托什的力量在这只奇特的生物体内永存！”——揭幕仪式",
                            ["name"] = "阿卡托什活体护甲森切",
                            ["id"] = 12992,
                        },
                        [12993] = 
                        {
                            ["category"] = "特殊",
