                            ["icon"] = "/esoui/art/icons/mount_harrowstormcharger.dds",
                            ["hint"] = "",
                            ["description"] = "第一匹诞生自血疫风暴的军马抛弃了它最初的骑手，并绝尘而去，没人能够捉到它。这种情况持续了一段时间，让很多人都想知道它去了哪里。有人说它必会寻找新的骑手，无论这是好是坏。",
                            ["name"] = "血疫风暴军马",
                            ["id"] = 11067,
                        },
                        [6972] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 7244,
                            ["icon"] = "/esoui/art/icons/mount_groupmountspider.dds",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t多人坐骑（1个操控者，1个乘客）|r|",
                            ["description"] = "“很明显，矮人们总是喜欢结对旅行，为此他们建造了这个两人座的矮人构造体，我和我的伴侣喜欢坐着它去赶集！”——戴利纳·艾维尔",
                            ["name"] = "双座矮人蜘蛛",
                            ["id"] = 6972,
                        },
                        [11069] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8701,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "“邪恶的恶作剧对这只条纹盾角蜥造成了伤害。‘必须得让维威克领主知道，我们治愈了这只保护其仆从的生物。痛定思痛，才能免除后痛。’于是，它与熊和蜘蛛成了朋友。”——剑骑士萨里斯的日记",
                            ["name"] = "博雅剑骑士盾角蜥",
