                        [11073] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8818,
                            ["icon"] = "/esoui/art/icons/houseguest_sirstefanmornard.dds",
                            ["hint"] = "",
                            ["description"] = "拥有骑士技能和德鲁伊知识的斯特凡·莫尔纳德爵士是一名致命的敌人，也是一位彬彬有礼的房客。把斯特凡爵士添加到你的家中，你可以为他设置行动路径，你和访客们还能和他聊天。",
                            ["name"] = "斯特凡·莫尔纳德",
                            ["id"] = 11073,
                        },
                        [11074] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8817,
                            ["icon"] = "/esoui/art/icons/houseguest_caska.dds",
                            ["hint"] = "",
                            ["description"] = "森切战猫卡斯卡是至臻突袭者号的大副，她喜欢在休息时间捣鼓其他爱好——也许就是在你的房子里！把卡斯卡添加到你的家中，你可以为她设置行动路径，你和访客们还能和她聊天。",
                            ["name"] = "卡斯卡",
                            ["id"] = 11074,
                        },
                        [11075] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8819,
                            ["icon"] = "/esoui/art/icons/houseguest_meladrys.dds",
                            ["hint"] = "",
                            ["description"] = "像梅尔·阿德里斯这样的吸血鬼猎人在追猎过程中常四处奔波，在狩猎的间隙，他们需要有地方休息。你愿意接待这位暗精灵吗？把梅尔添加到你的家中，你可以为他设置行动路径，你和访客们还能和他聊天。",
                            ["name"] = "梅尔·阿德里斯",
                            ["id"] = 11075,
                        },
                        [11076] = 
                        {
                            ["category"] = "陆行狮鹫",
                            ["furnitureId"] = 8705,
                            ["icon"] = "/esoui/art/icons/mount_spellscarquasigriff.dds",
                            ["hint"] = "",
                            ["description"] = "法术之疤释放出来的未受约束的能量会扭曲并改变其接触到的一切。现在仍然不知道是谁或者什么东西将陆行狮鹫引到了荒崖，但这些奇异而美丽的生物为泰姆瑞尔增添了前所未见且超脱凡俗的景象。",
                            ["name"] = "法术之疤陆行狮鹫",
                            ["id"] = 11076,
                        },
                        [11079] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8707,
                            ["icon"] = "/esoui/art/icons/pet_firebellyshalk.dds",
                            ["hint"] = "",
                            ["description"] = "火腹沙克虫总是在燃烧，这点不同于它们更常见的家养近亲。暗精灵战士们有时会训练这些琉璃壁建筑的原住民潜入敌人领地，而其他人则会在灰原寒冷的夜晚发现，它们是能为自己带来温暖的朋友。",
                            ["name"] = "火腹沙克虫",
                            ["id"] = 11079,
                        },
                        [11082] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 8708,
                            ["icon"] = "/esoui/art/icons/pet_fangtome.dds",
                            ["hint"] = "",
                            ["description"] = "“你喜欢书，是吧？要是它们长出触手和一只眼睛呢？要是它们会飞呢？你还会那么喜欢它们吗？会？哦，太棒了！来吧，跟我心爱的《永恒哲学》（简称《永哲》）交个朋友吧，帮它更加深入地了解奈恩。”—失落的档案保管者",
                            ["name"] = "深渊魂泊典魔",
                            ["id"] = 11082,
                        },
                        [11097] = 
                        {
                            ["category"] = "助手",
                            ["furnitureId"] = 8997,
                            ["icon"] = "/esoui/art/icons/assistant_pyroclast.dds",
                            ["hint"] = "",
                            ["description"] = "从因弗内斯的口袋世界出现，火山碎屑将把你的物品（或你队友的物品）存放在湮灭之地的火坑中。可能会留有轻微的灼伤痕迹。\r\n\r\n古代约缚让他们无法出现在西罗帝尔或战场上。",
                            ["name"] = "火山碎屑（因弗内斯保护者）",
                            ["id"] = 11097,
                        },
                        [11102] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 8776,
                            ["icon"] = "/esoui/art/icons/mount_necromarmigersenche.dds",
                            ["hint"] = "",
                            ["description"] = "“当使者带着这只森切抵达时，我们全都惊讶万分。‘这是来自死灵之地的礼物，献给一位声名显赫的剑骑士。请返回帮助训练更多的人！’于是，我带着一只狡猾的毛茸伙伴踏上了前往死亡之地的旅程。”——剑骑士萨里斯的日记",
                            ["name"] = "死灵之地剑骑士森切",
                            ["id"] = 11102,
