                        [9062] = 
                        {
                            ["category"] = "四目兽",
                            ["furnitureId"] = 7528,
                            ["icon"] = "/esoui/art/icons/mount_sulxanfleshripper.dds",
                            ["hint"] = "在石林试炼中完成达成“夏尔瓦卡的克星”成就。",
                            ["description"] = "通过一个被剃刀魔神的混沌所浸染的亚龙人仪式，这只曾经的四目兽坐骑在可触之的炎火形态下，周身弥漫怒气与破坏欲。只有意志坚强之人才得以控制这头野兽。也许这人就是你？",
