                            ["id"] = 9062,
                        },
                        [9063] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7529,
                            ["icon"] = "/esoui/art/icons/mount_grandnibenesehorse.dds",
                            ["hint"] = "",
                            ["description"] = "尽管有人说这些马纯粹是为了展示而饲养的，但在乐雅文，尼本尼巨型公马不仅仅是幸运的象征。它们十分聪明，气质高雅，即使在拥挤的街道上也能不骄不躁。",
                            ["name"] = "尼本尼巨型公马",
                            ["id"] = 9063,
                        },
                        [9064] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 7530,
                            ["icon"] = "/esoui/art/icons/mount_dappledelinhircamel.dds",
                            ["hint"] = "",
                            ["description"] = "“虽然铁兽人几乎把这些温和的骆驼吃绝种了，但强大的爱林希尔法师们收留了它们，让它们繁衍生息。凭借着它们流畅的步态和柔软的皮毛，这种气息香甜的动物成为了法师们的首选坐骑。”——加洛德·法尔弗莱",
                            ["name"] = "爱林希尔斑点骆驼",
                            ["id"] = 9064,
                        },
                        [9065] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7531,
                            ["icon"] = "/esoui/art/icons/mount_bayhorse.dds",
                            ["hint"] = "",
                            ["description"] = "这匹马的阳光气质正与它富有活力的多色皮毛相配，它因此成为新骑手或经常冒险进入危险地带之人的坐骑。马群经常追逐着黄金海岸的海浪奔跑，鬃毛随风摆动，尾巴高高翘起。",
                            ["name"] = "金轮枣红纯种马",
                            ["id"] = 9065,
                        },
                        [9066] = 
                        {
                            ["category"] = "公羊",
                            ["furnitureId"] = 7532,
                            ["icon"] = "/esoui/art/icons/mount_celestialram.dds",
                            ["hint"] = "",
                            ["description"] = "“在荒崖，星星并不总是停留在天上。它们四处游荡，跳过岩石，偶尔还会吃掉你在花园里种的所有东西。那些长着獠牙的山羊可以把它们闪闪发光的毛皮带到别的地方去！”——贝尔卡斯园艺家乌布里",
                            ["name"] = "天界公羊",
                            ["id"] = 9066,
                        },
                        [9067] = 
                        {
                            ["category"] = "异域",
