                        [7077] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 6532,
                            ["icon"] = "/esoui/art/icons/mount_curseboundradsenche.dds",
                            ["hint"] = "",
                            ["description"] = "这种生物被冷港的压迫性能量所支配，莫拉格·巴尔的邪恶誓约把它与其主人约缚在了一起。虽然它缺乏自我行动的能力，但它体内蕴含的怒火却与日俱增。",
                            ["name"] = "咒缚剑齿虎潜行者",
                            ["id"] = 7077,
                        },
                        [7078] = 
                        {
