                            ["furnitureId"] = 6533,
                            ["icon"] = "/esoui/art/icons/mount_curseboundradraht.dds",
                            ["hint"] = "",
                            ["description"] = "扎诺为了满足自己旺盛的好奇心，参加了一些实验性的仪式，结果却被这些仪式扭曲，打上了烙印。尽管他仍在寻求满足自己无休止的求知欲，但他现在这样做是为了摆脱可憎的主人对他的奴役。",
                            ["name"] = "咒缚暗牙森切战猫",
                            ["id"] = 7078,
                        },
                        [7079] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 6534,
                            ["icon"] = "/esoui/art/icons/mount_gloomsporebear.dds",
                            ["hint"] = "",
                            ["description"] = "“一个叫里古特的兄弟想要一只‘英勇无畏’的熊坐骑，能让朋友为之‘眼前一亮’。我这融合了天鹅菇、泛着莹光的幽暗孢子熊能突破敌人，将骑手带离危险，真可谓是‘英勇无畏’。”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子熊",
                            ["id"] = 7079,
                        },
                        [7080] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 6535,
                            ["icon"] = "/esoui/art/icons/mount_gloomsporecamel.dds",
                            ["hint"] = "",
                            ["description"] = "“一位学者想要一匹可以承受很大负重的坐骑，所以我给了她一匹幽暗孢子骆驼。在创造它的过程中使用鳞片菇会使它在承受任何重量时都不太可能抱怨，另外还让它的步伐具有弹性。”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子骆驼",
                            ["id"] = 7080,
                        },
                        [7081] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 6536,
                            ["icon"] = "/esoui/art/icons/mount_gloomsporeguar.dds",
                            ["hint"] = "",
                            ["description"] = "“一个暗精灵法师走过来，气得发抖，直接询问我哪个坐骑最皮糙肉厚。虽然我的幽暗孢子瓜尔看起来有点淘气，这可能是因为我在制作它们时加多了流血冠冕菇，但它们有厚厚的真菌皮。”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子瓜尔",
                            ["id"] = 7081,
                        },
                        [7082] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6537,
                            ["icon"] = "/esoui/art/icons/mount_gloomsporehorse.dds",
                            ["hint"] = "",
                            ["description"] = "“在使用巨型地衣制造幽暗孢子马时产生了意想不到的结果。这些坐骑漂亮得令人生畏，而且经常会因紧张而抽搐。所以你永远不必担心遭遇暗算，只要紧紧抓住它就行了，它会带着你跑的！”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子马",
                            ["id"] = 7082,
                        },
                        [7083] = 
                        {
