                            ["icon"] = "/esoui/art/icons/mount_solstheimshamanwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“不要招惹其他骑手的狼，除非你已准备好去见造物主。这些狼都是灵兽，它们受召而来，但只忠诚于它们的骑手。我几乎是失掉了一根手指才学到了这个苦痛的教训。”——独孤城的赫罗凯拉",
                            ["name"] = "索塞姆战栗之狼",
                            ["id"] = 11197,
                        },
                        [11198] = 
                        {
                            ["category"] = "房客",
