                            ["icon"] = "/esoui/art/icons/houseguest_craftylerisa.dds",
                            ["hint"] = "",
                            ["description"] = "正如她的名字所暗示的，勒里莎的狡猾正是她一直存活至今的品质。现在这个品质正在告诉她坐着别动——要不就坐在你家里怎么样？将狡猾的勒里莎添加到你的家中后，你可以为她设置行动路径，你和访客们还能和她聊天。",
                            ["name"] = "狡猾的勒里莎",
                            ["id"] = 11198,
                        },
                        [11199] = 
                        {
                            ["category"] = "房客",
