                            ["icon"] = "/esoui/art/icons/pet_mistralthunderbug.dds",
                            ["hint"] = "",
                            ["description"] = "谁要是拥有了这个震颤人心的小家伙，就必须学会应对不时发生的电击事故。雷光虫很擅长表现，然而它们的主要沟通方式是火花和剧烈的震动。",
                            ["name"] = "米斯特拉尔雷光虫",
                            ["id"] = 11657,
                        },
                        [10203] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8253,
                            ["icon"] = "/esoui/art/icons/mount_stonelorefox.dds",
                            ["hint"] = "",
                            ["description"] = "德鲁伊的故事说，第一批狐狸刚游出耶弗隆不久，焱歌山就喷吐出了灰烬和火焰。那些跟石刻之识狐狸交好的人都很长寿，尽管石刻之识坚持认为这与狐狸的生存本能无关。",
                            ["name"] = "石刻之识狐狸",
                            ["id"] = 10203,
                        },
                        [10202] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 8252,
                            ["icon"] = "/esoui/art/icons/mount_stoneloreelk.dds",
                            ["hint"] = "",
                            ["description"] = "“我们重视麋鹿，因为它们行动灵活，性情温和。它们陪伴我们到大型野兽无法到达的地方。它们在危险面前不会退缩，也不放弃自己的工作。我希望我能说一些新人也是如此！哼！”—德鲁伊巴尔约特",
                            ["name"] = "石刻之识麋鹿",
                            ["id"] = 10202,
                        },
                        [13571] = 
                        {
                            ["category"] = "普通",
