                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingu46painting001.dds",
                            ["hint"] = "",
                            ["description"] = "传说高精灵和哥布林曾在国王港隘口互通往来、和平贸易。但在两者关系恶化后，裂珊族的哥布林便将此地占为了己有。",
                            ["name"] = "画作：国王港隘口",
                            ["id"] = 13571,
                        },
                        [13555] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 10609,
                            ["icon"] = "/esoui/art/icons/u45_houseguest_duchesseleadufort.dds",
                            ["hint"] = "",
                            ["description"] = "艾利亚·杜佛特女公爵的盛大环游正在进行中，她渴望瞧一瞧高岛与西斯忒斯群岛之外的精彩世界。邀请她来作客吧！让艾利亚进入你的家，你可以为她设置行动路径，你和访客们还能和她聊天。",
                            ["name"] = "艾利亚·杜佛特女公爵",
                            ["id"] = 13555,
                        },
                        [13554] = 
                        {
                            ["category"] = "存储",
                            ["furnitureId"] = 10846,
                            ["icon"] = "/esoui/art/icons/housing_uni_fur_housingfurnishingbag001.dds",
                            ["hint"] = "ESO Plus会员可用",
                            ["description"] = "|cFFFFFF500个槽位|r\r\n\r\n你可以将装饰品宝库添加到多个住宅中。即使宝库并未放置，你也可以存取其中的物品。你既可以使用已放置的宝库，也可以打开编辑器菜单来取出、放置或储存物品。该宝库仅能储存装饰品。",
                            ["name"] = "装饰品宝库",
                            ["id"] = 13554,
                        },
                        [13547] = 
                        {
                            ["category"] = "萨里克尔",
                            ["furnitureId"] = 10604,
                            ["icon"] = "/esoui/art/icons/mount_nightmaresalchemytharriker.dds",
                            ["hint"] = "",
                            ["description"] = "A mix of Skingrad wine, some ashy remnants of Quagmire dreams, and ooze from a Pits-born plague hopper make for a heady solution. After imbibing, neither rider or steed can waver from goals set by the Nightmare Queen and the Master of Tasks.",
                            ["name"] = "Nightmare's Alchemy Tharriker",
                            ["id"] = 13547,
                        },
                        [9235] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7604,
                            ["icon"] = "/esoui/art/icons/mount_dauntlessbananas.dds",
                            ["hint"] = "",
                            ["description"] = "骑手们驾驭着这些黑金相间的坐骑意气风发地横扫了西罗帝尔，它们象征着无畏战士们的共同追求和体验。\r\n\r\n|cFFFFFF骑术技能不会影响该坐骑的外观。|r",
                            ["name"] = "战场之绊军马",
                            ["id"] = 9235,
                        },
                        [9236] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7605,
                            ["icon"] = "/esoui/art/icons/mount_goldleafacquisitions.dds",
                            ["hint"] = "",
                            ["description"] = "整个泰姆瑞尔的寻宝者都对它梦寐以求，这匹步履稳健的骏马既是强壮的伙伴，也是长久的提醒，提醒人们友谊和友情可以取得什么成就。\r\n\r\n|cFFFFFF骑术技能不会影响该坐骑的外观。|r",
                            ["name"] = "公会之傲冲锋战马",
                            ["id"] = 9236,
                        },
                        [13546] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 10603,
                            ["icon"] = "/esoui/art/icons/mount_nightmaresalchemyelk.dds",
                            ["hint"] = "",
                            ["description"] = "Cult priests form a compound with Blackwood herbs and bone salvaged from Quagmire and the Pits. The glowing solution guides this elk and its rider to Prince-favored destinations.",
                            ["name"] = "Nightmare's Alchemy Elk",
                            ["id"] = 13546,
                        },
                        [9238] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7606,
                            ["icon"] = "/esoui/art/icons/pet_spectralmudcrab.dds",
                            ["hint"] = "",
                            ["description"] = "“如果跟在我身后的东西真的是鬼魂，那么这是我见过的最温和的闹鬼行为。这个甲壳生物只在我的脚边溜达，偶尔还会用爪子抓抓家里的不速之客。”——灵魂猎手本沙拉兹",
                            ["name"] = "幽灵泥蟹",
                            ["id"] = 9238,
                        },
                        [13545] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 10602,
                            ["icon"] = "/esoui/art/icons/mount_nightmaresalchemysenche.dds",
                            ["hint"] = "",
                            ["description"] = "Cult alchemists in Rimmen distill Tenmar plants watered from the Pits and grown in Dreamstride soil. A few drops from the resulting tincture for both rider and steed bless their missions for Peryite and Vaermina.",
                            ["name"] = "Nightmare's Alchemy Senche",
                            ["id"] = 13545,
                        },
                        [9240] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7607,
                            ["icon"] = "/esoui/art/icons/pet_terrorbirdyellow.dds",
                            ["hint"] = "",
                            ["description"] = "在野外，黄玉恐鸟会躲在风沙中，伏击毫无戒心的猎物。这种雏鸟总是在练习这种伏击技巧，所以一定要在沙尘暴袭来之前警告你的同伴。毕竟谁都不想遭受袭击！",
                            ["name"] = "黄玉恐鸟雏鸟",
                            ["id"] = 9240,
                        },
                        [13544] = 
                        {
                            ["category"] = "瓦尔德瓦克",
                            ["furnitureId"] = 10601,
                            ["icon"] = "/esoui/art/icons/mount_nightmaresalchemyvvardvark.dds",
                            ["hint"] = "",
                            ["description"] = "Fungal spores from the Telvanni Peninsula, when placed in a medium of Quagmire soil and mixed with Pits minerals, grow into a pungent slime. Both rider and beast, after imbibing, travel through a mix of the waking world and dream world.",
                            ["name"] = "Nightmare's Alchemy Vvardvark",
                            ["id"] = 13544,
                        },
                        [12751] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10230,
                            ["icon"] = "/esoui/art/icons/pet_kynarethsgryphon.dds",
                            ["hint"] = "",
                            ["description"] = "要想展翅高飞，就得先学会脚踏实地。据说吉娜莱丝将这些幼雏送到奈恩的目的就是让它们找到自己的挚友，从而帮助它们学会平等地珍视大地与天空。",
                            ["name"] = "吉娜莱丝的狮鹫幼雏",
                            ["id"] = 12751,
                        },
                        [9243] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7608,
                            ["icon"] = "/esoui/art/icons/pet_lowlandbristleback.dds",
                            ["hint"] = "",
                            ["description"] = "“这个棘手的生物把哪个低地称为家？为什么！为什么所有人都觉得我在夸张？相信你想要的，但你要知道，除非在它们年幼时就训练它们，否则它们会毫不犹豫地冲向你。最好让它们站在你这边。”——饲养员米特",
                            ["name"] = "低地刚鬣猪",
                            ["id"] = 9243,
                        },
                        [9244] = 
                        {
