                            ["icon"] = "/esoui/art/icons/pet_snowbarrowboar.dds",
                            ["hint"] = "",
                            ["description"] = "这些野猪在荒岩岛的北方森林中游荡。它们勉强适应了驯化，并乐于和主人一起穿越厚厚的积雪、污泥或草原。",
                            ["name"] = "雪野猪",
                            ["id"] = 9244,
                        },
                        [11293] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 8998,
                            ["icon"] = "/esoui/art/icons/pet_bibliosophfangtome.dds",
                            ["hint"] = "",
                            ["description"] = "方托梅并不了解他们所栖息之书的重要性或内容。要是你珍贵的初版书或重要的学术文献有了一个栖居者，那么，只需要经常按摩书脊，并轻柔地翻动书页，就能与这本书建立友谊。",
                            ["name"] = "白化者方托梅",
                            ["id"] = 11293,
                        },
                        [9246] = 
                        {
                            ["category"] = "陆行狮鹫",
                            ["furnitureId"] = 7615,
                            ["icon"] = "/esoui/art/icons/mount_baldgryphon.dds",
                            ["hint"] = "",
                            ["description"] = "这种嵌合体坐骑是魔法和选择性繁殖的产物，夏暮岛狮鹫的后代。据创造者伊拉斯蒂米尔·第仁尼所说，它们没有翅膀的结构可以减少维护成本，同时保持了对自命不凡的布莱顿人笨拙坐骑的优势。",
                            ["name"] = "陆行狮鹫",
                            ["id"] = 9246,
                        },
                        [9247] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 7616,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettesyrabane001.dds",
                            ["hint"] = "",
                            ["description"] = "一尊先祖神州的魔法祖先塞拉班的微型雕像。",
                            ["name"] = "小雕像：塞拉班，法士",
                            ["id"] = 9247,
                        },
                        [9248] = 
                        {
                            ["category"] = "普通",
