                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettekynareth001.dds",
                            ["hint"] = "",
                            ["description"] = "水手和旅行者的神圣赞助人，吉娜莱丝的微型雕像。",
                            ["name"] = "小雕像：吉娜莱丝，空气女神",
                            ["id"] = 9248,
                        },
                        [9249] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7619,
                            ["icon"] = "/esoui/art/icons/mount_grimsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“这只体态轻盈的猫科动物知道如何像一名聪明的刺客那样隐秘地出击，这让它成为能够有条不紊地结束他人生命的和睦坐骑。更妙的是，我的这只有时候还会带来残缺不全的精灵作为礼物。也许你也会这么幸运？”——悔恨之母",
                            ["name"] = "奸笑恐怖森切",
                            ["id"] = 9249,
                        },
                        [9250] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7620,
                            ["icon"] = "/esoui/art/icons/mount_grimhorse.dds",
                            ["hint"] = "",
                            ["description"] = "“我无法从奸笑恐怖中选出最喜欢的一个，但这匹被疯狂恩泽过的不祥马匹从内心深处吸引着我。也许是因为它们喜欢用蹄子把不受欢迎的骑手内脏都给踢出来。”——悔恨之母",
                            ["name"] = "奸笑恐怖马",
                            ["id"] = 9250,
                        },
                        [9251] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 7621,
                            ["icon"] = "/esoui/art/icons/mount_grimbear.dds",
                            ["hint"] = "",
                            ["description"] = "“要驾驭这种熊，你需要的不仅仅是丰富色彩的披甲——纳布克雷森放出的一滴血和观察者眼中的一滴泪珠，都可能会将这只熊束缚于你。只是可能。否则，站开。它们要是拥抱你的话，你活不下来的。”——悔恨之母",
                            ["name"] = "奸笑恐怖熊",
                            ["id"] = 9251,
                        },
                        [9252] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 7622,
                            ["icon"] = "/esoui/art/icons/mount_grimguar.dds",
                            ["hint"] = "",
                            ["description"] = "“对着这只瓜尔低吟，描述最近的狂暴凶杀，你可能会在这只瓜尔身边赢得一席之地。或者通过模仿响亮的排泄功能来吸引它的注意。这两种都能让它高兴。”——悔恨之母",
                            ["name"] = "奸笑恐怖瓜尔",
                            ["id"] = 9252,
                        },
                        [9253] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 7623,
                            ["icon"] = "/esoui/art/icons/mount_grimwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“这只狼看起来像是一个顽皮的小丑节动物，一头准备表演娱乐节目的野兽。但不是的。它的聪明机智和尖利獠牙可不关心别人的娱乐，它只关心自己。只有骑在上面的人才是安全的。”——悔恨之母",
                            ["name"] = "奸笑恐怖狼",
                            ["id"] = 9253,
                        },
                        [9254] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7632,
                            ["icon"] = "/esoui/art/icons/pet_sapphiresepadder.dds",
                            ["hint"] = "",
                            ["description"] = "据阿什阿巴所说，如果你收到一条这种凶猛的赛普蝰蛇作为礼物，一年后你们两个都还活着，那么你就通过了毒药交易的第一次试炼。奖金？如果你还活着，你就可以留着这个宝石色的生物。",
                            ["name"] = "蓝宝石赛普蝰蛇",
                            ["id"] = 9254,
                        },
                        [9255] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 7633,
                            ["icon"] = "/esoui/art/icons/pet_carminewoodmoth.dds",
                            ["hint"] = "",
                            ["description"] = "一个世纪前，尼本尼人用明亮的红宝石翅膀上的灰尘作为胭脂，几乎灭绝了这些蛾子，但是后者在另一个地区卷土重来了：瓦伦伍德。它们非常友好，现在是炼金术士们喜爱的伙伴。",
                            ["name"] = "洋红木蛾",
                            ["id"] = 9255,
