                            ["description"] = "一尊铜制半身像，以纪念无畏者在龙星竞技场的胜利。",
                            ["name"] = "半身像：战斗大师西亚斯",
                            ["id"] = 1124,
                        },
                        [7269] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 6549,
                            ["icon"] = "/esoui/art/icons/pet_slateskinneddaedrat.dds",
                            ["hint"] = "",
                            ["description"] = "“灰皮魔鼠的眼睛和身上的标记之所以会闪烁着冷蓝色的光芒，是因为它们以被莫拉格·巴尔触摸过的尸体为食。有一些胆子大到研究甚至阻挠残暴大君的人，就常常研究这种生物来获得更多知识。”——爱林希尔的普拉斯图斯",
                            ["name"] = "灰皮魔鼠",
                            ["id"] = 7269,
                        },
                        [1126] = 
                        {
                            ["category"] = "无畏者半身像",
                            ["furnitureId"] = 4349,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteraniceatronach001.dds",
                            ["hint"] = "完成（老兵模式）恐霜要塞后获得的奖励。",
                            ["description"] = "一尊铜制半身像，以纪念无畏者在恐霜要塞的胜利。",
                            ["name"] = "半身像：寒冰之心",
                            ["id"] = 1126,
                        },
                        [5223] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5443,
                            ["icon"] = "/esoui/art/icons/pet_201_riverholdcub.dds",
                            ["hint"] = "",
                            ["description"] = "即使只是一窝幼崽，这群威猛河堡镇森切狮也继承了种族特有的勇气以及忠诚品格。它们会在主人受到甲虫还有蝴蝶骚扰时勇敢地挺身而出！",
                            ["name"] = "威猛河堡镇森切幼狮",
                            ["id"] = 5223,
                        },
                        [5224] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5473,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_riverholdlion.dds",
                            ["hint"] = "",
                            ["description"] = "生活在安奎那北部田园的族群在放牧时需要可靠的坐骑，在这点上没什么能比得上河堡镇附近的森切狮群品种了。这些猫科坐骑勇敢而忠诚，因此被称为“威猛”。",
                            ["name"] = "威猛河堡镇森切狮",
                            ["id"] = 5224,
                        },
                        [7273] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6553,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporeguar.dds",
                            ["hint"] = "",
                            ["description"] = "“我忠诚的幽暗孢子瓜尔幼崽是最棒的同伴。我用以镇静功效闻名的幽暗孢子改变了瓜尔的性情。很可惜，这样做的副作用是让这小家伙变得爱放屁，不过和无与伦比的忠诚度相比，爱放屁也没什么了。”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子瓜尔幼崽",
                            ["id"] = 7273,
                        },
                        [7274] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6554,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporebear.dds",
                            ["hint"] = "",
                            ["description"] = "“在整合了附魔师阿兹达尔的研究成果之后，利用从一位行遍四方的商人手中买来的孢子，我创造出了一只小熊幼崽。跟普通的小熊比起来，这家伙笨手笨脚的，但它会发光啊！多棒啊！”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子熊幼崽",
                            ["id"] = 7274,
                        },
                        [7275] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6555,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporesenche.dds",
                            ["hint"] = "",
                            ["description"] = "“为了给世上最冷漠无情的人们一个惊喜，我照着森切幼崽的样貌，做出了一个孢子毛球。我怎么能忍住不做呢？至于那些经过如此可爱的孢子球也挤不出一丝微笑的人，我鄙视他们。”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子森切幼崽",
                            ["id"] = 7275,
                        },
                        [7276] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6556,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporepony.dds",
                            ["hint"] = "",
                            ["description"] = "“有个同事和我打赌，于是我就造出了这个孢子小马。起初的那几只只会呆呆地站着，所以我加了一点迪曼提亚的癫狂羊肚菌，这小家伙一下子就活泼起来了。如果你想领养一只的话，我建议你让它离客厅远点。”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子小马",
                            ["id"] = 7276,
                        },
                        [7277] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6557,
                            ["icon"] = "/esoui/art/icons/pet_gloomsporewolf.dds",
                            ["hint"] = "",
                            ["description"] = "“我构思了一种可爱的狼崽，添加了一些牛血真菌孢子，想看看那样会不会增强它们的守护本能。我成功了，现在它们会忠诚地守护我的双脚，连鞋和袜子都不让碰。考虑在它们的视线之外穿衣服吧！”——法师纳勒迪尔",
                            ["name"] = "幽暗孢子狼幼崽",
                            ["id"] = 7277,
                        },
                        [7278] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6558,
                            ["icon"] = "/esoui/art/icons/pet_rimeduskindrik.dds",
                            ["hint"] = "",
                            ["description"] = "寒风呼啸的声音刺破了黄昏，冰封的树林昭示着一只青霜夫诸的诞生。无论走到哪里，这些夫诸都散发着深沉冷静的气息。",
                            ["name"] = "青霜夫诸",
                            ["id"] = 7278,
                        },
                        [7279] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6559,
                            ["icon"] = "/esoui/art/icons/pet_coldspringnixhound.dds",
                            ["hint"] = "",
                            ["description"] = "哈拉鲁家族的暗精灵们深知在瓦登费尔之外也有着许多危险的人、动物和植物，于是他们繁育了一种能在各样环境中茁壮成长的尼克斯犬虫。即便身上披着蓝紫色的花纹，这种尼克斯犬虫仍然散发着一股危险的气息。",
                            ["name"] = "寒春尼克斯犬虫",
                            ["id"] = 7279,
                        },
                        [7280] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6560,
                            ["icon"] = "/esoui/art/icons/pet_iceglowsalamander.dds",
                            ["hint"] = "",
                            ["description"] = "在研究秘术养殖业时，法师纳勒迪尔发现了一种被人长年遗忘的野精灵仪式，这种仪式能让普通的蝾螈发出光芒。而现在，由于这种蝾螈的数量意外暴涨，纳勒迪尔决定把它们送给自己看好的人。",
                            ["name"] = "寒光蝾螈",
                            ["id"] = 7280,
                        },
                        [7281] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6561,
                            ["icon"] = "/esoui/art/icons/pet_bluetorchbug.dds",
                            ["hint"] = "",
                            ["description"] = "苏醒日的前天夜里，伊利亚克湾的布莱顿人传颂着一个有关莫拉格·巴尔的可怕流萤虫的故事。虽然这个故事有很多版本，不过它们有一个共同点：那些被钴蓝色流萤虫跟随的人在战斗中十分野蛮，而这份野蛮也会伴随每一位幸存者。",
                            ["name"] = "蓝色流萤虫",
                            ["id"] = 7281,
                        },
                        [7282] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6562,
                            ["icon"] = "/esoui/art/icons/pet_purpletorchbug.dds",
                            ["hint"] = "",
                            ["description"] = "疯狂伴随着紫色流萤虫，至少一些人是这么说的。另一些人则认为，受过谢尔格拉关注的人会吸引这种昆虫。不管怎么说，也许这种小虫子真接受过谢尔格拉那微妙的“祝福”。",
                            ["name"] = "紫色流萤虫",
                            ["id"] = 7282,
                        },
                        [7283] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6563,
                            ["icon"] = "/esoui/art/icons/pet_whitetorchbug.dds",
                            ["hint"] = "",
                            ["description"] = "有些人认为受到美瑞蒂亚的青睐就像用赤手空拳紧紧握住一把双刃剑一样危险。不过如果你做了什么她喜欢的事情，她倒是有可能会送给你一只白色流萤虫，这可能是她手中最安全的一份礼物了！",
                            ["name"] = "白色流萤虫",
                            ["id"] = 7283,
                        },
                        [7284] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6564,
                            ["icon"] = "/esoui/art/icons/pet_pinktorchbug-copy.dds",
                            ["hint"] = "",
                            ["description"] = "一些思坦达的追随者声称，如果谁看到了一只粉色流萤虫，那这个人就必须在转天的黄昏到来之前做一些极具怜悯与恩慈的善举。如果取悦了思坦达，这个可爱的小家伙就有可能跟随此人一段时间。",
                            ["name"] = "粉色流萤虫",
                            ["id"] = 7284,
                        },
                        [1141] = 
                        {
                            ["category"] = "无畏者半身像",
                            ["furnitureId"] = 4364,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranxyvkin001.dds",
                            ["hint"] = "完成（老兵模式）心灵地穴 I 后获得的奖励。",
                            ["description"] = "一尊铜制半身像，以纪念无畏者在心灵地穴 I 的胜利。",
                            ["name"] = "半身像：伊拉姆布里斯双子",
                            ["id"] = 1141,
                        },
                        [7286] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 6566,
                            ["icon"] = "/esoui/art/icons/mount_pyrewatchjackal.dds",
                            ["hint"] = "",
                            ["description"] = "很久以前，神秘教团看火人将本地的胡狼培育成了坐骑，好让自己在巡逻时能快速往返于各个他们的诅咒洞穴。现在，你也可以把这只迅捷灵敏的白色坐骑买回家！",
                            ["name"] = "看火人胡狼",
                            ["id"] = 7286,
                        },
                        [7287] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6567,
                            ["icon"] = "/esoui/art/icons/mount_icereachwickersteed.dds",
                            ["hint"] = "",
                            ["description"] = "一柄被抛弃的恋人用过的染血魔族匕首。一滴滴受到莫拉格·巴尔折磨的人流下的痛苦之泪。当这些物品在邪恶的冰境女巫团仪式中被使用时，它们有助于塑造一匹条编骏马，这骏马配得上所有人心中最大的梦魇，也就是你。",
                            ["name"] = "冰境条编骏马",
                            ["id"] = 7287,
                        },
                        [7288] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 6568,
                            ["icon"] = "/esoui/art/icons/mount_shadowcapcavesenche.dds",
                            ["hint"] = "",
                            ["description"] = "“拜阿兹达尔所赐，对于影耀森切这种可怕的猫科坐骑来说，蓝色光芒是它们最显眼的特点。洞穴探险者们十分珍视这种会发光的家伙，它们能轻而易举地照亮最黑暗的洞穴。”——海隆·格雷克洛格",
                            ["name"] = "影耀森切",
                            ["id"] = 7288,
                        },
                        [7289] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 6569,
                            ["icon"] = "/esoui/art/icons/mount_fungiflarewolf.dds",
                            ["hint"] = "",
                            ["description"] = "“阿兹达尔的其中一项实验是为危险的森林和洞穴创造一种理想的狼骑。这种菌耀狼的性情十分凶残，是设计也是天性。毕竟，菌耀蘑菇本身就很致命。”——海隆·格雷克洛格",
                            ["name"] = "菌耀狼",
                            ["id"] = 7289,
                        },
                        [7290] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6570,
                            ["icon"] = "/esoui/art/icons/mount_embermouldwarhorse.dds",
                            ["hint"] = "",
                            ["description"] = "“为了尝试将火焰与真菌融合到一起，阿兹达尔创造出了第一匹余烬战马。这种坐骑由炖菜中常常用到的羊肚菌幻化而来，能在最黑暗的冬夜中照亮骑手的旅途。”——海隆·格雷克洛格",
                            ["name"] = "余烬战马",
                            ["id"] = 7290,
                        },
                        [7291] = 
                        {
                            ["category"] = "玩具类",
                            ["furnitureId"] = 6571,
                            ["icon"] = "/esoui/art/icons/mount_nightmarestickhorse.dds",
