                            ["hint"] = "",
                            ["description"] = "克罗普斯福特母鸡是许多西罗帝尔农庄心仪的名产，因为只要一只母鸡就可以保护整个鸡舍免受狐狸的侵害。克罗普斯福特的孩子们说，每当老鹰在空中盘旋，母鸡就会把他们赶进鸡舍。",
                            ["name"] = "克罗普斯福特母鸡",
                            ["id"] = 9377,
                        },
                        [9378] = 
