                            ["icon"] = "/esoui/art/icons/pet_daedriccollector.dds",
                            ["hint"] = "达成成就“觉醒之焰探险家”后获得。",
                            ["description"] = "“虽然我也认为这些火葬堆很火热，很吓人，但我不敢相信它们就像龙身上的虱子一样，就像一位不愿透露姓名的学者给我说的一样。不，恰恰相反，我认为它们是死地本土的变种。”——维·阿斯普布雷德",
                            ["name"] = "斯克里昂火葬堆",
                            ["id"] = 9409,
                        },
                        [11458] = 
                        {
