                            ["furnitureId"] = 9229,
                            ["icon"] = "/esoui/art/icons/pet_bluebloodfroghound.dds",
                            ["hint"] = "",
                            ["description"] = "“别让眼睛蒙蔽了你。这个小家伙是一个操纵大师。即便它嘴边还挂着一条青蛙腿，它也会让你相信，它已经有几个世纪没吃过东西了。尤里安诺斯在上，它确实是很让人难以抗拒。”——学者薇丽雅·森诺",
                            ["name"] = "蓝血蛙犬幼崽",
                            ["id"] = 11461,
                        },
