                            ["icon"] = "/esoui/art/icons/pet_navirechicken.dds",
                            ["hint"] = "",
                            ["description"] = "“这只鸡虽然看着普通，但它是我的幸运鸡。它总能给我找到小零食，比如苹果、陈年面包之类的东西。就好像它不想让我饿着一样。是不是很好？”——农夫昆汀",
                            ["name"] = "纳维尔鸡",
                            ["id"] = 12981,
                        },
                        [12980] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 10312,
                            ["icon"] = "/esoui/art/icons/pet_skuldafndovahfly.dds",
                            ["hint"] = "",
                            ["description"] = "经过与泰姆瑞尔其他地区的数代隔离，至日岛的都瓦蜓演变出了不同寻常的明亮色彩，看似是在向掠食者发出警告，但这种都瓦蜓本身并无毒性。",
                            ["name"] = "至日岛平原都瓦蜓",
                            ["id"] = 12980,
                        },
