                            ["furnitureId"] = 9230,
                            ["icon"] = "/esoui/art/icons/pet_saarthalshepherd.dds",
                            ["hint"] = "",
                            ["description"] = "“有这样一只狗陪伴左右，任何诺德人都会备感骄傲。我们的祖先很久以前就驯服了它们。从那时起，它们一直帮助我们看管羊群，吓跑掠食者，并防止不听话的孩子到处乱跑。”——农夫伊欧丽芙",
                            ["name"] = "萨塔尔牧羊犬",
                            ["id"] = 11464,
                        },
                        [11465] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9231,
                            ["icon"] = "/esoui/art/icons/pet_meridiatouchedasp.dds",
                            ["hint"] = "",
                            ["description"] = "光是看它在阳光下闪烁的样子，就知道这绝非普通的蛇。这种蛇会散发出一种虹彩魔法；当它直起身子时，它会用这种魔法来催眠猎物。即使是人类和精灵也难以抵挡它那令人迷醉的鳞片。",
                            ["name"] = "美瑞蒂亚触之毒蛇",
                            ["id"] = 11465,
                        },
                        [12977] = 
                        {
                            ["category"] = "尼克斯牛虫",
                            ["furnitureId"] = 10309,
                            ["icon"] = "/esoui/art/icons/mount_goldennixoxsteed.dds",
                            ["hint"] = "",
                            ["description"] = "即使是透过岩灰的微弱阳光，也能将这种生物的金色甲壳照得闪闪发亮。金色的尼克斯牛虫既受商人追捧，用以展示自己的富裕，也被阿卡托什的信众视作美丽的象征。",
                            ["name"] = "黄金尼克斯牛虫战骑",
                            ["id"] = 12977,
                        },
                        [12976] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 10308,
                            ["icon"] = "/esoui/art/icons/mount_twilightkagoutidestroyer.dds",
                            ["hint"] = "",
                            ["description"] = "这只野兽的黑色皮毛上满是伤疤，向你无声诉说着它百战百胜的过往。它的眼光凶狠，显然刚被驯服不久，骑乘风险自负。",
                            ["name"] = "影暮盾角蜥破坏者",
                            ["id"] = 12976,
                        },
                        [12975] = 
                        {
                            ["category"] = "大型猫科动物",
