                        {
                            ["category"] = "助手",
                            ["furnitureId"] = 10579,
                            ["icon"] = "/esoui/art/icons/assistant_celiatydelostfleetbursar.dds",
                            ["hint"] = "",
                            ["description"] = "瑟莉亚·泰德虽是海盗，却能在失落舰队的船舱里，把你的金银财宝保护得万无一失。\r\n\r\n以太风的肆虐让你无法召唤她前往战场或西罗帝尔，但你和队友依然可以享受她提供的服务。",
                            ["name"] = "失落舰队财务主管瑟莉亚·泰德",
                            ["id"] = 13517,
                        },
                        [13518] = 
                        {
                            ["category"] = "助手",
                            ["furnitureId"] = 10580,
                            ["icon"] = "/esoui/art/icons/assistant_vokocarnavalweapondancer.dds",
                            ["hint"] = "",
                            ["description"] = "你和你的队友可以召唤沃科，在家园外调整和保存军械库出装方案，为即将到来的血腥战斗做准备。由于既无美酒也无热舞，他不会前往战场或西罗帝尔来为你们服务。",
                            ["name"] = "狂欢节武舞者沃科",
                            ["id"] = 13518,
                        },
                        [12972] = 
                        {
                            ["category"] = "特殊",
                            ["furnitureId"] = 10304,
                            ["icon"] = "/esoui/art/icons/mount_stonenestlandloper.dds",
                            ["hint"] = "",
                            ["description"] = "“至日岛的石巢部落有许多习俗的历史都可以追溯到落昏时期以前。他们使用魔法，如塑石一般塑造血肉。这些技艺在现代的村民中已经失传，但其在古老的造物中依旧鲜活。”——穆扎-忒伊，石巢涂鸦",
                            ["name"] = "石巢流浪者",
                            ["id"] = 12972,
                        },
                        [1232] = 
                        {
                            ["category"] = "异域",
