                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_vitrine_senche.dds",
                            ["hint"] = "",
                            ["description"] = "“想到矮人机械坐骑，即所谓的机械动物时，人们会感到深渊精灵并不是在试图复制自然中的生物，而是对其加以改进。举个例子：琉璃森切。”——泰尔威·格莱恩，矮人学者",
                            ["name"] = "琉璃矮人森切",
                            ["id"] = 1253,
                        },
                        [1254] = 
