                        [12749] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 10228,
                            ["icon"] = "/esoui/art/icons/pet_russafeldfellrunner.dds",
                            ["hint"] = "",
                            ["description"] = "“保护者怀璐尔对我的高地鸵鸟实验不以为然，也许这个粉色的变种能让她明白我的厉害！它的饮食非常奇特，我认为这一定会非常有趣！”——奇怪的研究员",
                            ["name"] = "绯红圣地高地鸵鸟",
                            ["id"] = 12749,
                        },
                        [11502] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 9256,
                            ["icon"] = "/esoui/art/icons/mount_silverlimnedguarcharger.dds",
                            ["hint"] = "",
                            ["description"] = "“我的沼泽伙伴不理解我为什么选择了这只野兽。他们说它领地意识强，脾气古怪。但你只需读懂它的讯号。就像现在，它的尾巴在抖动。要是你想保住你那可爱的手指，那就赶紧抽回手。”——风暴城的斯克海耶斯",
                            ["name"] = "银边冲锋瓜尔",
                            ["id"] = 11502,
                        },
                        [12745] = 
                        {
                            ["category"] = "异域",
