                            ["icon"] = "/esoui/art/icons/pet_stripedpangritnymphling.dds",
                            ["hint"] = "",
                            ["description"] = "“如果你需要有个能自己照顾自己、危险时刻会自己藏起来的小伙伴，那不妨找一只条纹小宁芙来养养看吧。这种可爱的小家伙就喜欢蜷着身子和你睡同一个被窝！”——马厩主塞苏拉",
                            ["name"] = "条纹潘格瑞小宁芙",
                            ["id"] = 12745,
                        },
                        [11504] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 9262,
                            ["icon"] = "/esoui/art/icons/pet_brumaspottedpig.dds",
                            ["hint"] = "",
                            ["description"] = "“绝对不行。我们不能留下它！猪只是家畜，仅此而已。别用那种眼神看我。好吧，我承认它非常可爱。而且很柔软。但我们还是不能留下它。我们会为它找到一个好人家。”——在布鲁玛偶然听到的对话",
