                            ["icon"] = "/esoui/art/icons/housing_uni_inc_handfan001.dds",
                            ["hint"] = "达成成就“夏暮岛的圣遗物”即可获得。",
                            ["description"] = "这把扇子可以让持有者变换成他人的脸，尽管代价是逐渐失去自我。",
                            ["name"] = "假面之扇",
                            ["id"] = 5460,
                        },
                        [12263] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 9819,
                            ["icon"] = "/esoui/art/icons/mount_lambentshoalmount.dds",
                            ["hint"] = "",
                            ["description"] = "“毫无疑问，这是一种奇怪的生物。它究竟是太靠近海边而染上魔力的熊，还是碰巧长得像熊的海洋魔物，这我也说不清楚。无论哪样，它都是个游泳好手。”——法师修者厄尔万·科特雷特",
                            ["name"] = "浅滩熊",
                            ["id"] = 12263,
                        },
                        [8460] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 7270,
                            ["icon"] = "/esoui/art/icons/mount_ayleidwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“那些在向高岩撤离期间骑着奈纳拉塔狼的人会在大军的前方探路，充当斥候的角色。许多人都在记录中提到了内纳盖，这匹狼对隐藏的危险似乎有着预知的能力，并且还能将危险提示给自己的骑手。”——昭示者贝尔达默",
                            ["name"] = "奈纳拉塔野精灵狼",
                            ["id"] = 8460,
                        },
                        [8513] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 7341,
                            ["icon"] = "/esoui/art/icons/mount_deadlandsguar.dds",
                            ["hint"] = "",
                            ["description"] = "它那鲜艳的橙色皮毛暗示着这匹瓜尔坐骑的起源和性情。虽然它出生成形于火热的死地，但你有能力将其磨练成一匹凶猛但忠诚的坐骑。",
                            ["name"] = "死地瓜尔",
                            ["id"] = 8513,
                        },
                        [12260] = 
                        {
                            ["category"] = "森切战猫",
                            ["furnitureId"] = 9816,
                            ["icon"] = "/esoui/art/icons/mount_ardorsdevotionsencheraht_fix2.dds",
                            ["hint"] = "",
                            ["description"] = "“为何是花？因为在下觉得花朵美丽，仅此而已。冲锋陷阵并不妨碍我们欣赏花之绚烂。战场花瓣遍地，亦是一大奇景。”——玛丝-约",
                            ["name"] = "热诚森切战猫",
                            ["id"] = 12260,
                        },
                        [12259] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 9814,
                            ["icon"] = "/esoui/art/icons/mount_hollowsoulsteed.dds",
                            ["hint"] = "",
                            ["description"] = "“无垠暗夜，横亘奥比斯诸位面之间，此乃虚无之境外围深渊。所幸栖居空无者寥寥无多。其至怪至异，超乎常人想象。”——阿赞达尔·阿尔-塞比亚底斯",
                            ["name"] = "虚魂战骑",
                            ["id"] = 12259,
                        },
                        [12258] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 9813,
                            ["icon"] = "/esoui/art/icons/mount_wildburntigerlynx.dds",
                            ["hint"] = "在达成“西威尔德的救星”成就后获得。",
                            ["description"] = "“追随晨曦之道的人需要有信念。我们正在回归我们的根源，回到野精灵曾使用的古老魔法。你不能指望它毫无杂质。不过，森林之神会提供一切所需。”——瓦沙巴的祭司诺特拉斯",
                            ["name"] = "燃野猞猁",
                            ["id"] = 12258,
                        },
                        [7515] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 6639,
                            ["icon"] = "/esoui/art/icons/mount_curseboundbear.dds",
                            ["hint"] = "",
                            ["description"] = "受到死灵法师诅咒的熊会变成邪恶、容易被激怒的野兽。这些变异熊只会效忠于它们的主人，并且面临危险毫不畏惧，这使它们成为优秀的战斗伙伴。",
                            ["name"] = "咒缚熊",
                            ["id"] = 7515,
                        },
                        [7516] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 6640,
                            ["icon"] = "/esoui/art/icons/mount_curseboundsenche.dds",
                            ["hint"] = "",
                            ["description"] = "受到不死诅咒的剑齿虎的吼声可以将一个灵魂撕成碎片，至少独孤城吟游诗人学院的人是这么说的。然而，这并不能阻止野心勃勃的死灵法师试图驯服这些可怕的生物。",
                            ["name"] = "咒缚剑齿虎",
                            ["id"] = 7516,
                        },
                        [7517] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6641,
                            ["icon"] = "/esoui/art/icons/mount_cursebondhorse.dds",
                            ["hint"] = "",
                            ["description"] = "光荣且致命；威严且震撼。这匹装备精良的骏马忠心耿耿地为它的主人效力，尽管其噩梦般的外表曾在岩潭周边地区引发了关于它是一种食尸鬼的传言。",
                            ["name"] = "咒缚马",
                            ["id"] = 7517,
                        },
                        [5470] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 5410,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_zenithauroran.dds",
                            ["hint"] = "",
                            ["description"] = "据说美瑞蒂亚的奥罗兰人在泰姆瑞尔需要坐骑时，就会从一道纯洁的光中召唤出这些闪亮的战马。虽然是这样，但它们的确足够强壮，能够配合重甲战士发起冲锋！",
                            ["name"] = "奥罗兰顶峰战马",
                            ["id"] = 5470,
                        },
                        [7519] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 6643,
                            ["icon"] = "/esoui/art/icons/mount_sabercatorange.dds",
                            ["hint"] = "",
                            ["description"] = "这种体态轻盈的坐骑身上那奇异的黑白色彩使其出场时令人眼前一亮。不过要当心！卡斯追猎者会通过舔你的脸来向你表达爱意。",
                            ["name"] = "卡斯追猎者剑齿虎",
                            ["id"] = 7519,
                        },
                        [7520] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 6644,
                            ["icon"] = "/esoui/art/icons/mount_duradachbear.dds",
                            ["hint"] = "",
                            ["description"] = "这种熊最初由古老的阴森尖牙瑞驰氏族驯化并作为坐骑饲养，后来，它们被诺德人在劫掠中捕获，并受到越来越多诺德人的青睐。尽管它们天性温顺，但当受到威胁时，它们会立即发怒。",
                            ["name"] = "逐达奇山熊",
                            ["id"] = 7520,
                        },
                        [7521] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6645,
                            ["icon"] = "/esoui/art/icons/mount_legionzero.dds",
                            ["hint"] = "",
                            ["description"] = "背信弃义的零之军团战斗法师们用禁忌的魔族法术凭空召唤出了这些强大的战马。在战场上看到这种来自异界的冲锋战马，真是让人既恐惧又惊叹。",
                            ["name"] = "零之军团冲锋战马",
                            ["id"] = 7521,
                        },
                        [7522] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 6646,
                            ["icon"] = "/esoui/art/icons/mount_valedeerxb.dds",
                            ["hint"] = "",
                            ["description"] = "如果在晚上看到这只麋鹿，它的周身会散发出微弱的光芒。那景象简直可以与天际北部天空中奇异的颜色变化，或是黑降巨大洞穴中的发光真菌相媲美。漂亮极了！",
                            ["name"] = "松樱峡谷麋鹿",
                            ["id"] = 7522,
                        },
                        [7523] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 6647,
                            ["icon"] = "/esoui/art/icons/mount_valedeerp4.dds",
                            ["hint"] = "",
                            ["description"] = "法师公会的学者们声称，这只麋鹿身上的蓝色光芒是与生俱来的：它们是由一束纯净的光凝聚而成的，这束光受到了阿祖拉的祝福，照落在一片飘摇的雪花上。又或者，正如其他人所说，它蔚蓝色的光泽源自于它经常食用的蓝草菇。",
                            ["name"] = "飞雪峡谷麋鹿",
                            ["id"] = 7523,
                        },
                        [7524] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 6648,
                            ["icon"] = "/esoui/art/icons/mount_valedeerpc.dds",
                            ["hint"] = "",
                            ["description"] = "一些人声称有鬼魂附在这匹骄傲的生物身上，使它散发出诡异的光芒；另一些人则认为这种光芒和它常吃的发光植物和真菌有关。不管怎样，骑上它，你都会觉得自己像是在空中滑翔。",
                            ["name"] = "冰灰峡谷麋鹿",
                            ["id"] = 7524,
                        },
                        [1381] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 4472,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_shadow-ghost.dds",
                            ["hint"] = "",
                            ["description"] = "几乎与其他所有的狼都不同，暗影幽灵狼没有狼群，它们在静谧的荒野和荒原上孤独地生活，它们只会偶尔在夜间出现。有人怀疑它们根本不是凡间位面的真正物种。",
                            ["name"] = "暗影幽灵狼",
                            ["id"] = 1381,
                        },
                        [7526] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6650,
                            ["icon"] = "/esoui/art/icons/pet_batwhite.dds",
                            ["hint"] = "",
                            ["description"] = "“这些蝙蝠是纯白色的，在风雪中很难看到它们。但只要给它吃一点香蕉，它就会粘在你身边一段时间。如果经常喂它吃香蕉和其他水果呢？那你就是它的好伙伴了。”——周游学者塔南德拉",
                            ["name"] = "雪喉果蝠",
                            ["id"] = 7526,
                        },
                        [7527] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6651,
                            ["icon"] = "/esoui/art/icons/pet_batblack.dds",
                            ["hint"] = "",
                            ["description"] = "“通常你不会看到这些黑蝙蝠，因为它们喜欢待在洞穴和人迹罕至的地方。然而，如果经过训练，这些家伙就会把你当作它们群体中的一员，而且不愿意离开你的身边。”——周游学者塔南德拉",
                            ["name"] = "影速蝙蝠",
                            ["id"] = 7527,
                        },
                        [7528] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6652,
                            ["icon"] = "/esoui/art/icons/pet_batbrown.dds",
                            ["hint"] = "",
                            ["description"] = "“受到这些棕色蝙蝠祝福的人们几乎不会受到昆虫的袭扰。它们白天喜欢躲在你的背包里，而当你晚上睡觉时，它们就会出来帮你驱赶虫子。”——周游学者塔南德拉",
                            ["name"] = "棕塔蝙蝠",
                            ["id"] = 7528,
                        },
                        [7529] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6653,
                            ["icon"] = "/esoui/art/icons/pet_batspotted.dds",
                            ["hint"] = "",
                            ["description"] = "“这些黑白蝙蝠有时被称为大篷车之友，它们穿梭于干旱地区的仙人掌丛中。当需要的时候，人们便会跟随它们的粪便寻找水分充足、安全可用的仙人掌。这种生物很容易训练为同伴。”——周游学者塔南德拉",
                            ["name"] = "花斑仙人掌蝙蝠",
                            ["id"] = 7529,
                        },
                        [7530] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 6654,
                            ["icon"] = "/esoui/art/icons/pet_batorange.dds",
                            ["hint"] = "",
                            ["description"] = "“多么鲜艳的色彩啊！常见于果园、农场和其他种植水果与鲜花的地方。它们对于觅食者和旅行者来说是无价的伴侣，因为它们能带你找到食物。”——周游学者塔南德拉",
                            ["name"] = "暮火蜜蝠",
                            ["id"] = 7530,
                        },
                        [7531] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6655,
                            ["icon"] = "/esoui/art/icons/pet_bardscollegegryphon.dds",
                            ["hint"] = "",
                            ["description"] = "传说在吟游诗人学院的开幕演出中，迪贝拉将一只这种欢快的狮鹫雏鸟送给了学院，并把它记录为学院内所属的第一个生物。",
                            ["name"] = "吟唱女神狮鹫幼雏",
                            ["id"] = 7531,
                        },
                        [7532] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6656,
                            ["icon"] = "/esoui/art/icons/pet_lynxumbral.dds",
                            ["hint"] = "",
                            ["description"] = "几十年前，诺德人曾流传过一个故事：一只隐遁的深色皮毛猞猁吃掉了那些无法进入松加德的灵魂。想象一下，当诺德人袭击瑞驰原住民时，发现这些猞猁竟被瑞驰人用来看家，他们是如此的惊讶。",
                            ["name"] = "影暮条纹猞猁",
                            ["id"] = 7532,
                        },
                        [7533] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 6657,
                            ["icon"] = "/esoui/art/icons/pet_goatvariant.dds",
                            ["hint"] = "",
                            ["description"] = "雪漫斑驳山羊以其固执的性格以及在恶劣条件下的攀爬能力而闻名。它会选择一个最喜欢的人并试图跟随他。挺可爱的是吧？只要你觉得它们用头撞你时也很可爱就好。",
                            ["name"] = "雪漫斑驳山羊",
                            ["id"] = 7533,
                        },
                        [7534] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6658,
                            ["icon"] = "/esoui/art/icons/pet_frostbitespider.dds",
                            ["hint"] = "",
                            ["description"] = "“我失去了许多训练有素的冰啮蜘蛛，因为独孤城的人们把它们当作有攻击性的害虫。于是我搬到城外，现在要把它们送出去了。它们都经受过训练，能分泌毒液，并且随时可以成为你旅途中的伙伴！”——独孤城的赫罗凯拉",
                            ["name"] = "冰啮蜘蛛",
                            ["id"] = 7534,
                        },
                        [7535] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 6659,
                            ["icon"] = "/esoui/art/icons/pet_palepasshare.dds",
                            ["hint"] = "",
                            ["description"] = "有胆识的商人会去寻找并捕捉这些可爱的小生物，称它们为“兔子”，或者，如果买家喜欢准确一些或者礼貌一些的说法，就称它们为苍白密道山兔。真是太可爱了！",
                            ["name"] = "苍白密道山兔",
                            ["id"] = 7535,
                        },
                        [7536] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 6660,
                            ["icon"] = "/esoui/art/icons/pet_graysphynx.dds",
                            ["hint"] = "",
                            ["description"] = "“这些有洁癖的猫会带来图瓦卡的祝福，并在它们选择的家庭中占据荣耀的位置。此外，它们通常会在死期将近之人的身边睡觉，所以我们尊崇它们，并将其当作遥远海岸的向导。”——周游学者塔南德拉",
                            ["name"] = "图瓦卡的斯芬克斯猫",
                            ["id"] = 7536,
                        },
                        [1393] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 4475,
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_guar_a.dds",
                            ["hint"] = "",
                            ["description"] = "烈焰侍灵被召唤自因弗内斯的湮灭位面，那是一个炽热的界域，熔岩在地表流动，那里的魔族都是在火焰中生存的物种。这种侍灵几乎能以任何形态被召唤至泰姆瑞尔，甚至是瓜尔形态！",
                            ["name"] = "烈焰侍灵瓜尔",
                            ["id"] = 1393,
                        },
                        [1394] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 4476,
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_bear_a.dds",
                            ["hint"] = "",
                            ["description"] = "据说海丝特拉女皇率领大军将吸血鬼斯特里奇国王和他的灰宿军驱赶至西落锤省时，正是骑着名为“火热乌苏拉”的烈焰侍灵熊。",
                            ["name"] = "烈焰侍灵熊",
                            ["id"] = 1394,
                        },
                        [1395] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 4477,
                            ["icon"] = "/esoui/art/icons/mounticon_guar_shadow-ghost.dds",
                            ["hint"] = "",
