                            ["description"] = "“我一直都更喜欢驼鹿，而不是麋鹿或马。在战斗中它们更可靠，而且强壮得吓人，对陆地旅行来说，它们简直无人能敌。而且它们的鼻子真的好柔软！”——匕落的伊冯·赛利勒",
                            ["name"] = "海鬼双骑驼鹿",
                            ["id"] = 11643,
                        },
                        [11644] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 9362,
                            ["icon"] = "/esoui/art/icons/mount_ashbonesabrecat.dds",
                            ["hint"] = "",
                            ["description"] = "“是的，这很不错。它就像我的主人一样充满了复仇和诅咒情绪。它也带有玛拉卡斯的标记——我们的敌人必将在我们面前畏缩颤抖！愿它在我们骑行的那条颠簸道路上洒满猎物的鲜血。”——强大的奥格玛什",
                            ["name"] = "尘骨剑齿虎",
                            ["id"] = 11644,
                        },
                        [11645] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9363,
                            ["icon"] = "/esoui/art/icons/pet_ashborneechalette.dds",
                            ["hint"] = "",
                            ["description"] = "即便体型娇小，这只鹿角野猪幼崽也颇为凶猛。它不惧用那小小的獠牙去顶撞它认为的威胁、其他鹿角野猪幼崽，或者任何动的东西。这并非一种有效的战术，但这种行为却让人觉得它莫名的可爱。",
                            ["name"] = "尘骨鹿角野猪幼崽",
                            ["id"] = 11645,
                        },
                        [11646] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9383,
                            ["icon"] = "/esoui/art/icons/pet_goldcrestancestorlizard.dds",
                            ["hint"] = "",
                            ["description"] = "“看看这无与伦比的鳞片！我都不知道如此实用的蜥蜴居然这么美。也许这就是它的用途？它的存在就是要在沼泽中传播美丽？我将沉浸在这样的美当中，看看希思特是否会给予我更多的洞见。”——风暴城的多虑之士",
                            ["name"] = "金冠古蜥",
                            ["id"] = 11646,
                        },
                        [11647] = 
                        {
                            ["category"] = "异域",
