                        },
                        [5552] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 5423,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_rahdmanthra.dds",
                            ["hint"] = "",
                            ["description"] = "当堕落虎人从末世之暗骑行而来时，他们就骑着这些可怕的骏马：堕落黑骏！它们是来自暗月的灵魂，还是有形的邪恶生物？",
                            ["name"] = "堕落黑骏马",
                            ["id"] = 5552,
                        },
                        [5553] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 5424,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_wolf.dds",
                            ["hint"] = "",
                            ["description"] = "“沼泽里几乎每一位马厩主都有各种各样精良的有鳞蜥蜴坐骑可供购买，一切都是干皮人熟悉的，但专门适用于深沼泽骑行。我们的蜥蜴坐骑是如此方便，如此有鳞又风度翩翩！”——乌卡斯帕",
                            ["name"] = "蜥蜴狼骑",
                            ["id"] = 5553,
                        },
                        [5554] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5425,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_senche.dds",
                            ["hint"] = "",
                            ["description"] = "“不止一次有人问我， ‘乌卡斯帕，为什么你的蜥蜴坐骑长得这么像泰姆瑞尔其他地方的坐骑？为什么你如此帅气的蜥蜴坐骑长得一点儿都不像蜥蜴？ ’这些个问题问得好啊！”——利尔莫斯的乌卡斯帕",
                            ["name"] = "蜥蜴森切",
                            ["id"] = 5554,
                        },
                        [5555] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 5426,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_guar.dds",
                            ["hint"] = "",
                            ["description"] = "“有些干皮人问， ‘既然瓜尔已经算是一种沼泽爬行类坐骑了，为什么还要杂交出像瓜尔一样的蜥蜴坐骑呢？那不会有点多此一举吗？ ’这些干皮人的洞察力异常敏锐！”——利尔莫斯的乌卡斯帕",
                            ["name"] = "蜥蜴瓜尔骑",
                            ["id"] = 5555,
                        },
                        [5556] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 5427,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_camel.dds",
                            ["hint"] = "",
                            ["description"] = "“也许创造出蜥蜴骆驼骑就是为了能让我们这样英勇的亚龙人冒险家可以在类似安奎那这样气候干旱的地方旅行，或者是为了让英勇的虎人冒险家可以在黑沼泽有坐骑可用。我不知道，我就是想要拥有一头。”——希姆·贾斯",
                            ["name"] = "蜥蜴骆驼骑",
                            ["id"] = 5556,
                        },
                        [5557] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 5428,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_bear.dds",
                            ["hint"] = "",
                            ["description"] = "“所以，它是一头熊。只不过也是一只蜥蜴。而且你还能骑它？肖尔的骨头啊！我需要知道的就是这些。我要了！”——知名诺德使节桀骜者里古特",
                            ["name"] = "蜥蜴熊骑",
                            ["id"] = 5557,
                        },
                        [5558] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 5429,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_horse.dds",
                            ["hint"] = "",
                            ["description"] = "“有时候亚龙人想花很长时间进行长途旅行，这时候人们会怎么办？骑上坐骑！如此一来，实用的蜥蜴就变成了形态各异的蜥蜴马，然后亚龙人就可以骑着它们，人高马大，威风凛凛！”——利尔莫斯的乌卡斯帕",
                            ["name"] = "蜥蜴马",
                            ["id"] = 5558,
                        },
                        [5559] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5430,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_frost.dds",
                            ["hint"] = "",
                            ["description"] = "第仁尼氏族的一个冰霜法师花了她一辈子的光阴完善一个法术，只为了可以永久召唤一头剑齿虎模样的寒霜侍灵。（为什么？谁知道呢？巴尔菲拉岛是个奇怪的地方。）",
                            ["name"] = "寒霜侍灵剑齿虎",
                            ["id"] = 5559,
                        },
                        [5560] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 5431,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_shellback.dds",
                            ["hint"] = "",
                            ["description"] = "亚龙人重装部队有一个非正式的诨名叫硬汉。所以不可避免地，他们的重骑兵坐骑也被称作硬汉战马。这类战马是众所周知的最强壮的品种。",
                            ["name"] = "硬汉战马",
                            ["id"] = 5560,
                        },
                        [5561] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 5432,
                            ["icon"] = "/esoui/art/icons/mounticon_guar_glowgill.dds",
                            ["hint"] = "",
                            ["description"] = "“这些荧鳃瓜尔坐骑来自阿肯附近的一个海滨氏族。它们可真英俊，不是吗？我听说它们可以通过那些鳃在水下呼吸，尽管我个人还未验证这是否属实。”——利尔莫斯的马厩主，乌卡斯帕",
                            ["name"] = "荧鳃瓜尔",
                            ["id"] = 5561,
