                            ["icon"] = "/esoui/art/icons/houseguest_keshutheblackfin.dds",
                            ["hint"] = "",
                            ["description"] = "战争英雄兼吉德昂总督凯叙在寻求和平与良伴的同时，也在努力改善撒西勒人民的生活。将凯叙添加到你的家中后，你可以为她设置行动路径，你和访客们还能和她聊天。",
                            ["name"] = "黑鳍凯叙",
                            ["id"] = 11924,
                        },
                        [10708] = 
                        {
                            ["category"] = "多人坐骑",
