                            ["icon"] = "/esoui/art/icons/housing_uni_inc_eso10thanniversarytavernpainting001.dds",
                            ["hint"] = "",
                            ["description"] = "如此多的面孔，如此多的故事。在这幅其乐融融的画作中选择你最喜欢的伙伴，重温十年的冒险历程。",
                            ["name"] = "画作：10周年庆典",
                            ["id"] = 13789,
                        },
                        [11656] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 9493,
                            ["icon"] = "/esoui/art/icons/mount_pyrodraconiccamellizard.dds",
                            ["hint"] = "",
                            ["description"] = "“它当然不是真正的龙。这无关紧要。浓烈的着色、喷吐着硫磺，还融合了木精灵和泰尔瓦尼的魔法技艺？告诉奥瑟瑞，契约已经履行，而且超乎预期。”——魔导师瓦尔肯内尔",
                            ["name"] = "炎龙骆驼蜥",
                            ["id"] = 11656,
                        },
                        [11652] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9474,
                            ["icon"] = "/esoui/art/icons/pet_thorngecko.dds",
                            ["hint"] = "",
                            ["description"] = "“老尖刺当然不是最可爱的宠物，但他向来十分忠诚。我偶尔会扔给他一些蛆虫，然后他就跟着我到处走。我觉得他想要的是陪伴，而不仅仅是零食。”——捕兽者马西恩",
                            ["name"] = "荆棘壁虎",
                            ["id"] = 11652,
                        },
                        [5600] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5532,
                            ["icon"] = "/esoui/art/icons/pet_205_pumpkinnetch.dds",
                            ["hint"] = "",
                            ["description"] = "女巫庆典，是为了庆祝恐怖和死亡，也有一项肆意破坏的令人懊悔的传统，尤其在那些泰姆瑞尔年轻气盛的孩子中间盛行。所谓的“万圣杰克浮游者”就是这种玩法的受害者。",
                            ["name"] = "空心南瓜浮游者",
                            ["id"] = 5600,
                        },
                        [5601] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5442,
                            ["icon"] = "/esoui/art/icons/pet_234_snowgryphon.dds",
                            ["hint"] = "",
                            ["description"] = "在伊顿尼尔的顶峰，在那积雪永不融化之地，生活着苍白的雪顶狮鹫。在第一纪元的绝大部分时间，它们都一直被认为只是个神话，因为它们完美地伪装在一种云端隐居的生活中。",
                            ["name"] = "雪顶狮鹫幼雏",
                            ["id"] = 5601,
                        },
