                        [11531] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 9344,
                            ["icon"] = "/esoui/art/icons/mount_companionrevelrybear.dds",
                            ["hint"] = "",
                            ["description"] = "“啊，这才是英雄所该拥有的野兽！别担心，忠诚的米娜娜在这里已经参与过多次战斗，足以赢得她现在所穿的护甲。无论洪丁指引你走向何方，她都将是你坚定的伙伴。”——龙卫扎芮娜",
                            ["name"] = "赛·萨汗的狂欢熊",
                            ["id"] = 11531,
                        },
                        [11530] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 9343,
                            ["icon"] = "/esoui/art/icons/pet_chorralretriever.dds",
                            ["hint"] = "",
                            ["description"] = "无论是短途出游还是远行，这些生性活泼的金色犬科动物都会愉快地陪伴在主人左右，并且一路上都能交到朋友。当然，这种令人喜爱的信任也有其缺点，那就是它们没法成为优秀的看门狗。",
                            ["name"] = "科洛尔寻回犬",
                            ["id"] = 11530,
                        },
                        [11523] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 9341,
                            ["icon"] = "/esoui/art/icons/mount_celestiallynx.dds",
                            ["hint"] = "",
                            ["description"] = "这种迅如急流，默如暗影的生物出现在泰姆瑞尔的许多民间故事中。在一些故事中，山猫在夜空中追逐猎物。在其他故事中，它是敏捷的同伴，非常适合那些在最黑暗之夜潜行的优秀猎人。",
                            ["name"] = "天界猞猁",
                            ["id"] = 11523,
                        },
                        [11522] = 
                        {
                            ["category"] = "乌萨克熊",
                            ["furnitureId"] = 9333,
                            ["icon"] = "/esoui/art/icons/mount_atmoransnowursauk.dds",
                            ["hint"] = "",
                            ["description"] = "尽管长相吓人，但经过适当的社会化训练，这些乌萨克熊会成为坚定的同伴。它们厚厚的皮毛和耐寒的体质使它们即使在最严酷恶劣的环境中也能茁壮成长，尤其是在泰姆瑞尔北部地区。",
                            ["name"] = "阿特莫拉乌萨克雪熊",
                            ["id"] = 11522,
                        },
                        [5619] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 5475,
                            ["icon"] = "/esoui/art/icons/pet_203_blackchicken.dds",
                            ["hint"] = "",
                            ["description"] = "这究竟只是一只面目有些狰狞的黑色家禽，还是来自奈恩之外的界域，也许来自梅鲁涅斯·大衮的死地或是玛拉卡斯的灰池？你敢问自己这个可怕的问题吗：它究竟是何方神圣？",
                            ["name"] = "恶魔小鸡",
                            ["id"] = 5619,
                        },
                        [5620] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 5476,
                            ["icon"] = "/esoui/art/icons/pet_215_roosterwhite.dds",
                            ["hint"] = "",
                            ["description"] = "这是一只在天际的白河流域四处可见的蛮横家鸡，据说它们最初繁衍于一个名叫溪木镇的古老村庄。它们的主人特别喜爱它们，要是谁胆敢伤害它们分毫，主人就会暴跳如雷。",
                            ["name"] = "溪木镇白母鸡",
                            ["id"] = 5620,
                        },
                        [11520] = 
                        {
                            ["category"] = "欧尔瑙格",
                            ["furnitureId"] = 9331,
                            ["icon"] = "/esoui/art/icons/mount_alterationornaug.dds",
                            ["hint"] = "",
                            ["description"] = "这只野兽是莎德阿斯图拉学生和法师公会学徒合作的结晶。有传闻称，它似乎稍微具有心灵感应的能力，几乎在骑手说出命令之前就能做出反应。颜色也是一个不错的加分项。",
                            ["name"] = "变异欧尔瑙格",
                            ["id"] = 11520,
                        },
                        [11519] = 
                        {
                            ["category"] = "无畏者战利品",
                            ["furnitureId"] = 9329,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyvaerminagloamknight001.dds",
                            ["hint"] = "通关理智边缘后获得的奖励。",
                            ["description"] = "从折磨者安苏尔处取得的战利品，以纪念无畏者在理智边缘的胜利。",
                            ["name"] = "奖杯：折磨者安苏尔",
                            ["id"] = 11519,
                        },
                        [11518] = 
                        {
                            ["category"] = "无畏者半身像",
                            ["furnitureId"] = 9328,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialvaerminagloamknight001.dds",
                            ["hint"] = "完成老兵模式的理智边缘后获得的奖励。",
                            ["description"] = "一尊铜制半身像，以纪念无畏者在理智边缘的胜利。",
                            ["name"] = "半身像：折磨者安苏尔",
                            ["id"] = 11518,
                        },
                        [11515] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9270,
                            ["icon"] = "/esoui/art/icons/pet_prismaticsenchecub.dds",
                            ["hint"] = "",
                            ["description"] = "“这只幼崽很特别，是的。它很美丽，且相当友好。虽然它也不是最温和的同伴，但其他人也这样评价过我。”——学者赞索拉",
                            ["name"] = "棱镜森切虎幼崽",
                            ["id"] = 11515,
                        },
                        [11514] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 9269,
                            ["icon"] = "/esoui/art/icons/pet_conjureddragonimp.dds",
                            ["hint"] = "",
                            ["description"] = "这一令人印象深刻的景象，是一只非常专注的幻术小鬼的杰作。它那闪烁的身姿激起了所有见者的爱慕，轻易地为这位号称“小龙”的家伙赢得了施舍和安全的栖身之地。",
                            ["name"] = "召唤出的恶魔龙",
                            ["id"] = 11514,
                        },
                        [11513] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9268,
                            ["icon"] = "/esoui/art/icons/pet_tinderflarevalefawn.dds",
                            ["hint"] = "",
                            ["description"] = "虽然乍看之下很是惊人，但这只小鹿对自己奇特而炽烈的身体似乎十分满意。这种神奇的生物是适者生存的极端例子，而那些能够驯服它的人会发现，它的背部可是在明火上烹饪的绝佳媒介。",
                            ["name"] = "毁灭山谷小鹿",
                            ["id"] = 11513,
                        },
                        [11508] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 9266,
                            ["icon"] = "/esoui/art/icons/mount_swordsingerstuftedcamel.dds",
                            ["hint"] = "",
                            ["description"] = "“洪丁知道他们看上去就走不快。但这实际上是件好事。没人期望你能走那么远的路。而且没有什么比一头全速冲向你的骆驼更可怕的事情了。”——商队员比拉米",
                            ["name"] = "剑咏者的簇冠骆驼",
                            ["id"] = 11508,
                        },
                        [11507] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 9265,
                            ["icon"] = "/esoui/art/icons/pet_emeraldoaknixad.dds",
                            ["hint"] = "",
                            ["description"] = "“翡翠橡木尼克萨德一直都以淘气著称。它们的颜色具有隐蔽性，能够很地隐身于森林中，等待毫无戒备的旅行者经过。离开这片森林时，旅行者就会发现，他们的口粮变轻了，尤其是甜食。”——黄金海岸野外指南",
                            ["name"] = "翡翠橡木尼克萨德",
                            ["id"] = 11507,
                        },
                        [11506] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9264,
                            ["icon"] = "/esoui/art/icons/pet_moonsugarmonkey.dds",
                            ["hint"] = "",
                            ["description"] = "“当这些家伙在你周围时，要小心你的月糖。它们眼神敏锐，双手灵巧。本人已经被祖兹杜偷走了不知多少次午餐。不过，只要它们愿意，它们也可以非常甜美可爱。可能是因为吃了那么多偷来的糖吧。”——塔哈拉",
                            ["name"] = "糖雪狐猴",
                            ["id"] = 11506,
                        },
                        [11505] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9263,
                            ["icon"] = "/esoui/art/icons/pet_lus_begottenhajmota.dds",
                            ["hint"] = "",
                            ["description"] = "这种哈吉鳄龟的醒目色彩看着或许很养眼，但那美丽的皮囊下隐藏着火爆的脾气。哈吉鳄龟向来都以脾气暴躁闻名，而这只哈吉鳄龟更是不容小觑。还好它太小了，只能咬到脚踝。",
                            ["name"] = "红宝石哈吉鳄龟",
                            ["id"] = 11505,
                        },
                        [11472] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 9232,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_hermaeusmorastatuette001.dds",
                            ["hint"] = "",
                            ["description"] = "从某种意义上来说，所有必然知晓者的雕像都是从异典通往奈恩的入口。考虑到这一点，当你邀请赫麦尤斯·莫拉入驻家中时，请务必小心谨慎。",
                            ["name"] = "小雕像：秘密之主莫拉",
                            ["id"] = 11472,
                        },
                        [11457] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 9220,
                            ["icon"] = "/esoui/art/icons/mount_brindlebear.dds",
                            ["hint"] = "",
                            ["description"] = "我只见过一次野生的布林德尔熊，但这种经历我以后再也不想有了。当时我正在森林里，准备把一头鹿装进袋里，那家伙发现了我。它发出了咆哮。我吓得一动不动。但它随后却径直走过我身边。它那时肯定已经吃饱了。”——科瓦奇的斯卡里乌斯·巴巴图斯",
                            ["name"] = "布林德尔熊",
                            ["id"] = 11457,
                        },
                        [11454] = 
                        {
                            ["category"] = "夫诸",
                            ["furnitureId"] = 9190,
                            ["icon"] = "/esoui/art/icons/mount_lightgiverindrik.dds",
                            ["hint"] = "",
                            ["description"] = "这只夫诸从头到蹄流金焕彩，着实散发出灵感之光。它或许就是瓦努斯·加里昂传说中的同伴。无论传说是否属实，其骑手都将看到一个充满闪耀思想和可能性的世界。",
                            ["name"] = "加里昂的夫诸",
                            ["id"] = 11454,
                        },
                        [11441] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9153,
                            ["icon"] = "/esoui/art/icons/pet_solstheimtundrawolf.dds",
                            ["hint"] = "",
                            ["description"] = "许多人命丧成年索塞姆狼之口。然而这一只是经过训练的品种。它的皮毛中仍然会闪耀着雪花，它总是喜欢在新的雪堆上嬉戏。在受到召唤时，它甚至还会献上冰冷的吻。",
