                            ["icon"] = "/esoui/art/icons/pet_star-orphan-fawn.dds",
                            ["hint"] = "",
                            ["description"] = "空灵的光芒从这只神秘的小鹿身上倾泻而出。有人说这是诸神的祝福，也有人认为这是魔族的把戏。尽管如此，能被这种难以捉摸的生物所信任，仍然是一件相当罕见的事情，这样也为其同伴创造了良好的环境。",
                            ["name"] = "孤星小斑点鹿",
                            ["id"] = 11237,
                        },
                        [11233] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8989,
                            ["icon"] = "/esoui/art/icons/pet_gingerpocketmammoth.dds",
                            ["hint"] = "",
                            ["description"] = "就像最初在骨岩洞附近驯养的袖珍猛犸象一样，这些生物是温顺可爱的优秀家畜。这一亚种因其独特的毛色而特别受到饲养者的青睐。",
                            ["name"] = "姜黄色袖珍猛犸象",
