                        [11232] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8968,
                            ["icon"] = "/esoui/art/icons/mount_lavenderguar2.dds",
                            ["hint"] = "",
                            ["description"] = "长期以来，瓜尔一直栖居在黑沼泽，因而成为了亚龙人的忠实伙伴。拉文德瓜尔与各自的骑手建立起深厚的情感联系这种事并不稀奇，它们会守在入睡的主人身边，亲昵地用嘴鼻轻蹭他们。",
                            ["name"] = "拉文德瓜尔",
                            ["id"] = 11232,
                        },
                        [11219] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 8965,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingu37firesonggalenzone001.dds",
                            ["hint"] = "",
                            ["description"] = "一幅画，展示的是布莱顿和德鲁伊混合风格建筑物，该建筑坐落在野生伽林植物丛中。",
                            ["name"] = "画：和谐伽林",
                            ["id"] = 11219,
