                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettedemonspire001.dds",
                            ["hint"] = "",
                            ["description"] = "一座微型卡尔格隆蒂德雕塑，卡尔格隆蒂德是掌控愤怒与恐惧的翡翠君主。",
                            ["name"] = "小雕像：卡尔格隆蒂德",
                            ["id"] = 11217,
                        },
                        [11210] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8951,
                            ["icon"] = "/esoui/art/icons/pet_clockworknixhound.dds",
                            ["hint"] = "",
                            ["description"] = "机械风尼克斯犬虫是源自索萨希尔隐藏实验室的一种人造体，它很小，但却栩栩如生。它甚至会“狩猎”并吃掉周遭的小金属碎片。请当心你的钱袋！",
                            ["name"] = "机械风尼克斯犬虫",
                            ["id"] = 11210,
                        },
                        [11209] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8950,
                            ["icon"] = "/esoui/art/icons/pet_ebonyscarab.dds",
                            ["hint"] = "",
                            ["description"] = "“父亲创造的一些东西有时候会令人害怕，因为它们会嘶嘶作响，还会发出断断续续的声音，但这只小甲虫不是这样的。毕竟，它明亮的光芒确实能够驱赶我床底下的怪物。”——制造者安扎尔夫的女儿",
                            ["name"] = "乌木矮人甲虫",
                            ["id"] = 11209,
                        },
                        [11204] = 
                        {
                            ["category"] = "夫诸",
                            ["furnitureId"] = 8937,
                            ["icon"] = "/esoui/art/icons/mount_hollowjackindrik.dds",
                            ["hint"] = "",
                            ["description"] = "“扭曲的树枝，死亡的气息，以及荆棘中的舞蹈。只要来几声嚎叫，并滴落几滴鲜血，邪恶的火焰就会熊熊燃烧。使用幽魂附体的骨头搅拌，然后发出尖叫来呼唤我。要是能得到我的认可，你将获得一匹可折磨你敌人梦境的坐骑。”——万圣杰克魔神",
                            ["name"] = "万圣杰克夫诸",
                            ["id"] = 11204,
                        },
                        [11203] = 
                        {
                            ["category"] = "瓦尔德瓦克",
                            ["furnitureId"] = 8936,
                            ["icon"] = "/esoui/art/icons/mount_ashmournvvardvark.dds",
                            ["hint"] = "",
                            ["description"] = "最初，瓦尔德瓦克被其创造者视为一种错误，不料它竟大受欢迎，促使泰尔瓦尼的魔导师不断扩展其培育规模。这种深色坐骑非常适合载着骑手加入悼念先祖的丧葬队伍。",
                            ["name"] = "灰烬哀悼者瓦尔德瓦克",
                            ["id"] = 11203,
                        },
                        [11202] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 8934,
                            ["icon"] = "/esoui/art/icons/mount_starorphanelk.dds",
                            ["hint"] = "",
                            ["description"] = "“经过数周的搜寻，我终于在地平线上瞥见了那只显耀的野兽。我以为那是美瑞蒂亚制造的幻象，但它随后踏上了冰冻的苔原，我的手感受到了它呼吸的温暖。”——法师阿布佐罗格的日记",
                            ["name"] = "孤星麋鹿",
                            ["id"] = 11202,
                        },
                        [9775] = 
                        {
                            ["category"] = "陆行狮鹫",
                            ["furnitureId"] = 7951,
                            ["icon"] = "/esoui/art/icons/mount_aurielicquasigriff.dds",
                            ["hint"] = "",
                            ["description"] = "这只陆行狮鹫几乎在破壳而出的时候就被人从巢里带走了，它被宠爱得很好，打扮得很像奥瑞尔的神兽。它金色的羽毛被巴尔菲拉的弓箭手用作箭杆上的装饰。",
                            ["name"] = "奥瑞尔陆行狮鹫",
                            ["id"] = 9775,
                        },
                        [11201] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 8933,
                            ["icon"] = "/esoui/art/icons/mount_alkoshs-blessing-lion.dds",
                            ["hint"] = "",
                            ["description"] = "“于是，艾尔克许将一只闪耀着纯净光芒的伙伴赐给了他的勇士。勇士驾着这只野兽，踏上了崇高的道路。无论这只雄狮的爪子踏在何处，光明和正义都将随后到达。”——《高鬃之路》，译文版",
                            ["name"] = "福佑长鬃雄狮",
                            ["id"] = 11201,
                        },
                        [11200] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8932,
                            ["icon"] = "/esoui/art/icons/houseguest_filbertcienne.dds",
                            ["hint"] = "",
                            ["description"] = "准备好了解更多关于瘟疫魔神佩伊特的信息了吗？那费尔伯特就会来拜访并分享他的知识。将费尔伯特添加到你的家中后，你可以为他设置行动路径，你和访客们还能和他聊天。",
                            ["name"] = "费尔伯特·希恩",
                            ["id"] = 11200,
                        },
                        [11180] = 
                        {
                            ["category"] = "无畏者半身像",
