                        },
                        [11121] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8821,
                            ["icon"] = "/esoui/art/icons/pet_telvannihermitcrab.dds",
                            ["hint"] = "",
                            ["description"] = "寄居蟹的适应能力极强。来自泰尔瓦尼半岛的寄居蟹以中空的蘑菇伞为家，并在暗精灵的花园中充当装饰品。",
                            ["name"] = "半岛寄居蟹",
                            ["id"] = 11121,
                        },
                        [11120] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 8820,
                            ["icon"] = "/esoui/art/icons/pet_discorddremnaken.dds",
                            ["hint"] = "",
                            ["description"] = "德雷曼肯幼崽不喜欢攻击性的行为。令人遗憾的是，抓挠下巴和拍头也在此之列。事实上，最好连最温和的眼神接触都应避免。",
                            ["name"] = "敏感的德雷曼肯幼崽",
                            ["id"] = 11120,
                        },
                        [11072] = 
                        {
                            ["category"] = "矮人蜘蛛",
                            ["furnitureId"] = 8704,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerdwarvenspider.dds",
                            ["hint"] = "",
                            ["description"] = "“剧烈的震颤破坏了矮人制造的蜘蛛。‘它闻起来恶臭无比。让我们来帮维威克领主把它的运行机制修好。它的永久存在势必会在我们中间引发必要的改变。’于是，它与熊一起加入了队伍。”——剑骑士萨里斯的日记",
                            ["name"] = "博雅剑骑士矮人蜘蛛",
                            ["id"] = 11072,
                        },
                        [11071] = 
                        {
                            ["category"] = "公羊",
                            ["furnitureId"] = 8703,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerram.dds",
                            ["hint"] = "",
                            ["description"] = "“这只好奇的有角野兽闻了闻食物，之后转身离去。‘啊，好奇心驱使它行动，但谨慎使其冷静克制。对于维威克领主的研究来说，这是一种聪明的野兽。也许它能让愚人开智增慧，令智者焕发希望。’这就是它的结局。”——剑骑士萨里斯的日记",
                            ["name"] = "博雅剑骑士公羊",
                            ["id"] = 11071,
                        },
                        [9784] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7952,
                            ["icon"] = "/esoui/art/icons/mount_tyrigelsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“在哨兵城以外的任何地方旅行时，请骑上这些花斑动物。它们比我养过的所有森切薮猫都更喜爱炎热。这让我相信：几十年前，夏暮岛的流浪汉在附近的土匪洞穴里把它们抚养长大的故事。”——马夫伯尔汉",
                            ["name"] = "花斑森切薮猫",
                            ["id"] = 9784,
                        },
                        [9785] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7953,
                            ["icon"] = "/esoui/art/icons/pet_nightcrestfellrunn.dds",
                            ["hint"] = "",
                            ["description"] = "亚龙人的农民把高地鸵鸟的羽毛成袋卖给猎人。即使是一只苍白的高地鸵鸟臂章，也能让猎人偷偷穿过暗木的沼泽而不被发现。",
                            ["name"] = "夜峰高地鸵鸟",
                            ["id"] = 9785,
                        },
                        [7738] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6724,
                            ["icon"] = "/esoui/art/icons/pet_valefawn.dds",
                            ["hint"] = "",
                            ["description"] = "虽然这只可爱的小鹿的颜色与它的亲属不同，但首先映入人们眼帘的是这只小鹿珍珠般的白色。只要给予它足够的照顾，你就能帮助它克服害羞，让它在你身边嬉戏。",
                            ["name"] = "谷小鹿",
                            ["id"] = 7738,
                        },
                        [7739] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6725,
                            ["icon"] = "/esoui/art/icons/pet_valefawnred.dds",
                            ["hint"] = "",
                            ["description"] = "一位勘探者声称：“夜玫瑰的红色光芒从它诞生时便有了。如果天空是红色的，小鹿也是红色的。”虽然有些人对此嗤之以鼻，但所有人都同意一件事：夜玫瑰对危险有一种第六感，它会唤醒任何被选中的家庭。",
                            ["name"] = "夜玫瑰谷小鹿",
                            ["id"] = 7739,
                        },
                        [7740] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6726,
                            ["icon"] = "/esoui/art/icons/pet_valefawnyellow.dds",
                            ["hint"] = "",
                            ["description"] = "它琥珀般的金色光芒创造了一种温暖，一位马厩主说，“它可以让你在天际的星空下度过寒冷的夜晚。”你只需要让小鹿时不时地舔一口蜂蜜，就能让它留在你身边。",
                            ["name"] = "安伯辛谷小鹿",
                            ["id"] = 7740,
                        },
                        [7741] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6727,
                            ["icon"] = "/esoui/art/icons/pet_valefawngreen.dds",
                            ["hint"] = "",
                            ["description"] = "有一段时间，学者们认为只有一种谷小鹿存在。现在，人们有了更好的了解，为什么会有这种变化呢？小鹿才不在乎。但是，附着绿色闪光的小鹿品种更喜欢赛跑。要是把它认作同伴的话，它甚至可能与你赛跑呢！",
                            ["name"] = "翡翠谷小鹿",
                            ["id"] = 7741,
                        },
                        [7742] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6728,
                            ["icon"] = "/esoui/art/icons/pet_valefawnpurple.dds",
                            ["hint"] = "",
                            ["description"] = "一位研究谷小鹿的学者指出，紫色的紫秋谷小鹿喜欢吃花。它的名字来源于天际一个现已消失的充满植物的洞穴。“给它一朵花，它是你一生的朋友！”你手里有花吗？",
                            ["name"] = "兰花谷小鹿",
                            ["id"] = 7742,
                        },
                        [9791] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8021,
                            ["icon"] = "/esoui/art/icons/pet_magmaskinsalamander.dds",
                            ["hint"] = "",
                            ["description"] = "途歇城的强盗想要用这些生物来骚扰镇上的贵族，但事与愿违后，他们卖掉了自己的股票。你很幸运，这些蝾螈在被出售前接受了忠诚训练。",
                            ["name"] = "苹果背蝾螈",
                            ["id"] = 9791,
                        },
                        [11070] = 
                        {
                            ["category"] = "欧尔瑙格",
                            ["furnitureId"] = 8702,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerornag.dds",
                            ["hint"] = "",
                            ["description"] = "“翠绿的欧尔瑙格先是满心喜悦，继而又感到绝望。‘它享受着离开笼子的自由，但缺乏目标又让它萎靡不振。或许维威克领主可以让它加入我们之列。’于是，它加入了其他三匹坐骑之列。”——剑骑士萨里斯的日记",
                            ["name"] = "博雅剑骑士欧尔瑙格",
                            ["id"] = 11070,
                        },
                        [5697] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 5562,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_apex_horse.dds",
                            ["hint"] = "",
                            ["description"] = "“在沼泽深处的浓重湿气里很难点燃营火，对吧？但你要是有焦热蜥蜴马那就不一样了！要是有个这样的坐骑，你就永远不会再吃到冷的炖鳗鱼了！”——乌卡斯帕，利尔莫斯的马厩主",
                            ["name"] = "焦热蜥蜴马",
                            ["id"] = 5697,
                        },
                        [5698] = 
                        {
                            ["category"] = "矮人蜘蛛",
                            ["furnitureId"] = 5563,
                            ["icon"] = "/esoui/art/icons/mounticon_dwarvenspider_flame..dds",
                            ["hint"] = "",
                            ["description"] = "来自死域熔炉的矮人蜘蛛坐骑是如此的与众不同，这位矮人学者指出它们可能都出自同一深渊精灵工匠之手。”——盖莱恩·马里列",
                            ["name"] = "死域矮人蜘蛛",
                            ["id"] = 5698,
                        },
                        [5699] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5564,
                            ["icon"] = "/esoui/art/icons/pet_219_flamedwarvenspider.dds",
                            ["hint"] = "",
                            ["description"] = "来自死域熔炉的矮人小蜘蛛是如此的与众不同，这位矮人学者指出它们可能都出自同一深渊精灵工匠之手。”——盖莱恩·马里列",
                            ["name"] = "死域矮人小蜘蛛",
                            ["id"] = 5699,
                        },
                        [11068] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 8700,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerbear.dds",
                            ["hint"] = "",
                            ["description"] = "“这只狂暴的熊尽管为锁链所缚，却仍发出令人胆寒的咆哮声。‘让我们用这只双色野兽来取悦维威克领主吧。在一个充斥着胆怯低语的世界中，它的咆哮声充满了希望。’于是，一切开始了。”——剑骑士萨里斯的日记",
                            ["name"] = "博雅剑骑士熊",
                            ["id"] = 11068,
                        },
                        [9797] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8054,
                            ["icon"] = "/esoui/art/icons/pet_driftwaterhajmota.dds",
                            ["hint"] = "通过使用25个来自高岛幽灵庇护湾的珊瑚哈吉鳄龟诱饵和25个来自猩红币尖塔的珊瑚哈吉鳄龟诱饵获得。",
                            ["description"] = "这些哈吉鳄龟原产于西斯忒斯群岛，喜欢在沿海地区生活，在那里它们长时间浸泡在水下，珊瑚都长在了它们身上。所以，如果你喜欢在海滩上度过美好时光，这种凶猛的捕食者可能是一个很棒的海滩伙伴!",
                            ["name"] = "珊瑚哈吉鳄龟",
                            ["id"] = 9797,
                        },
                        [11059] = 
                        {
                            ["category"] = "助手",
                            ["furnitureId"] = 8996,
                            ["icon"] = "/esoui/art/icons/assistant_hoarfrost.dds",
                            ["hint"] = "",
                            ["description"] = "从塔库巴第四道沟中被召唤出来，尖啸冰霜将把你的货物（或你队友的货物）运到湮灭之地的冷焰坑去，以换取凡人的硬币。\r\n\r\n古代约缚让他们无法出现在西罗帝尔或战场上。",
                            ["name"] = "尖啸冰霜（塔库巴商人）",
                            ["id"] = 11059,
                        },
                        [10926] = 
                        {
                            ["category"] = "尼克斯牛虫",
                            ["furnitureId"] = 8685,
                            ["icon"] = "/esoui/art/icons/mount_urshilakunixox.dds",
                            ["hint"] = "",
                            ["description"] = "在成为厄施拉库的坐骑之前，这些色彩斑斓的生物的外壳被磨碎用作颜料。后来看到了它们作为快速坐骑的潜力，驯兽师训练它们执行侦察任务，经常以干泥掩盖这些鲜艳的颜色。",
                            ["name"] = "厄施拉库尼克斯牛虫",
                            ["id"] = 10926,
                        },
                        [10906] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 8681,
                            ["icon"] = "/esoui/art/icons/mount_anupadomaycamel.dds",
                            ["hint"] = "",
                            ["description"] = "“阿努，帕多枚，这只骆驼让我想起了它们。一个结束，另一个开始。一个开始，另一个结束。停滞和变化的条纹。唯一，永恒，完美。就像这只骆驼一样。快躲开，它要吐口水了。”——深翠哨兵阿塔扎尔",
                            ["name"] = "典型骆驼",
                            ["id"] = 10906,
                        },
                        [5705] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5565,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_apex_senche.dds",
                            ["hint"] = "",
                            ["description"] = "“这只霜冻蜥蜴森切相当稀有；它来自沼泽深处的一个部落，据说该部落致力于研究寒霜法术，以通过放慢生活速度来延长寿命。他们的希思特树上甚至挂满了冰柱（别管那到底是什么）！”——乌卡斯帕",
                            ["name"] = "霜冻蜥蜴森切",
                            ["id"] = 5705,
                        },
                        [5706] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 5566,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_apex_wolf.dds",
                            ["hint"] = "",
                            ["description"] = "“没有什么比骑着一个能在黑夜里发光还全身冒毒的坐骑进城更让人望而却步的了。当一个人来自于像黑沼泽那样奇怪的地方时，真的要走极端才能让人印象深刻。”——利尔莫斯的乌卡斯帕",
                            ["name"] = "蜥蜴毒狼",
                            ["id"] = 5706,
                        },
                        [5707] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 5567,
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_ringtail.dds",
                            ["hint"] = "",
                            ["description"] = "在阿卡维尔帝国统治末期其后裔就定居在了瑞门及其周边地区，本地环尾狼身上的某些特质使得它们十分受后裔们青睐，随后他们将其驯化并培育成了独特坐骑。",
                            ["name"] = "瑞门环尾狼",
                            ["id"] = 5707,
                        },
                        [5708] = 
                        {
                            ["category"] = "森切战猫",
                            ["furnitureId"] = 5568,
                            ["icon"] = "/esoui/art/icons/mounticon_monstroussenche_raht.dds",
                            ["hint"] = "",
                            ["description"] = "作为虎人中最大的亚种，或者说是“品种”，森切战猫睿智善战，在战斗中可以同时担任战士和坐骑两种角色。",
                            ["name"] = "森切战猫",
                            ["id"] = 5708,
