                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5569,
                            ["icon"] = "/esoui/art/icons/mounticon_senche_summersetserval.dds",
                            ["hint"] = "",
                            ["description"] = "“作为畜牧业的晶智副学者，我受拉纳蒂尔委派，来为我们的智者培育一种适合在田间劳作时骑乘的坐骑。现在我向大家自豪地展示我的成果：忠诚威严的森切薮猫！”——太阳要塞的柯德罗尔",
                            ["name"] = "晶智·森切薮猫",
                            ["id"] = 5709,
