                        [10881] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 8678,
                            ["icon"] = "/esoui/art/icons/mount_steedofrevelry.dds",
                            ["hint"] = "",
                            ["description"] = "在这匹淡黄色的骏马到来之前，花香已经先到了。白色和酒红色相间的马匹铠甲上，用银色和金色雕刻着狂欢之主桑吉恩的笑脸。你是否会相信这些虚幻的玫瑰和美酒所许下的诺言，在它们的引诱之下寻欢作乐？",
                            ["name"] = "桑吉恩狂欢天马",
                            ["id"] = 10881,
                        },
                        [5712] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5571,
                            ["icon"] = "/esoui/art/icons/pet_hajmota_slateback.dds",
                            ["hint"] = "",
                            ["description"] = "这种体型较小的哈吉鳄龟会潜伏在黑沼泽南部海岸的咸水入海口，身影会被浑浊的灰色潮水所掩盖。但当它们被人工养殖后，却出乎意料地成了讨人喜欢的宠物。",
