                        [5720] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5579,
                            ["icon"] = "/esoui/art/icons/pet_232_monarchorange.dds",
                            ["hint"] = "",
                            ["description"] = "黑脉金斑蝶迁徙在整个泰姆瑞尔南部都很常见，夏日期间在北部省份也能见到。据说黑脉金斑蝶代表现在，相比之下祖先圣蛾则代表着过去。",
                            ["name"] = "黑脉金斑蝶",
                            ["id"] = 5720,
                        },
                        [5721] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5580,
                            ["icon"] = "/esoui/art/icons/pet_252_dragonimp_green.dds",
                            ["hint"] = "",
                            ["description"] = "“哈哈！骗到你了，对吧？这东西看上去就跟个小龙一样，不是吗？当然，你应该很清楚这世上本来就没这东西。就是个长得有点像佩伊特的幻术小恶魔，你别说还真挺像小龙的！”——阿布努尔·萨恩",
                            ["name"] = "绿龙小恶魔",
                            ["id"] = 5721,
                        },
                        [5722] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 5581,
                            ["icon"] = "/esoui/art/icons/pet_242_jerboa.dds",
                            ["hint"] = "",
                            ["description"] = "“你说跳鼠？啊，对，那些活蹦乱跳的小个子雪鼠，长着大大的耳朵。灰烬之痕里有好多这种动物，如果你抓到一只还没长大的可以拿来当宠物，他们可是亲近人的毛茸茸小伙伴。我小时候就有一只！”——河堡镇的舒兹瑞",
                            ["name"] = "灰烬之痕跳鼠",
                            ["id"] = 5722,
                        },
                        [5723] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5582,
                            ["icon"] = "/esoui/art/icons/pet_218_brimstonenixad.dds",
                            ["hint"] = "",
                            ["description"] = "无畏派的地下探索者们都知晓一个传说，这些会点火的妖精会负责点亮每一个蜡烛，火把，以及地下能够点着的每一个提灯，黑暗里它们会在冒险者身前飞着，将那些东西都点亮。",
                            ["name"] = "硫磺熔岩尼克萨德",
                            ["id"] = 5723,
                        },
                        [9820] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8059,
                            ["icon"] = "/esoui/art/icons/houseguest_hezehk.dds",
                            ["hint"] = "",
                            ["description"] = "刚把这个劲头十足的斯卡芬从法格雷夫的奇想夫人店里买回来，他能立即给你的住所带来惊喜的欢乐气氛。在把赫泽科添加到你的家里后，你可以为他设置行动路径。另外，你和访客们还能和他聊天。",
                            ["name"] = "赫泽科",
                            ["id"] = 9820,
                        },
                        [9821] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8060,
                            ["icon"] = "/esoui/art/icons/houseguest_marafar.dds",
                            ["hint"] = "",
                            ["description"] = "在完成了最初的魔族研究后，玛拉法尔希望在协助阿蒂姆的圣遗物大师的过程中发现更多的秘密。你会支持她吗？让玛拉法尔进入你的家，你可以为她设置行动路径，你和访客们还能和她聊天。",
                            ["name"] = "圣遗物学徒玛拉法尔",
                            ["id"] = 9821,
                        },
                        [10873] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8676,
                            ["icon"] = "/esoui/art/icons/pet_spellscarsalamander.dds",
                            ["hint"] = "",
                            ["description"] = "“你可能会觉得被法术之疤扭曲的蝾螈肯定是恐怖的野兽，但我却发现在它们的形态下相互作用的能量非常迷人。并且无论天气如何，脚边有一只这东西总会让你感觉温暖或酷爽。”——学者奈法",
                            ["name"] = "法术之疤蝾螈",
                            ["id"] = 10873,
                        },
                        [10870] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8675,
                            ["icon"] = "/esoui/art/icons/pet_rimmenjerboa.dds",
                            ["hint"] = "",
                            ["description"] = "“我不确定这些可爱的跳鼠什么时候来瑞门的，不过应该刚来没多久。它们很讨厌，很闹腾。而且这只总是碍事，也许它想要干掉莎瑞丝蒂。”——学者莎瑞丝蒂",
                            ["name"] = "瑞门跳鼠",
                            ["id"] = 10870,
                        },
