                            ["furnitureId"] = 8670,
                            ["icon"] = "/esoui/art/icons/mount_abyssalguar.dds",
                            ["hint"] = "",
                            ["description"] = "泰尔瓦尼家族以其惨烈的学术内斗而闻名。在内海各处幽暗的洞穴中，被泰尔瓦尼家族驱逐的人形成了一个崇拜赫麦尤斯·莫拉的邪教，虽然被驱逐但他们依然渴求知识、力量以及有朝一日的……复仇。",
                            ["name"] = "起源论学者的瓜尔",
                            ["id"] = 10858,
                        },
                        [11873] = 
                        {
                            ["category"] = "地精犬",
                            ["furnitureId"] = 9557,
                            ["icon"] = "/esoui/art/icons/mount_sandsqualldurzog.dds",
                            ["hint"] = "",
                            ["description"] = "适应力极强的地精犬游荡在泰姆瑞尔的沙漠中，它们厚厚的皮肤能抵挡住粗糙沙粒的研磨，脖子和背部的羽毛则有助于散热。它们的沙色皮肤和耐旱特性使它们成为沙丘中的高效掠食者。",
                            ["name"] = "沙飑地精犬",
                            ["id"] = 11873,
                        },
                        [11874] = 
                        {
                            ["category"] = "四目兽",
                            ["furnitureId"] = 9558,
                            ["icon"] = "/esoui/art/icons/mount_dragontailwelwa.dds",
                            ["hint"] = "",
                            ["description"] = "这些性情暴躁的四目兽来自沃斯加，而且名不虚传。它们在艰苦的环境中变得强悍，对骑手任何微小的过失，无论是喂食迟了，还是鞍具稍微过紧，它们都乐于施以惩罚以示不满。",
                            ["name"] = "憎恨之岩四目兽",
                            ["id"] = 11874,
                        },
                        [10854] = 
                        {
                            ["category"] = "无畏者战利品",
