                            ["icon"] = "/esoui/art/icons/mount_coldharbourwelwa.dds",
                            ["hint"] = "",
                            ["description"] = "在冷港的荒废之地诞生的、莫拉格·巴尔的凶猛四目兽会以可怕的韧性追逐猎物。据说，一旦它们嗅到猎物的气味，只有暗锚的链条才能将这些野兽拉回。",
                            ["name"] = "锚生四目兽",
                            ["id"] = 11880,
                        },
                        [11881] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 9564,
                            ["icon"] = "/esoui/art/icons/mount_meownimarco.dds",
                            ["hint"] = "",
                            ["description"] = "这只猫科动物正盯着你，似乎在说：“你竟然企图摸我，真是狗胆包天！你认为区区鼠辈能阻止得了泰姆瑞尔有史以来最强大的猫术士吗？这个形态是我朝不朽目标迈出的第一步！来见识下我真正的猫咪力量！”",
                            ["name"] = "喵尼玛可",
                            ["id"] = 11881,
                        },
                        [7786] = 
                        {
                            ["category"] = "森切战猫",
                            ["furnitureId"] = 6729,
                            ["icon"] = "/esoui/art/icons/mount_curseboundraht.dds",
                            ["hint"] = "",
                            ["description"] = "阿巴哈达曾被认为是史迪奇中最棘手的班达理盗贼，却在灰烬之痕中遭遇了可怕的诅咒。她想找一个同伴帮她恢复以前的生机与活力。那个人是你吗？",
                            ["name"] = "咒缚森切战猫",
                            ["id"] = 7786,
                        },
                        [10709] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 8601,
                            ["icon"] = "/esoui/art/icons/mount_legionzerosabrecat.dds",
                            ["hint"] = "",
                            ["description"] = "在强迫剑齿虎喝下冷港之血后，零之军团士兵骑上了它们，为曼尼玛克占领了帝都贵族区。有许多士兵在战斗中阵亡，只留下没有了骑手的坐骑。至少对你来说，这是一件大好事。",
                            ["name"] = "零之军团剑齿虎",
                            ["id"] = 10709,
                        },
                        [7788] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 6730,
                            ["icon"] = "/esoui/art/icons/horse_goldensteed.dds",
                            ["hint"] = "",
                            ["description"] = "“据说，当一个德高望重的诺德人寻求一个光荣的结局时，松加德会给他派遣一匹敏捷的战马，带他去参加最后的战斗，但不要理会那些唱着多腿马的吟唱者。”—慧女茉莉塔",
                            ["name"] = "勇猛的松加德冲锋战马",
                            ["id"] = 7788,
                        },
                        [7789] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 6731,
                            ["icon"] = "/esoui/art/icons/mount_sovngardeclawthanewolf.dds",
                            ["hint"] = "",
                            ["description"] = "“松加德的利爪子爵狼时常会在鲸骨桥站岗，但也有些会选择陪伴勇敢的灵魂到天际或更远的地方。这些狼不仅高尚，而且很聪明。”——慧女茉莉塔",
                            ["name"] = "松加德利爪子爵狼",
                            ["id"] = 7789,
                        },
                        [7790] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 6732,
                            ["icon"] = "/esoui/art/icons/mount_goldensteedsabercat.dds",
                            ["hint"] = "",
                            ["description"] = "“柔韧的剑齿虎在松加德的英雄中很受欢迎，尤其是那些被称为英勇尖牙的英雄，它们为了保护骑手牺牲了自己。它们伫立在勇气之殿，等着把英雄送到需要帮助的勇士手中。”——慧女茉莉塔",
                            ["name"] = "松加德英勇尖牙剑齿虎",
                            ["id"] = 7790,
                        },
                        [11887] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 9569,
                            ["icon"] = "/esoui/art/icons/mount_nightmarepillioncharger.dds",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t多人坐骑（1个操控者，1个乘客）|r|",
                            ["description"] = "“当心偏僻的道路和无月的夜晚。警惕那些阴魂不散的蹄声。留意那些火炭般的眼睛，以及每一个坚定脚印所留下的炽烈轨迹。最重要的是，当心那些可怕骑士所走过的路径。”——泰姆瑞尔民间传说",
                            ["name"] = "梦魇双骑骏马",
                            ["id"] = 11887,
                        },
                        [10646] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8574,
                            ["icon"] = "/esoui/art/icons/pet_obsidiandwarvensphere.dds",
                            ["hint"] = "在达成成就“堡垒守护者”后获得。",
                            ["description"] = "奥辛纽姆的祖加尔兹声称，是她首先发现了这些黑曜石制成的矮人构造体。这一说法得到了她那些忠诚的构造体追随者的支持。她后来才得知，是自己的学者同伴将此物“赠予”了她，但她并不急于分享。",
                            ["name"] = "黑曜石矮人机械球",
                            ["id"] = 10646,
                        },
                        [10645] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8573,
                            ["icon"] = "/esoui/art/icons/mount_duskemberfox.dds",
                            ["hint"] = "",
                            ["description"] = "这些色彩斑斓的狐狸是一种罕见的景象，它们在野外一直躲在阴影里。当它们被驯化装上鞍具后，它们会自豪地展示自己精美的皮毛和精致的鞍具。它们最喜欢的食物是雪莓，为了获得它们最喜欢的零食，它们几乎什么都愿意做。",
                            ["name"] = "暮烬狐",
                            ["id"] = 10645,
                        },
                        [10644] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8572,
                            ["icon"] = "/esoui/art/icons/pet_pollenbat.dds",
                            ["hint"] = "",
                            ["description"] = "这种棕毛蝙蝠可以为希罗河两岸的花朵授粉。没有它们，瓦伦伍德的自然生态就会遭遇破坏。而且这种动物打喷嚏的时候很可爱。",
                            ["name"] = "希罗河花粉蝠",
                            ["id"] = 10644,
                        },
                        [7795] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 6734,
                            ["icon"] = "/esoui/art/icons/mount_sovngardebear.dds",
                            ["hint"] = "",
                            ["description"] = "“在急需之时，松加德会派出一些英雄回到世界，以及派出一些传奇野兽为他们服务。坚毅熊就是这样一种生物。它是一个无畏的伙伴，来带着真正的战士去战斗。”—慧女茉莉塔",
                            ["name"] = "松加德坚毅熊",
                            ["id"] = 7795,
                        },
                        [7796] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 6735,
                            ["icon"] = "/esoui/art/icons/mount_goldensteedguar.dds",
                            ["hint"] = "",
                            ["description"] = "“在战斗中倒下的瓜尔会在松加德获得一席之地。它们中的一些后来在我们中间穿行，为那些献身于英勇壮举的人充当忠诚勇敢的坐骑。一旦被召唤，它们就会迅速作出响应。”——慧女茉莉塔",
                            ["name"] = "英勇松加德瓜尔陆行者",
                            ["id"] = 7796,
                        },
                        [7797] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 6736,
                            ["icon"] = "/esoui/art/icons/camelmount_goldensteed.dds",
                            ["hint"] = "",
                            ["description"] = "“骆驼确实在松加德地区茁壮成长。当被召唤加入泰姆瑞尔的战斗时，这些灿烂的生物急切地向前奔跑，迎接它们英勇的骑手。不过，不要相信它们能吐出蜂蜜酒的谣言。”——慧女茉莉塔",
                            ["name"] = "灿烂松加德骆驼",
                            ["id"] = 7797,
                        },
                        [10633] = 
                        {
                            ["category"] = "乌萨克熊",
                            ["furnitureId"] = 8571,
                            ["icon"] = "/esoui/art/icons/mount_inkheartmonstrousbear.dds",
                            ["hint"] = "",
                            ["description"] = "“传说中，格拉特森林的古老橡树从深林中唤出了这些黑毛乌萨克熊。但是为什么呢？我听到的每个理由都不一样！有的说是让它们保护小树，有的说是让它们帮助解决狼人的问题，还有的说也许只是想要熊抱而已。”——云游四方的农场工人齐拉兹",
                            ["name"] = "墨色毛乌萨克熊",
                            ["id"] = 10633,
                        },
                        [10632] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8570,
                            ["icon"] = "/esoui/art/icons/pet_grahtwoodfisher.dds",
                            ["hint"] = "",
                            ["description"] = "“在我漫步在格拉特森林的每个清晨，都会有一只当地的捕手紧紧抓着附近一棵树的树干看着我。我猜它想吃一点我的早餐，所以在第三天，我与它分享了早餐。现在我走到哪它都跟着我。”——努尔莫",
                            ["name"] = "格拉特森林捕手",
                            ["id"] = 10632,
                        },
                        [10605] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8553,
                            ["icon"] = "/esoui/art/icons/pet_kvatchbrindlebearcub.dds",
                            ["hint"] = "",
                            ["description"] = "这些爱冒险的幼兽喜欢在瀑布里玩耍，经常在冬天把瀑布后面的裂缝当成巢穴。它们最喜欢黄油的味道，因此有人说是某位奶农首先驯服了其中一只幼兽。",
                            ["name"] = "布林德尔熊幼崽",
                            ["id"] = 10605,
                        },
                        [10604] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8552,
                            ["icon"] = "/esoui/art/icons/pet_duskfallancestorlizard.dds",
                            ["hint"] = "",
                            ["description"] = "“害怕改变会浪费你本可以用来把握当下的时间。这些黑暗生物是来自我们过去的礼物，赠送给冯-瓦斯忒和那些需要被引导到现在的人。”—默言者乌萨尔",
                            ["name"] = "落昏时期祖先蜥蜴",
                            ["id"] = 10604,
                        },
                        [10600] = 
                        {
                            ["category"] = "四目兽",
                            ["furnitureId"] = 8550,
                            ["icon"] = "/esoui/art/icons/mount_oilslickwelwa.dds",
                            ["hint"] = "",
                            ["description"] = "赫麦尤斯·莫拉的信徒们利用从禁忌之书《野兽转化之术》中学到的知识，将一头四目兽转化成了一头幽光闪烁的多色坐骑。莫拉允许自己在泰姆瑞尔最老练的代理人骑着它执行陆上任务。",
                            ["name"] = "落昏四目兽",
                            ["id"] = 10600,
                        },
                        [10599] = 
                        {
                            ["category"] = "森切战猫",
                            ["furnitureId"] = 8549,
                            ["icon"] = "/esoui/art/icons/mount_umbralstripesencheraht.dds",
                            ["hint"] = "",
                            ["description"] = "这只美丽的野兽在穿越迷宫时失去了自己的骑手。在离开迷宫之后，这只满身条纹的森切战猫希望能依靠神秘的帮助让自己重返迷宫。由于它的行动经常会使自己面临危机，因此努沙本希望能找到一位伙伴，陪伴其共同完成未来的漫长旅程。",
                            ["name"] = "暗影条纹森切战猫",
                            ["id"] = 10599,
                        },
                        [10587] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 8679,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_antsealkoshhourglass001_fx.dds",
                            ["hint"] = "",
                            ["description"] = "你可以把沙漏放在家里。专注于落下的沙子会让它们变得模糊，对当地时间的感知也会发生变化。时间似乎静止了，直至沙漏被搅乱。享受从永恒日出到无尽夜晚的一切吧。",
                            ["name"] = "艾尔克许的神圣沙漏",
                            ["id"] = 10587,
                        },
                        [10586] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 8547,
                            ["icon"] = "/esoui/art/icons/mount_mothermaramarehorse.dds",
