                        [5765] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 5583,
                            ["icon"] = "/esoui/art/icons/pet_228_stormnixad.dds",
                            ["hint"] = "",
                            ["description"] = "这一稀有而色彩斑斓的闪电尼克萨德虽然身上不带旋转电石，看上去就更像个小小的带翅膀的风暴侍灵了。它们相当忠诚——但它们也会让你的头发直立！",
                            ["name"] = "蓝闪电尼克萨德",
