                        [10429] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8434,
                            ["icon"] = "/esoui/art/icons/pet_purpleguar.dds",
                            ["hint"] = "",
                            ["description"] = "“你以为一只瓜尔不会与一个杀乌鸦的人和睦相处，但这个好家伙真的会这样做！也许这是精致的紫色色调？无论如何，最奇怪的是它开始把宝石留给那些小坏蛋。”——生物创造者伊拉斯蒂米尔·第仁尼",
                            ["name"] = "乌鸦场小瓜尔兽",
                            ["id"] = 10429,
                        },
                        [10427] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 8433,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_sacredshield001.dds",
                            ["hint"] = "在高岛完成“荣誉竞赛”任务后获得的奖励。",
                            ["description"] = "乔思琳·加里克女士直到最后一次才把她的船员安全带回了家——至少传说是这样说的。既然已经证明你值得继承她的遗产，你可以把这个著名的全旗海军船长盾牌挂到你的墙上了。",
                            ["name"] = "加里克夫人的圣盾",
                            ["id"] = 10427,
                        },
                        [10418] = 
                        {
                            ["category"] = "地精犬",
                            ["furnitureId"] = 8431,
                            ["icon"] = "/esoui/art/icons/mount_harrowforgeddurzog.dds",
                            ["hint"] = "",
                            ["description"] = "“血疫锻造地精犬：准备好你最猛的毒药和最强的咒语。你的目标击败了超乎你想象的恐怖之物才获得了这匹光荣的深红色坐骑。”——黑暗兄弟会新人手册的最新注释",
                            ["name"] = "血疫锻造地精犬",
                            ["id"] = 10418,
