                        [10399] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8416,
                            ["icon"] = "/esoui/art/icons/pet_goldcollaredwolfpup.dds",
                            ["hint"] = "",
                            ["description"] = "这只吵闹黑毛小狗的祖先可以一直追溯至斯格拉默的五百英豪。不过这并不妨碍它当个淘气的小毛球！",
                            ["name"] = "伙伴的狼崽",
                            ["id"] = 10399,
                        },
                        [10398] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8415,
                            ["icon"] = "/esoui/art/icons/mount_xitahranagonizer.dds",
                            ["hint"] = "",
                            ["description"] = "“这些顽固的生物可能看起来脑袋空空。然而，你就算激怒了欧尔瑙格，它们也能让你活下来。这就是忠诚坐骑的本性。”——马厩主塞苏拉",
                            ["name"] = "猩红战争潘格瑞",
                            ["id"] = 10398,
                        },
                        [10397] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8414,
                            ["icon"] = "/esoui/art/icons/pet_doomtruthpocketwatcher.dds",
                            ["hint"] = "",
                            ["description"] = "“你了解到什么了吗，恶眼魔？奈恩的凡人都会养一个小伙伴。哦，是吗？你是说名字吗？作为我的小伙伴，你想要一个名字？很好，就叫你奥库拉吧。你确实值得。”——莫瑞安·泽纳斯",
                            ["name"] = "暗语者之眼袖珍恶眼魔",
                            ["id"] = 10397,
                        },
                        [10396] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 8413,
                            ["icon"] = "/esoui/art/icons/pet_goldenglowchicken.dds",
                            ["hint"] = "",
                            ["description"] = "这种具有攻击性的家禽可通过它们燃烧的红色羽毛来轻松识别，它们被十字军骑士用来当作看门狗的替代品。他们的大声啼叫几乎让人睡不着觉。",
                            ["name"] = "远征者金币鸡",
                            ["id"] = 10396,
                        },
                        [10389] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 8412,
                            ["icon"] = "/esoui/art/icons/mount_blackheightscamel.dds",
                            ["hint"] = "",
                            ["description"] = "“你可能不会想到会在我的家乡黑色高地附近看到骆驼，但你错了！我们喜欢用颜料和一点光滑的油来装饰这些芳香的动物，这样它们既美丽又能运输！”——艺术家赫扎尔",
                            ["name"] = "黑色高地骆驼",
                            ["id"] = 10389,
                        },
                        [10384] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 8408,
                            ["icon"] = "/esoui/art/icons/mount_skingradpillioncourser.dds",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t多人坐骑（1个操控者，1个乘客）|r|",
                            ["description"] = "“斯金格拉德的第一只双骑坐骑是在里斯拉夫的两个兄弟姐妹希望骑行时少一些警卫的情况下产生的。他们被告知：‘一匹马两个警卫。’因此，他们创造了第一只身经百战的双人坐骑。”——马厩主里崇·查切尔",
                            ["name"] = "斯金格拉德双骑骏马",
                            ["id"] = 10384,
                        },
                        [10332] = 
                        {
                            ["category"] = "地精犬",
                            ["furnitureId"] = 8392,
                            ["icon"] = "/esoui/art/icons/mount_ragebounddurzog.dds",
                            ["hint"] = "",
                            ["description"] = "“这头野兽的狂怒只有它的骑手能控制住它。不幸的是，这些地精犬通常会选择那些允许自己经常发泄愤怒的骑手。”——马卡斯城的迈德瑞希·古弗隆",
                            ["name"] = "怒缚地精犬",
                            ["id"] = 10332,
                        },
                        [10331] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8391,
                            ["icon"] = "/esoui/art/icons/mount_rageboundkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "“你没听明白我说的，这些和普通的盾角蜥完全不同。暴怒、口吐白沫又大杀四方。还有他们的骑手，瞪大的眼睛充满了狂怒。这就是吸引我的地方。这就是我加入他们的原因。”——马卡斯城的迈德瑞希·古弗隆",
                            ["name"] = "怒缚盾角蜥",
                            ["id"] = 10331,
                        },
                        [10330] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 8390,
                            ["icon"] = "/esoui/art/icons/mount_rageboundbear.dds",
                            ["hint"] = "",
                            ["description"] = "“这只熊怪身上的每一块皮毛和骨头都会让它的骑手想起过去的战斗。愤怒终于平息，骑手从敌人手中夺过了胜利。我想，你知道这种感觉。它就在你的眼睛里。愤怒，勉强抑制下的愤怒。”——马卡斯城的阿帕那",
                            ["name"] = "怒缚熊",
                            ["id"] = 10330,
                        },
                        [9874] = 
                        {
                            ["category"] = "尼克斯牛虫",
                            ["furnitureId"] = 8063,
                            ["icon"] = "/esoui/art/icons/mount_rubyfiretorchnix.dds",
                            ["hint"] = "",
                            ["description"] = "“传说中，阿什·阿穆骑着第一只尼克斯牛虫上阵后，艾拉卜尼姆桑就驯服了这些发光的生物。虽然选择一头会发光暴露你位置的坐骑很奇怪，但有些战士就喜欢在战斗前增加危险。”——穆尔丁·阿斯伦",
                            ["name"] = "深红发光尼克斯牛虫",
                            ["id"] = 9874,
                        },
                        [9875] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 8064,
                            ["icon"] = "/esoui/art/icons/mount_darkflamecamel.dds",
                            ["hint"] = "",
                            ["description"] = "“一开始，贝扎蒂很生气。他们给他一头骆驼？贝扎蒂只骑不逊色于冲锋战马的坐骑。但他必须承认，他很喜欢这次的骑行。骆驼很平稳，速度快，步履稳健。甚至赫尔拉周围的岩石也没有给这头野兽带来任何麻烦。”——贝扎蒂游记",
                            ["name"] = "赫尔拉王权骆驼",
                            ["id"] = 9875,
                        },
                        [9876] = 
                        {
                            ["category"] = "地精犬",
                            ["furnitureId"] = 8065,
                            ["icon"] = "/esoui/art/icons/mount_graniteclawdurzog.dds",
                            ["hint"] = "",
                            ["description"] = "“花岗岩爪哥布林地精犬狼吞虎咽地吃着在西斯忒斯群岛周围游动的海洋生物。它们的纹饰帮助它们融入珊瑚礁，它们的羽毛可以防止水滴进眼睛。”——摘自两栖生物生理学",
                            ["name"] = "花岗岩爪地精犬",
                            ["id"] = 9876,
                        },
                        [11925] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 9601,
                            ["icon"] = "/esoui/art/icons/houseguest_kor.dds",
                            ["hint"] = "",
                            ["description"] = "猎人、黑暗兄弟会刺客、大哥——科尔的身份不止如此。邀请他到你的住所，他将与你分享他的人生洞见。将科尔添加到你的家中后，你可以为他设置行动路径，你和访客们还能和他聊天。",
                            ["name"] = "科尔",
                            ["id"] = 11925,
                        },
                        [11926] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 9602,
                            ["icon"] = "/esoui/art/icons/houseguest_hildegard.dds",
                            ["hint"] = "",
                            ["description"] = "这位初出茅庐的黑暗兄弟会刺客不在用狼人能力执行任务时，她就会静下来思考自己的双重天性。将希尔德加德添加到你的家中后，你可以为她设置行动路径，你和访客们还能和她聊天。",
                            ["name"] = "希尔德加德",
                            ["id"] = 11926,
                        },
                        [10326] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8386,
                            ["icon"] = "/esoui/art/icons/pet_stonelorewisp.dds",
                            ["hint"] = "",
                            ["description"] = "从耶弗尔那里派来的幽魂预示着雨手月的风暴。看到了它就意味着看到了新的成长、新的生命和大自然循环的新篇章。",
                            ["name"] = "伽林幽魂",
                            ["id"] = 10326,
                        },
                        [10318] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 8369,
                            ["icon"] = "/esoui/art/icons/mount_eveningstarice.dds",
                            ["hint"] = "",
                            ["description"] = "传说曾有一位雇佣兵在暴风雨中被她的领主抛弃。她冻僵的双唇祈求着帮助。桑吉恩听到了她的恳求，将冰块变成了一匹骏马。萨图拉里亚的清晨降临时，那位领主猩红的血液浸透了白雪和常青树的树枝。",
                            ["name"] = "萨图拉里亚冰马",
                            ["id"] = 10318,
                        },
                        [10317] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 8368,
                            ["icon"] = "/esoui/art/icons/pet_verdurousdaedrat.dds",
                            ["hint"] = "",
                            ["description"] = "“去年年中，我们发现魔鼠在偷吃我们的仪式补给。现在这些该死的东西都变绿了，大德鲁伊说它们是伽林通往湮灭之地的桥梁？哎！”——前匕落人卡莉斯·马伦斯",
                            ["name"] = "苔脊魔鼠",
                            ["id"] = 10317,
                        },
                        [10303] = 
                        {
                            ["category"] = "无畏者半身像",
                            ["furnitureId"] = 8348,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranspriggan001.dds",
                            ["hint"] = "完成（老兵模式）船工之憾地牢后获得奖励。",
                            ["description"] = "一尊铜制半身像，以纪念无畏者在船工之憾地牢的胜利。",
                            ["name"] = "半身像：娜扎莱",
                            ["id"] = 10303,
                        },
                        [10302] = 
                        {
                            ["category"] = "无畏者半身像",
                            ["furnitureId"] = 8347,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterancoralgryphon001.dds",
                            ["hint"] = "完成（老兵模式）珊瑚鹫巢后获得奖励。",
                            ["description"] = "一尊铜制半身像，以纪念无畏者在珊瑚鹫巢的胜利。",
                            ["name"] = "半身像：卡尔盖达",
                            ["id"] = 10302,
                        },
                        [10301] = 
                        {
                            ["category"] = "无畏者战利品",
                            ["furnitureId"] = 8346,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyspriggan001.dds",
                            ["hint"] = "完成“船工之憾地牢”后获得奖励。",
                            ["description"] = "从海精灵海盗处取得的战利品，以纪念无畏者在“船工之憾”的胜利。",
                            ["name"] = "战利品：娜扎莱",
                            ["id"] = 10301,
                        },
                        [10300] = 
                        {
                            ["category"] = "无畏者战利品",
                            ["furnitureId"] = 8345,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophycoralgryphon001.dds",
                            ["hint"] = "完成“珊瑚鹫巢”后获得奖励。",
                            ["description"] = "从瓦拉利昂处取得的战利品，以纪念无畏者在珊瑚鹫巢的胜利。",
                            ["name"] = "战利品：卡尔盖达",
                            ["id"] = 10300,
                        },
                        [10290] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8304,
                            ["icon"] = "/esoui/art/icons/mount_newmoonfox.dds",
                            ["hint"] = "",
                            ["description"] = "“不要低估新月邪教所训练出的狐狸。它们闪着光的猩红双眼足以警告你离开。如果你蠢到想要偷走一只成年狐狸，那就跟奈恩说再见吧。”——太阳行者乔纳特",
                            ["name"] = "新月狐狸",
                            ["id"] = 10290,
                        },
                        [10277] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8300,
                            ["icon"] = "/esoui/art/icons/pet_lemondotnetch.dds",
                            ["hint"] = "",
                            ["description"] = "“颜色看起来更明亮？音乐的气味各不相同？迪尔达斯有个性化动作？你可能正在体验罕见的柠檬点气母的通感毒液。放轻松，这是无害的。只是全新的视角，永远不会害死任何人的。”——炼金术士阿利农",
                            ["name"] = "柠檬点气母",
                            ["id"] = 10277,
                        },
                        [10244] = 
                        {
                            ["category"] = "四目兽",
                            ["furnitureId"] = 8286,
                            ["icon"] = "/esoui/art/icons/mount_speckledwelwa.dds",
                            ["hint"] = "",
                            ["description"] = "这种野蛮的四目兽引起了晶智学院的学员们的兴趣，他们甚至带了几只到席尔瓦沃德研究。为了让公众更喜爱它们，一位有事业心的保育员给它们套上鞍具，把它们“借到”野外去。",
                            ["name"] = "斑点四目兽",
                            ["id"] = 10244,
                        },
                        [10243] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8285,
                            ["icon"] = "/esoui/art/icons/pet_planemeldpony.dds",
                            ["hint"] = "",
                            ["description"] = "“现在，我对朋友说，看看这些暗锚碎片，没人用，没人有。我看着他的小马，这个病态的小东西，我得说，为什么不给咱们自己弄点好东西呢？”——“革新者”德兰",
                            ["name"] = "锚生小马",
                            ["id"] = 10243,
                        },
                        [10242] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8280,
                            ["icon"] = "/esoui/art/icons/mount_stormsurgehowler.dds",
                            ["hint"] = "通过达成“至高欺凌者”成就获得。",
                            ["description"] = "身上覆盖着珊瑚和藤壶，这种不寻常的海洋生物像湍急的水流一样移动，为它的骑手创造出平稳的旅行体验。有人推测，凯恩用海上风暴制作了它们，并把它们送到陆地上去寻找那些崇敬她的人。",
                            ["name"] = "风暴潮嚎狼",
                            ["id"] = 10242,
                        },
                        [10240] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8277,
                            ["icon"] = "/esoui/art/icons/pet_rustpeltsabrecat.dds",
                            ["hint"] = "",
                            ["description"] = "“我从哪儿弄来的猫？卡片。可怜的小家伙被一些走私宠物的混蛋拿来当货币使用。我在教她怎么数卡片，给我拿点酒来。”——私掠者马克",
                            ["name"] = "锈皮剑齿虎",
                            ["id"] = 10240,
                        },
                        [10239] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8276,
                            ["icon"] = "/esoui/art/icons/pet_damsonhermitcrab.dds",
                            ["hint"] = "通过达成“失落深渊探险家”成就获得。",
                            ["description"] = "在德鲁伊教之前，在富商之前，甚至在贵族住宅之前，寄居蟹便统治着整个西斯忒斯。无论它走到哪里，都会拖着自己的东西，用那圆溜溜的眼睛看着你，好像在说：“我和你，我们没什么不同。”",
                            ["name"] = "深紫红寄居蟹",
                            ["id"] = 10239,
                        },
                        [10238] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 8275,
                            ["icon"] = "/esoui/art/icons/pet_spottedbeardog.dds",
                            ["hint"] = "",
                            ["description"] = "莫萨尔城里獒犬的威望令这座城市居民的熊犬执照变得有点……傻。不管是照看孩子还是面对入侵者，总有人要挨揍。",
                            ["name"] = "莫萨尔城熊犬",
                            ["id"] = 10238,
                        },
                        [10237] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8274,
                            ["icon"] = "/esoui/art/icons/mount_handmaidensstormwolf.dds",
                            ["hint"] = "",
                            ["description"] = "虽然诺德人声称这头披着闪电的狼在寻找值得服侍的凯恩勇士，但石刻之识德鲁伊并不这么认为。只有自然界的不平衡才会导致这样一种生物的结合。它的目的？找到一个能恢复平衡的骑手罢了。",
                            ["name"] = "女战士之狼",
                            ["id"] = 10237,
                        },
                        [7110] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6541,
                            ["icon"] = "/esoui/art/icons/pet_durzogemberthroat.dds",
                            ["hint"] = "",
                            ["description"] = "因其邪恶的智慧而被培育出来的余烬地精犬，可能会智胜抚养它们长大的气母无赖哥布林。只有那些头脑更灵活的人才能让它们保持忠诚，而那个人可能就是你！",
                            ["name"] = "余烬地精犬",
                            ["id"] = 7110,
                        },
                        [7272] = 
                        {
                            ["category"] = "魔族",
                            ["furnitureId"] = 6552,
                            ["icon"] = "/esoui/art/icons/pet_wickerfrightbanekin.dds",
                            ["hint"] = "",
                            ["description"] = "“长久以来，女巫们始终拒绝透露有关召唤木骇灾星的秘密……不过最近她们改主意了。刚一出现，它那木讷的面容就挤出了一丝诡异的微笑。这么一看，还真挺吓人的！”——法士艾尔达",
                            ["name"] = "木骇灾星",
                            ["id"] = 7272,
                        },
                        [7506] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 6638,
                            ["icon"] = "/esoui/art/icons/housing_ayl_run_dbhstatuegarlasmalatarsmall001.dds",
                            ["hint"] = "",
                            ["description"] = "奥瑞尔的微型雕像，先祖神州神殿的主神，与一只鹰。",
                            ["name"] = "小雕像：奥瑞尔，古精灵王",
                            ["id"] = 7506,
                        },
                        [6406] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5978,
                            ["icon"] = "/esoui/art/icons/mount_newmoonsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“森切已经算是很安静的坐骑了。这一匹呢？它行动时就如同沉默的化身一般安静。”——太阳行者乔纳特",
                            ["name"] = "新月森切",
                            ["id"] = 6406,
                        },
                        [6404] = 
                        {
                            ["category"] = "骆驼",
                            ["furnitureId"] = 5976,
                            ["icon"] = "/esoui/art/icons/mount_newmooncamel.dds",
                            ["hint"] = "",
                            ["description"] = "“那些在黑暗的沙地上寻求出路的人应该考虑新月骆驼。有人说它以黑夜本身为食。我说可能就是这样吧。”——太阳行者乔纳特",
                            ["name"] = "新月骆驼",
                            ["id"] = 6404,
                        },
                        [102] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 4187,
                            ["icon"] = "/esoui/art/icons/pet_082.dds",
                            ["hint"] = "",
                            ["description"] = "当厄运狼幼崽用大大的红眼睛看着你时，你的内心可能就已经融化了——但只要你一转身，这小无赖就会撕碎你绣花的阿伦西亚枕头，并在你的草药园里刨洞。",
