                            ["icon"] = "/esoui/art/icons/pet_077.dds",
                            ["hint"] = "",
                            ["description"] = "它虽然看上去像是刚从死地深处爬上来的，但狱火赛普蝰蛇其实原生于落锤省的高海拔地区。作为宠物，它们……并不怎么亲切。但确是很棒的话题发起者。",
                            ["name"] = "狱火赛普蝰蛇",
                            ["id"] = 478,
                        },
                        [10209] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 8259,
                            ["icon"] = "/esoui/art/icons/pet_mottledsheep.dds",
                            ["hint"] = "",
                            ["description"] = "“她的镇定让我们的患者感到安心。有时我会询问他们在她的外套上会看到何种图案和形状，然后根据他们的回答来了解他们的心理状况。”——医师泰利尔",
                            ["name"] = "杂色绵羊",
                            ["id"] = 10209,
                        },
                        [10208] = 
                        {
                            ["category"] = "乌萨克熊",
                            ["furnitureId"] = 8258,
                            ["icon"] = "/esoui/art/icons/mount_glistergloambear.dds",
                            ["hint"] = "",
                            ["description"] = "“我们选择一些守护者是基于他们压倒性的存在感，比如这头乌萨克熊。骑着它的时候，我发誓我的骨髓和她的咆哮产生了共鸣。”——光湖的罗尔曼诺尔",
                            ["name"] = "光湖乌萨克熊",
                            ["id"] = 10208,
                        },
                        [10207] = 
                        {
