                            ["furnitureId"] = 8257,
                            ["icon"] = "/esoui/art/icons/mount_hearthfirelynx.dds",
                            ["hint"] = "",
                            ["description"] = "“在树木抖下自己五彩缤纷的外衣时，德鲁伊们聚集在耶弗尔召唤出的猞猁周围。在他们唱起圣歌时，歌声与森林之神将这只大猫变成了一匹坐骑。只有炉火月勇士才能拥有这样的坐骑。”——《繁叶之书》",
                            ["name"] = "采叶猞猁",
                            ["id"] = 10207,
                        },
                        [10206] = 
                        {
                            ["category"] = "鹿",
                            ["furnitureId"] = 8256,
                            ["icon"] = "/esoui/art/icons/mount_fireleafelk.dds",
                            ["hint"] = "",
                            ["description"] = "“在炉火月的第一个夜晚，全西斯忒斯的人们都会点燃受祝福的古火原木。烟雾与树叶的飒飒声混合在一起，灵体便会随之显形，这是一年中仅此一次的现象。它们会以忠实的麋鹿坐骑的形体出现。”——《繁叶之书》",
                            ["name"] = "古火麋鹿",
                            ["id"] = 10206,
                        },
                        [11959] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 9616,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodtandemsteed.dds",
                            ["hint"] = "",
                            ["description"] = "黑暗兄弟会的战马已习惯了在漆黑中奔跑，它们完全信任自己的骑手。倘若情势所需，哪怕身侧挂附多名骑手，战马们也丝毫不会畏缩，依然勇往直前。",
                            ["name"] = "黑暗兄弟会战马",
                            ["id"] = 11959,
                        },
                        [11960] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 9617,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodsabrecat.dds",
                            ["hint"] = "",
                            ["description"] = "作为一种坐骑，剑齿虎与黑暗兄弟会简直是天作之合。这种生物脚步轻盈、动作敏捷，其狩猎天性更与骑手相得益彰。许多黑暗兄弟会成员认为：剑齿虎坐骑本身便是西帝斯的一份馈赠。",
                            ["name"] = "黑暗兄弟会剑齿虎",
                            ["id"] = 11960,
                        },
                        [11961] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 9618,
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "“没错，西帝斯的确教导我们沉默。但倘若速度与力量皆占上风，那隐不隐匿也并非总是那么重要。所以我选择盾角蜥来当坐骑。我发现这种生物的凶悍野性足以弥补那些许噪音。”——黑暗兄弟波尔斯·欧维勒思",
                            ["name"] = "黑暗兄弟会盾角蜥",
