                            ["description"] = "“我在河堡镇马厩卖不出多少瓜尔，因为虎人很重视自己的尊严，他们不愿意骑这么傻的野兽。但是穿着龙鳞披甲的瓜尔可好看了！”——马夫倌扎尔比达胡兹",
                            ["name"] = "龙鳞披甲瓜尔",
                            ["id"] = 5873,
                        },
                        [5874] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 5618,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_senche.dds",
                            ["hint"] = "",
                            ["description"] = "“我们的远房表亲，森切坐骑，穿着龙鳞披甲简直太棒了，就像刚刚从沙丘城的古老墙楣中走出来的生物。也许这些讨厌的龙还是有点用处的，对吧？”——马夫倌扎尔比达胡兹",
                            ["name"] = "龙鳞披甲森切",
                            ["id"] = 5874,
                        },
                        [5875] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 5619,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_wolf.dds",
                            ["hint"] = "",
                            ["description"] = "“直到我看到穿戴龙鳞披甲的骑兵狼之前，我都一直以为赫尔卡恩狼是艾斯维尔最好的狼类坐骑。还有比它看起来更适合战斗的坐骑吗？”——马夫倌扎尔比达胡兹",
                            ["name"] = "龙鳞披甲狼",
                            ["id"] = 5875,
                        },
                        [5876] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 5620,
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_bear.dds",
                            ["hint"] = "",
                            ["description"] = "龙鳞披甲几乎是坐骑可以装备的最重的护甲，但是作为坐骑而培育的熊是如此的强壮，以至于它们几乎意识不到这重量。",
                            ["name"] = "龙鳞披甲熊",
                            ["id"] = 5876,
                        },
                        [5877] = 
                        {
                            ["category"] = "马",
