                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_horse.dds",
                            ["hint"] = "",
                            ["description"] = "“龙实在是很烦人，对吧？但是它们的鳞片能够打造如此精美的骏马护甲！龙鳞披甲战马可能是有史以来我见过的最犀利的坐骑！”——马夫倌扎尔比达胡兹",
                            ["name"] = "龙鳞披甲战马",
                            ["id"] = 5877,
                        },
                        [5878] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 5622,
                            ["icon"] = "/esoui/art/icons/mounticon_horse_speckled.dds",
                            ["hint"] = "",
                            ["description"] = "匕落花斑马是一种坚韧的马种，来自匕落和凯姆洛恩之间的格伦姆布拉的远望塔地区。它以其耐力而闻名，是长途骑手的最爱。",
                            ["name"] = "匕落花斑马",
                            ["id"] = 5878,
                        },
                        [5879] = 
                        {
                            ["category"] = "玩具类",
