                        [9977] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8067,
                            ["icon"] = "/esoui/art/icons/pet_aurorafirepotspider.dds",
                            ["hint"] = "",
                            ["description"] = "节日的感觉吗？让这只火罐蜘蛛跟着你吧！有了它可爱的炼金术灯光秀，你一定能照亮任何人的一天——包括你自己！",
                            ["name"] = "奥罗兰火罐蜘蛛",
                            ["id"] = 9977,
