                        [9978] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8068,
                            ["icon"] = "/esoui/art/icons/pet_salamanderponyguar.dds",
                            ["hint"] = "",
                            ["description"] = "“我好苦恼，小偷偷走了我这批小瓜尔！我本想送一些给我表弟的，他很喜欢我的蝾螈瓜尔，而他对小瓜尔可谓情有独钟。那些小偷最好给我小心点。”——生物创造者伊拉斯蒂米尔·第仁尼",
                            ["name"] = "蝾螈小瓜尔",
                            ["id"] = 9978,
                        },
                        [7931] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 6742,
                            ["icon"] = "/esoui/art/icons/assistant_birodar.dds",
                            ["hint"] = "",
                            ["description"] = "别被比罗·达尔的外表骗了！他不是一般的学者。事实上，他生性诙谐，爱惹麻烦。让比罗·达尔进入你的家，你可以为他设置行动路径，你和访客们还能和他聊天。",
                            ["name"] = "比罗·达尔",
                            ["id"] = 7931,
                        },
                        [9980] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8070,
                            ["icon"] = "/esoui/art/icons/pet_spottedechalette.dds",
                            ["hint"] = "",
                            ["description"] = "尽管奥辛纽姆兽人经常在神学上存在分歧，但它们却因为热爱这件鹿角野猪的皮毛而团结了起来。有人说，这是来自崔尼马克的祝福；其他人则说，这是来自玛拉卡斯的流亡者的烙印。不管怎样，这头野兽都是带来欢乐的源泉。",
                            ["name"] = "龟甲鹿角野猪",
                            ["id"] = 9980,
                        },
                        [9981] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8071,
                            ["icon"] = "/esoui/art/icons/mount_spellscarkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "这些被法术之疤周围不稳定魔法逼疯的盾角蜥，是令人惊讶的优秀宠物。与它们神志清醒、更具攻击性的同类相比，疯疯癫癫的盾角蜥很温顺，很容易接受命令。",
                            ["name"] = "法术之疤盾角蜥",
                            ["id"] = 9981,
                        },
                        [9982] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 8072,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“有人认为，这些骷髅森切响应了迷失灵魂寻求安全通行的呼唤。我坚信这和耶弗尔脱不了关系，希望有一天我能证明这一点。”——德鲁伊·斐列克",
                            ["name"] = "怨灵潮森切",
                            ["id"] = 9982,
                        },
                        [9983] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 8073,
                            ["icon"] = "/esoui/art/icons/mount_wraithhaunthorse.dds",
                            ["hint"] = "",
                            ["description"] = "“那天，一个石刻之识德鲁伊骑着这匹可怕的海生马匹咆哮而来，嗯……这么说吧，我很高兴我认出骑手是德鲁伊·朵尔瓦瑟。她那凶狠的表情会让我做噩梦的——这匹马也一样。”——橡木教团的侍从哈罗德",
                            ["name"] = "怨灵潮马",
                            ["id"] = 9983,
                        },
                        [9984] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 8074,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntguar.dds",
                            ["hint"] = "",
                            ["description"] = "“奥尔布林伯尔的鬼魂在贸易路上驱赶着发光的瓜尔，寻找着买家。不要被它们的外表吓跑了。或者，嗯……也许对你来说，能看到你坐骑的骨架是个吸引点？不管怎么说，去买一个吧。”——新人罗杰克",
                            ["name"] = "怨灵潮瓜尔",
                            ["id"] = 9984,
                        },
                        [9985] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 8075,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntbear.dds",
                            ["hint"] = "",
                            ["description"] = "“在水生法师聚集的地方，他们举行古老的仪式。他们联合起来，把熊、海洋和死亡的精髓结合在一起，形成他们中的一员可以骑乘的坐骑。或者说，传说是这样的。”——德鲁伊桑迪尔",
                            ["name"] = "怨灵潮熊",
                            ["id"] = 9985,
                        },
                        [9986] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8076,
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“与长生者交流有时很费解。我看到海水中诞生了一个不同寻常的狼群，像愤怒的海浪一样流动，给予了它们生命。经验证明，它们和其他狼一样对骑手忠诚。”——德鲁伊阿诺蒂勒",
                            ["name"] = "怨灵潮狼",
                            ["id"] = 9986,
                        },
                        [9683] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 7927,
                            ["icon"] = "/esoui/art/icons/mount_vineduskbear.dds",
                            ["hint"] = "",
                            ["description"] = "“整只熊？你养了一整只熊？嗯哼？你还在拿它做什么啊？出去！把堡垒夷为平地！让它拿爪子击打些石头！享受熊的毁灭力量吧！”——藤暮游侠格洛雷德尔",
                            ["name"] = "旷野之魂熊",
                            ["id"] = 9683,
                        },
                        [9678] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 7924,
                            ["icon"] = "/esoui/art/icons/mount_soulrazerguar.dds",
                            ["hint"] = "",
                            ["description"] = "“高岛的墓窖里到处都是行走的护甲。幸存下来的人说，护甲保护着远古的宝藏。但我怀疑它们是在黑暗的走廊徘徊，等待死者醒来。”——纳维尔堡的墓窖看守者格罗德",
                            ["name"] = "灭魂瓜尔",
                            ["id"] = 9678,
                        },
                        [9677] = 
                        {
                            ["category"] = "熊",
                            ["furnitureId"] = 7923,
                            ["icon"] = "/esoui/art/icons/mount_soulrazerbear.dds",
                            ["hint"] = "",
                            ["description"] = "“我们知道，一个疯狂的死灵法师用他临终的气息锻造了这些生物。它们毫不留情，即使是仪式长的命令也阻止不了它们。但奇怪的是，一些熊竟然平静地坐在学徒的脚边。”——塞伊克教团伊尔辛",
                            ["name"] = "灭魂熊",
                            ["id"] = 9677,
                        },
                        [9676] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7922,
                            ["icon"] = "/esoui/art/icons/mount_soulrazersenche.dds",
                            ["hint"] = "",
                            ["description"] = "一片片的护甲盘旋在蓝色森切并不存在的皮毛上。它不会发出声音，不会因为追逐的刺激感而咆哮。它在地面上慢慢爬行，因为它知道狩猎一旦开始，任何猎物都逃脱不掉。",
                            ["name"] = "灭魂森切",
                            ["id"] = 9676,
                        },
                        [9645] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7918,
                            ["icon"] = "/esoui/art/icons/pet_glassworkwolfcub.dds",
                            ["hint"] = "",
                            ["description"] = "老狼把自己的铠甲咬成碎片后，赛伊塔恩要塞的训狗员就把训练小狼崽的铠甲作为首要任务。这种做法在这只小狼身上延续了下来，它在主人身边小跑时，会自豪地展示自己的精灵全副护甲。",
