                            ["icon"] = "/esoui/art/icons/pet_catwell.dds",
                            ["hint"] = "",
                            ["description"] = "猫的眼睛似乎在说：“真高兴见到你！我们这里似乎有小啮齿动物疫病。还有可怕的爬行动物到处乱跑。嗯，跳来跳去的疫病。我知道一个关于这件事的好笑笑话。什么？哦，是的。真是个打猎的好天气！”",
                            ["name"] = "卡特维尔",
                            ["id"] = 9577,
                        },
                        [9576] = 
                        {
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 7909,
                            ["icon"] = "/esoui/art/icons/mount_pillionhorse.dds",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t多人坐骑（1个操控者，1个乘客）|r|",
                            ["description"] = "与亲密的朋友或伙伴一起骑在这匹健壮的天际品种挽马上吧！它的鞍座由真正的海象皮革制成，这匹马的驮力可以毫不费力地承载两名骑手。",
                            ["name"] = "豪华后鞍挽马",
                            ["id"] = 9576,
                        },
                        [9575] = 
                        {
                            ["category"] = "矮人蜘蛛",
                            ["furnitureId"] = 7908,
                            ["icon"] = "/esoui/art/icons/mount_coralcrawler.dds",
                            ["hint"] = "",
                            ["description"] = "“这些珊瑚蜘蛛是仅仅模仿矮人蜘蛛，还是说珊瑚生长在了废弃的矮人构造体上？我还没有撬开一个来看看——它们真的不喜欢那样，所以试都不要去试。”——喘鸣的威伦",
                            ["name"] = "珊瑚爬行者矮人蜘蛛",
                            ["id"] = 9575,
                        },
                        [9574] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7907,
                            ["icon"] = "/esoui/art/icons/mount_seaorchardsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“这种生物在蓄潮池周围徘徊，就像树精在陆地的空地上漫步一样。它粗糙的木骨上长满了水生生物。如果它看到我，肯定会撕烂我的喉咙。”——摘自泰尔德丢失的日记",
                            ["name"] = "战争之猫森切狮",
                            ["id"] = 9574,
                        },
