                            ["icon"] = "/esoui/art/icons/mount_welwa.dds",
                            ["hint"] = "",
                            ["description"] = "正如泰姆瑞尔各地的马夫所说的，破坏者确实对得起它的名字，在它和它主人之间会动的东西，它都会破坏掉。学者们推测，冥潭村的蓝色希思特神树催生了这种绿色品种的四目兽。",
                            ["name"] = "纳迦鳞四目兽破坏者",
                            ["id"] = 8159,
                        },
                        [8160] = 
                        {
                            ["category"] = "马",
                            ["furnitureId"] = 7219,
                            ["icon"] = "/esoui/art/icons/mount_radpotentatehorse.dds",
                            ["hint"] = "",
                            ["description"] = "“对，第二纪元30年似乎就是第一匹追云驹出现的时间，但格维林学院的米兰娜记载说这些马是某种幽灵，这就太玄乎了。它们的诞生的确是个谜，我怀疑这个过程中掺杂了魔法。”——欧诺拉塔·安克鲁斯，艾维岛",
                            ["name"] = "首席谋士追云驹",
                            ["id"] = 8160,
                        },
                        [8161] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 7220,
                            ["icon"] = "/esoui/art/icons/mount_potentateradsenche.dds",
                            ["hint"] = "",
                            ["description"] = "“骑过这匹森切之后，我明白为什么米兰娜坚持认为它们是灵体了。她提到的起源时间第二纪元29年跟别人提到的第二纪元35年对不上号……两个都有可能是对的。不管怎么说，这批坐骑的吼叫声充满了魔法的力量，使它的骑乘体验十分难忘！”——欧诺拉塔·安克鲁斯，艾维岛",
                            ["name"] = "首席谋士太平森切",
                            ["id"] = 8161,
                        },
                        [10210] = 
                        {
                            ["category"] = "公羊",
                            ["furnitureId"] = 8260,
                            ["icon"] = "/esoui/art/icons/mount_mottledram.dds",
                            ["hint"] = "",
                            ["description"] = "“强壮的公羊在尼贝内海湾周围茂盛的草地上吃草。一个有趣的说法是，它们最初成为坐骑是因为当地的药草师不想让它们吃掉所有的奈恩根。它们受训接受了鞍具，然后就有了如今这个现状。”——学生萨蒂亚·渥纽斯",
                            ["name"] = "尼贝内海湾公羊",
                            ["id"] = 10210,
                        },
                        [10211] = 
                        {
                            ["category"] = "马",
