                            ["icon"] = "/esoui/art/icons/pet_molagbalseye.dds",
                            ["hint"] = "",
                            ["description"] = "看来并非所有的莫拉格·巴尔之眼都像魔神所期望的那样警觉。这只就展现出了对世界的巨大好奇心！不过，它眨起来确实挺吓人的。",
                            ["name"] = "冷港眼球观察者",
                            ["id"] = 12264,
                        },
                        [10217] = 
                        {
                            ["category"] = "房客",
                            ["furnitureId"] = 8265,
                            ["icon"] = "/esoui/art/icons/houseguest_jesteranglidor.dds",
                            ["hint"] = "",
                            ["description"] = "这个小丑的节日表演者为你的家带来了节日的所有欢乐和闹腾，是你举办友好聚会的完美之选！让小丑昂立多进入你的家，你可以为他设置行动路径，还能和他互动。",
                            ["name"] = "小丑昂立多",
                            ["id"] = 10217,
                        },
                        [12266] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 9821,
                            ["icon"] = "/esoui/art/icons/pet_senchalhornedowl.dds",
                            ["hint"] = "",
                            ["description"] = "“我一直心仪这里的猫头鹰，多么聪明的生物啊。大多都不愿意亲近人，哪怕以零食款待也是如此。不过也有例外，比如呼啼。这名字取得很巧妙吧？哪还有比这更适合宠物猫头鹰的名字呢？”——旅行商人吉玛戈",
                            ["name"] = "森查尔角鸮",
                            ["id"] = 12266,
                        },
                        [10219] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 8266,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_stendarrstatuette001.dds",
                            ["hint"] = "",
                            ["description"] = "慈悲、宽容与正义之神思坦达的微型雕像。",
                            ["name"] = "小雕像：坚定的思坦达",
                            ["id"] = 10219,
                        },
                        [10220] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 8267,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housinghewstatuette001.dds",
                            ["hint"] = "",
                            ["description"] = "尤库达修王子的微型雕像，他也被称为胡巴拉贾德亲王。",
                            ["name"] = "小雕像：修王子",
                            ["id"] = 10220,
                        },
                        [10221] = 
                        {
                            ["category"] = "普通",
                            ["furnitureId"] = 8268,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingcarouselclockworkcity001.dds",
                            ["hint"] = "",
                            ["description"] = "黄铜堡垒的画，那是机械之神索萨希尔的权力所在。",
                            ["name"] = "画：黄铜之门",
                            ["id"] = 10221,
                        },
                        [10222] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 8269,
                            ["icon"] = "/esoui/art/icons/pet_frostmossimp.dds",
                            ["hint"] = "",
                            ["description"] = "“为什么人们非要有小鬼在身边？为什么特别是这种呢？他们会把你让他们做的所有事都歪曲成最有利他们的，而不是你的。只有那些非常坚定的人才应该使用他们。”——迪瓦伊斯·弗雷",
                            ["name"] = "冰甲小恶魔",
                            ["id"] = 10222,
                        },
                        [7518] = 
                        {
                            ["category"] = "瓜尔和盾角蜥",
                            ["furnitureId"] = 6642,
                            ["icon"] = "/esoui/art/icons/mount_cursebondkagouti.dds",
                            ["hint"] = "",
                            ["description"] = "这只残暴的怪物给吟游诗人学院的埃夫诺特大师带来了灵感，于是他写下了《泽恩加纳兹的恐怖红眼》这首诗。事实上，这只坐骑最常选择的是恐吓和逃跑战术，而不是正面对抗。",
                            ["name"] = "咒缚盾角蜥",
                            ["id"] = 7518,
                        },
                        [10224] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 8270,
                            ["icon"] = "/esoui/art/icons/pet_silverstarcavymara.dds",
                            ["hint"] = "",
                            ["description"] = "“豚鼠平静的天性助它们成为了大自然的调和者，亲爱的。这是我一年前收养的。你看，银发有一种不可否认的世故感，不管其本身是不是很有智慧，银发都会给人一种这样的印象。”——阿拉贝勒·德沃克斯女士",
                            ["name"] = "纯银豚鼠",
                            ["id"] = 10224,
                        },
                        [10225] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 8271,
                            ["icon"] = "/esoui/art/icons/mount_bleakrocksnowdog.dds",
                            ["hint"] = "",
                            ["description"] = "这些蓝眼睛的犬科动物最初来自荒岩岛，它们喜欢在那片遥远土地上的寒冷空气中以及雪地里玩耍。事实上，当地人晚上经常把它们带入室内，免得早上被它们的滑稽行为吵醒。",
                            ["name"] = "荒岩雪犬",
                            ["id"] = 10225,
                        },
                        [7271] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6551,
                            ["icon"] = "/esoui/art/icons/pet_hallinsjackal.dds",
                            ["hint"] = "",
                            ["description"] = "在第七军团出现在哈林要塞附近的消息传播开来之后，几位永恒城的民众迅速赶到哈林要塞，以保护一些濒危物种，其中就包括一种极易驯养的胡狼。现在，这种凶猛的伙伴可以陪伴你四处游荡。",
                            ["name"] = "哈林胡狼",
                            ["id"] = 7271,
                        },
                        [7270] = 
                        {
                            ["category"] = "驯养",
                            ["furnitureId"] = 6550,
                            ["icon"] = "/esoui/art/icons/pet_princesspig.dds",
                            ["hint"] = "找到并结合全部七个猪猪公主收藏品碎片获得，这种碎片可在小丑节期间于巨型小丑节礼盒中找到。",
                            ["description"] = "在终于逃脱了可怕的牢笼，并正式嫁给了小丑国王乔伦之后，猪猪公主总算可以陪在你的身边，慢悠悠地踏上冒险之旅了。谁不想要一个像她这样面容端庄，还拥有王室血脉的同伴呢？",
                            ["name"] = "猪猪公主",
                            ["id"] = 7270,
                        },
                        [785] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 4326,
                            ["icon"] = "/esoui/art/icons/pet_093.dds",
                            ["hint"] = "",
                            ["description"] = "“陪伴着受了神秘调谐的凡人们的祖先圣蛾绝非普通的虫子，它们被逝者灵魂中的爱所驱使，给予它们造访之人以智慧和觉悟。”——特兰·阿米努斯修女",
                            ["name"] = "远古圣蛾群",
                            ["id"] = 785,
                        },
                        [786] = 
                        {
                            ["category"] = "飞行",
                            ["furnitureId"] = 4327,
                            ["icon"] = "/esoui/art/icons/pet_104.dds",
                            ["hint"] = "",
                            ["description"] = "木精灵们说，被友好的流萤虫跟着说明要走好运了。当然，他们也会抓流萤虫，把它们晾干，然后放在烟斗里抽。",
                            ["name"] = "忠心流萤虫",
                            ["id"] = 786,
                        },
                        [7111] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 6542,
                            ["icon"] = "/esoui/art/icons/mount_curseboundwolf.dds",
                            ["hint"] = "",
                            ["description"] = "牙齿。很多锋利的牙齿。从牙龈上突出，向后拉出了一个僵硬、扭曲的笑容。急于吞噬在其路径上的任何人。然而如果你有足够的勇气骑乘它，那些可怕的牙齿会热切地咬向你的敌人。",
                            ["name"] = "咒缚恶狼",
                            ["id"] = 7111,
                        },
                        [10231] = 
                        {
                            ["category"] = "大型猫科动物",
                            ["furnitureId"] = 8272,
                            ["icon"] = "/esoui/art/icons/mount_argentsencheserval.dds",
                            ["hint"] = "",
                            ["description"] = "“莫尔纳德家族不肯说出在哪里驯服了这些漂亮的野兽。我猜是在夏暮岛。有一段时间，只有族里年长的贵族才骑自己的珍奇异兽。现在，莫尔纳德的财富下滑后，你会发现泰姆瑞尔到处都是这些生物。”——学生萨蒂亚·渥纽斯",
                            ["name"] = "烬灰森切薮猫",
                            ["id"] = 10231,
                        },
                        [7105] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 6540,
                            ["icon"] = "/esoui/art/icons/pet_pocketmammoth.dds",
                            ["hint"] = "",
                            ["description"] = "虽然这只灰色袖珍猛犸象身上的秘术纹饰表明它是祭品，但这些生物最终往往会追随像你这样内心柔软的人。",
                            ["name"] = "献祭用袖珍猛犸象",
                            ["id"] = 7105,
                        },
                        [8185] = 
                        {
                            ["category"] = "狼",
                            ["furnitureId"] = 7221,
                            ["icon"] = "/esoui/art/icons/mount_potentateradwolf.dds",
                            ["hint"] = "",
                            ["description"] = "“据格维林大学的米兰娜记载，这种墨黑色的坐骑首次出现时间是第二纪元42年，它让我想起了一种秘密仪式，是用来追查雷曼效忠者的。当我琢磨起最近骑着它的一次旅程时，我会不由得感到一阵恐惧。”——欧诺拉塔·安克鲁斯，艾维岛",
                            ["name"] = "首席谋士黯夜狼",
                            ["id"] = 8185,
                        },
                        [8186] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7222,
                            ["icon"] = "/esoui/art/icons/pet_verminousfabricant.dds",
                            ["hint"] = "",
                            ["description"] = "锋利的牙齿，可怕的脊刺还有硕大的角，这只微缩邪恶制造者随从不仅表明了你对这一天中任务的上心程度，还表明了你对索萨希尔精致而又复杂的机械的喜爱。",
                            ["name"] = "微缩害人虫混合体",
                            ["id"] = 8186,
                        },
                        [8187] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7223,
                            ["icon"] = "/esoui/art/icons/pet_glowgillguar.dds",
                            ["hint"] = "",
                            ["description"] = "这些幽暗沼泽瓜尔常常发着微光，对周围的物品和生物嗅个不停。那些和沼泽有联系的人说，他们能感到是沼泽给瓜尔的光提供了来源，但有些学者认为这种发光现象只不过是炼金术反应罢了。",
                            ["name"] = "茶色微光瓜尔",
                            ["id"] = 8187,
                        },
                        [8188] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7224,
                            ["icon"] = "/esoui/art/icons/pet_potentatewolfcub.dds",
                            ["hint"] = "",
                            ["description"] = "“第二纪元4年，威尔西德·谢成立了狼骑手训练团，通过和训练员们交谈，我看到了穿着护甲玩耍着的小狼。它们懒洋洋地躺在地上的样子真的很可爱。很难让人相信它们长大之后会那么凶猛！”——格维林学院的米兰娜",
                            ["name"] = "阿卡维尔首席谋士小狼",
                            ["id"] = 8188,
                        },
                        [8189] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7225,
                            ["icon"] = "/esoui/art/icons/pet_potentatesabrecub.dds",
                            ["hint"] = "",
                            ["description"] = "“在来到天际的那年，也就是第二纪元7年之前，首席谋士训练了一些幼年剑齿虎用于骑乘。多年后看着这些小猫穿着训练战盔发起突袭，差点让我失声尖叫起来。”——格维林学院的米兰娜",
                            ["name"] = "阿卡维尔首席谋士剑齿虎幼崽",
                            ["id"] = 8189,
                        },
                        [8190] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7226,
                            ["icon"] = "/esoui/art/icons/pet_potentatepony.dds",
                            ["hint"] = "",
                            ["description"] = "“第二纪元5年，那些使用威尔西德·谢设计的附魔坐骑护甲的战斗法师们，接收到了一条命令：追杀雷曼效忠者。最开始这些护甲只装备在马匹身上，慢慢地，连同小马还有更多的动物都得到了这些特殊的护甲，接受特殊的训练。”——格维林学院的米兰娜",
                            ["name"] = "阿卡维尔首席谋士小马",
                            ["id"] = 8190,
                        },
                        [8191] = 
                        {
                            ["category"] = "异域",
                            ["furnitureId"] = 7227,
                            ["icon"] = "/esoui/art/icons/pet_potentateguarcalf.dds",
                            ["hint"] = "",
                            ["description"] = "“第二纪元27年，由于红山的威胁，首席谋士首次将瓜尔用作坐骑，但他们只在哀伤之城外面才骑这些坐骑。有一次我去拜访的时候，有一只穿着坐骑护甲的小瓜尔要我拍拍它的鼻子，我抵抗不了这种诱惑。”——格维林学院的米兰娜",
                            ["name"] = "阿卡维尔首席谋士幼年瓜尔",
                            ["id"] = 8191,
                        },
                    },
